// Bukhari, Kitab al-Maghazi, by event in the order of the Mukhtasar (the same list as the site): [chapter, text, number]
export default [["باب غزوة العشيرة أو العسيرة", "حدثني عبد الله بن محمد، حدثنا وهب، حدثنا شعبة، عن أبي إسحاق، كنت إلى جنب زيد بن أرقم، فقيل له: \" كم غزا النبي صلى الله عليه وسلم من غزوة؟ قال: تسع عشرة \" قيل: كم غزوت أنت معه؟ قال: سبع عشرة، قلت: فأيهم كانت أول؟ قال: العسيرة أو العشير \" فذكرت لقتادة فقال: العشير", "3949"], ["باب ذكر النبي صلى الله عليه وسلم من يقتل ببدر", "حدثني أحمد بن عثمان، حدثنا شريح بن مسلمة، حدثنا إبراهيم بن يوسف، عن أبيه، عن أبي إسحاق، قال: حدثني عمرو بن ميمون، أنه سمع عبد الله بن مسعود رضي الله عنه حدث، عن سعد بن معاذ أنه قال: كان صديقا لأمية بن خلف، وكان أمية إذا مر بالمدينة نزل على سعد، وكان سعد إذا مر بمكة نزل على أمية، فلما قدم رسول الله صلى الله عليه وسلم المدينة انطلق سعد معتمرا، فنزل على أمية بمكة، فقال لأمية: انظر لي ساعة خلوة لعلي أن أطوف بالبيت، فخرج به قريبا من نصف النهار، فلقيهما أبو جهل، فقال: يا أبا صفوان، من هذا معك؟ فقال هذا سعد، فقال له أبو جهل: ألا أراك تطوف بمكة آمنا، وقد أويتم الصباة، وزعمتم أنكم تنصرونهم وتعينونهم، أما والله لولا أنك مع أبي صفوان ما رجعت إلى أهلك سالما، فقال له سعد ورفع صوته عليه : أما والله لئن منعتني هذا لأمنعنك ما هو أشد عليك منه، طريقك على المدينة، فقال له أمية: لا ترفع صوتك يا سعد على أبي الحكم، سيد أهل الوادي، فقال سعد: دعنا عنك يا أمية، فوالله لقد سمعت رسول الله صلى الله عليه وسلم يقول: «إنهم قاتلوك»، قال: بمكة؟ قال: لا أدري، ففزع لذلك أمية فزعا شديدا، فلما رجع أمية إلى أهله، قال: يا أم صفوان، ألم تري ما قال لي سعد؟ قالت: وما قال لك؟ قال: زعم أن محمدا أخبرهم أنهم قاتلي، فقلت له: بمكة، قال: لا أدري، فقال أمية: والله لا أخرج من مكة، فلما كان يوم بدر استنفر أبو جهل الناس، قال: أدركوا عيركم؟ فكره أمية أن يخرج، فأتاه أبو جهل فقال: يا أبا صفوان، إنك متى ما يراك الناس قد تخلفت، وأنت سيد أهل الوادي، تخلفوا معك، فلم يزل به أبو جهل حتى قال: أما إذ غلبتني، فوالله لأشترين أجود بعير بمكة، ثم قال أمية: يا أم صفوان جهزيني، فقالت له: يا أبا صفوان، وقد نسيت ما قال لك أخوك اليثربي؟ قال: لا ما أريد أن أجوز معهم إلا قريبا، فلما خرج أمية أخذ لا ينزل منزلا إلا عقل بعيره، فلم يزل بذلك حتى قتله الله عز وجل ببدر \"", "3950"], ["باب قصة غزوة بدر", "حدثني يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عبد الرحمن بن عبد الله بن كعب، أن عبد الله بن كعب، قال: سمعت كعب بن مالك رضي الله عنه، يقول: لم أتخلف عن رسول الله صلى الله عليه وسلم في غزوة غزاها إلا في غزوة تبوك، غير أني تخلفت عن غزوة بدر، ولم يعاتب أحد تخلف عنها، إنما «خرج رسول الله صلى الله عليه وسلم يريد عير قريش، حتى جمع الله بينهم وبين عدوهم على غير ميعاد»", "3951"], ["باب قول الله تعالى {إذ تستغيثون ربكم فاستجاب لكم أني ممدكم بألف من الملائكة مردفين. وما جعله الله إلا بشرى ولتطمئن به قلوبكم وما النصر إلا من عند الله إن الله عزيز حكيم. إذ يغشيكم النعاس أمنة منه وينزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطان وليربط على قلوبكم ويثبت به الأقدام. إذ يوحي ربك إلى الملائكة أني معكم فثبتوا الذين آمنوا سألقي في قلوب الذين كفروا الرعب فاضربوا فوق الأعناق واضربوا منهم كل بنان. ذلك بأنهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فإن الله شديد العقاب} [الأنفال: 10]", "حدثنا أبو نعيم، حدثنا إسرائيل، عن مخارق، عن طارق بن شهاب، قال: سمعت ابن مسعود، يقول: شهدت من المقداد بن الأسود مشهدا، لأن أكون صاحبه أحب إلي مما عدل به، أتى النبي صلى الله عليه وسلم وهو يدعو على المشركين، فقال: لا نقول كما قال قوم موسى: اذهب أنت وربك فقاتلا، ولكنا نقاتل عن يمينك، وعن شمالك، وبين يديك وخلفك «فرأيت النبي صلى الله عليه وسلم أشرق وجهه وسره» يعني: قوله", "3952"], ["باب قول الله تعالى {إذ تستغيثون ربكم فاستجاب لكم أني ممدكم بألف من الملائكة مردفين. وما جعله الله إلا بشرى ولتطمئن به قلوبكم وما النصر إلا من عند الله إن الله عزيز حكيم. إذ يغشيكم النعاس أمنة منه وينزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطان وليربط على قلوبكم ويثبت به الأقدام. إذ يوحي ربك إلى الملائكة أني معكم فثبتوا الذين آمنوا سألقي في قلوب الذين كفروا الرعب فاضربوا فوق الأعناق واضربوا منهم كل بنان. ذلك بأنهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فإن الله شديد العقاب} [الأنفال: 10]", "حدثني محمد بن عبيد الله بن حوشب، حدثنا عبد الوهاب، حدثنا خالد، عن عكرمة، عن ابن عباس، قال: قال النبي صلى الله عليه وسلم يوم بدر: «اللهم إني أنشدك عهدك ووعدك، اللهم إن شئت لم تعبد» فأخذ أبو بكر بيده، فقال: حسبك، فخرج وهو يقول: {سيهزم الجمع ويولون الدبر} [القمر: 45]", "3953"], ["باب", "حدثني إبراهيم بن موسى، أخبرنا هشام، أن ابن جريج، أخبرهم قال: أخبرني عبد الكريم، أنه سمع مقسما، مولى عبد الله بن الحارث، يحدث عن ابن عباس، أنه سمعه يقول: {لا يستوي القاعدون من المؤمنين} [النساء: 95] عن بدر، والخارجون إلى بدر \"", "3954"], ["باب عدة أصحاب بدر", "حدثنا مسلم بن إبراهيم، حدثنا شعبة، عن أبي إسحاق، عن البراء، قال: استصغرت أنا وابن عمر،", "3955"], ["باب عدة أصحاب بدر", "حدثني محمود، حدثنا وهب، عن شعبة، عن أبي إسحاق، عن البراء، قال: «استصغرت أنا وابن عمر يوم بدر، وكان المهاجرون يوم بدر نيفا على ستين، والأنصار نيفا وأربعين ومائتين»", "3956"], ["باب عدة أصحاب بدر", "حدثنا عمرو بن خالد، حدثنا زهير، حدثنا أبو إسحاق، قال: سمعت البراء رضي الله عنه، يقول: حدثني أصحاب محمد صلى الله عليه وسلم ممن شهد بدرا: «أنهم كانوا عدة أصحاب طالوت، الذين جازوا معه النهر، بضعة عشر وثلاث مائة» قال البراء: «لا والله ما جاوز معه النهر إلا مؤمن»", "3957"], ["باب عدة أصحاب بدر", "حدثنا عبد الله بن رجاء، حدثنا إسرائيل، عن أبي إسحاق، عن البراء، قال: كنا أصحاب محمد صلى الله عليه وسلم، نتحدث: «أن عدة أصحاب بدر على عدة أصحاب طالوت الذين جاوزوا معه النهر، ولم يجاوز معه إلا مؤمن بضعة عشر وثلاث مائة»", "3958"], ["باب عدة أصحاب بدر", "حدثني عبد الله بن أبي شيبة، حدثنا يحيى، عن سفيان، عن أبي إسحاق، عن البراء، ح وحدثنا محمد بن كثير، أخبرنا سفيان، عن أبي إسحاق، عن البراء رضي الله عنه، قال: \" كنا نتحدث: أن أصحاب بدر ثلاث مائة وبضعة عشر، بعدة أصحاب طالوت، الذين جاوزوا معه النهر، وما جاوز معه إلا مؤمن \"", "3959"], ["باب دعاء النبي صلى الله عليه وسلم على كفار قريش شيبة، وعتبة، والوليد، وأبي جهل بن هشام، وهلاكهم", "حدثني عمرو بن خالد، حدثنا زهير، حدثنا أبو إسحاق، عن عمرو بن ميمون، عن عبد الله بن مسعود رضي الله عنه، قال: استقبل النبي صلى الله عليه وسلم الكعبة، \" فدعا على نفر من قريش: على شيبة بن ربيعة، وعتبة بن ربيعة، والوليد بن عتبة، وأبي جهل بن هشام، فأشهد بالله، لقد رأيتهم صرعى، قد غيرتهم الشمس، وكان يوما حارا \"", "3960"], ["باب قتل أبي جهل", "حدثنا ابن نمير، حدثنا أبو أسامة، حدثنا إسماعيل، أخبرنا قيس، عن عبد الله رضي الله عنه: \" أنه أتى أبا جهل وبه رمق يوم بدر، فقال: أبو جهل: هل أعمد من رجل قتلتموه \"", "3961"], ["باب قتل أبي جهل", "حدثنا أحمد بن يونس، حدثنا زهير، حدثنا سليمان التيمي، أن أنسا، حدثهم قال: قال النبي صلى الله عليه وسلم: ح وحدثني عمرو بن خالد، حدثنا زهير، عن سليمان التيمي، عن أنس رضي الله عنه، قال: قال النبي صلى الله عليه وسلم: «من ينظر ما صنع أبو جهل». فانطلق ابن مسعود فوجده قد ضربه ابنا عفراء حتى برد، قال: أأنت، أبو جهل؟ قال: فأخذ بلحيته، قال: وهل فوق رجل قتلتموه، أو رجل قتله قومه قال أحمد بن يونس: «أنت أبو جهل»", "3962"], ["باب قتل أبي جهل", "حدثني محمد بن المثنى، حدثنا ابن أبي عدي، عن سليمان التيمي، عن أنس رضي الله عنه، قال: قال النبي صلى الله عليه وسلم يوم بدر: «من ينظر ما فعل أبو جهل». فانطلق ابن مسعود فوجده قد ضربه ابنا عفراء حتى برد فأخذ بلحيته، فقال: أنت أبا جهل؟ قال: وهل فوق رجل قتله قومه أو قال: قتلتموه، حدثني ابن المثنى، أخبرنا معاذ بن معاذ، حدثنا سليمان، أخبرنا أنس بن مالك نحوه،", "3963"], ["باب قتل أبي جهل", "حدثنا علي بن عبد الله، قال: كتبت عن يوسف بن الماجشون، عن صالح بن إبراهيم، عن أبيه، عن جده في بدر يعني حديث ابني عفراء", "3964"], ["باب قتل أبي جهل", "حدثني محمد بن عبد الله الرقاشي، حدثنا معتمر، قال: سمعت أبي يقول: حدثنا أبو مجلز، عن قيس بن عباد، عن علي بن أبي طالب رضي الله عنه، أنه قال: «أنا أول من يجثو بين يدي الرحمن للخصومة يوم القيامة» وقال قيس بن عباد: وفيهم أنزلت: {هذان خصمان اختصموا في ربهم} [الحج: 19] قال: \" هم الذين تبارزوا يوم بدر: حمزة، وعلي، وعبيدة، أو أبو عبيدة بن الحارث، وشيبة بن ربيعة، وعتبة بن ربيعة، والوليد بن عتبة \"", "3965"], ["باب قتل أبي جهل", "حدثنا قبيصة، حدثنا سفيان، عن أبي هاشم، عن أبي مجلز، عن قيس بن عباد، عن أبي ذر رضي الله عنه، قال: نزلت: {هذان خصمان اختصموا} [الحج: 19] في ربهم في ستة من قريش: علي، وحمزة، وعبيدة بن الحارث، وشيبة بن ربيعة، وعتبة بن ربيعة، والوليد بن عتبة \"", "3966"], ["باب قتل أبي جهل", "حدثنا إسحاق بن إبراهيم الصواف، حدثنا يوسف بن يعقوب، كان ينزل في بني ضبيعة، وهو مولى لبني سدوس، حدثنا سليمان التيمي، عن أبي مجلز، عن قيس بن عباد، قال: قال علي رضي الله عنه: فينا نزلت هذه الآية: {هذان خصمان اختصموا في ربهم} [الحج: 19]", "3967"], ["باب قتل أبي جهل", "حدثنا يحيى بن جعفر، أخبرنا وكيع، عن سفيان، عن أبي هاشم، عن أبي مجلز، عن قيس بن عباد، سمعت أبا ذر رضي الله عنه يقسم: \" لنزلت هؤلاء الآيات، في هؤلاء الرهط الستة يوم بدر نحوه", "3968"], ["باب قتل أبي جهل", "حدثنا يعقوب بن إبراهيم الدورقي، حدثنا هشيم، أخبرنا أبو هاشم، عن أبي مجلز، عن قيس بن عباد، قال: سمعت أبا ذر، يقسم قسما: إن هذه الآية: {هذان خصمان اختصموا في ربهم} [الحج: 19] نزلت في الذين برزوا يوم بدر: حمزة، وعلي، وعبيدة بن الحارث، وعتبة، وشيبة، ابني ربيعة، والوليد بن عتبة \"", "3969"], ["باب قتل أبي جهل", "حدثني أحمد بن سعيد أبو عبد الله، حدثنا إسحاق بن منصور السلولي، حدثنا إبراهيم بن يوسف، عن أبيه، عن أبي إسحاق، سأل رجل البراء وأنا أسمع، قال: أشهد علي بدرا قال: «بارز وظاهر»", "3970"], ["باب قتل أبي جهل", "حدثنا عبد العزيز بن عبد الله، قال: حدثني يوسف بن الماجشون، عن صالح بن إبراهيم بن عبد الرحمن بن عوف، عن أبيه، عن جده عبد الرحمن، قال: كاتبت أمية بن خلف، فلما كان يوم بدر، فذكر قتله وقتل ابنه، فقال بلال: «لا نجوت إن نجا أمية»", "3971"], ["باب قتل أبي جهل", "حدثنا عبدان بن عثمان، قال: أخبرني أبي، عن شعبة، عن أبي إسحاق، عن الأسود، عن عبد الله رضي الله عنه، عن النبي صلى الله عليه وسلم: أنه قرأ والنجم فسجد بها، وسجد من معه، غير أن شيخا أخذ كفا من تراب فرفعه إلى جبهته، فقال: يكفيني هذا \" قال عبد الله: فلقد رأيته بعد قتل كافرا", "3972"], ["باب قتل أبي جهل", "أخبرني إبراهيم بن موسى، حدثنا هشام بن يوسف، عن معمر، أخبرنا هشام، عن عروة قال: «كان في الزبير ثلاث ضربات بالسيف إحداهن في عاتقه» قال: «إن كنت لأدخل أصابعي فيها» قال: «ضرب ثنتين يوم بدر، وواحدة يوم اليرموك» قال عروة: وقال لي عبد الملك بن مروان، حين قتل عبد الله بن الزبير: يا عروة، هل تعرف سيف الزبير؟ قلت: «نعم» قال: فما فيه؟ قلت: «فيه فلة فلها يوم بدر» قال: صدقت، [البحر الطويل] بهن فلول من قراع الكتائب ، ثم رده على عروة، قال هشام: فأقمناه بيننا ثلاثة آلاف، وأخذه بعضنا، ولوددت أني كنت أخذته", "3973"], ["باب قتل أبي جهل", "حدثنا فروة، حدثنا علي، عن هشام، عن أبيه، قال: «كان سيف الزبير بن العوام محلى بفضة» قال هشام: وكان سيف عروة محلى بفضة", "3974"], ["باب قتل أبي جهل", "حدثنا أحمد بن محمد، حدثنا عبد الله، أخبرنا هشام بن عروة، عن أبيه، أن أصحاب رسول الله صلى الله عليه وسلم، قالوا للزبير يوم اليرموك: ألا تشد فنشد معك؟ فقال: \" إني إن شددت كذبتم، فقالوا: لا نفعل، فحمل عليهم حتى شق صفوفهم، فجاوزهم وما معه أحد، ثم رجع مقبلا، فأخذوا بلجامه، فضربوه ضربتين على عاتقه، بينهما ضربة ضربها يوم بدر، قال عروة: «كنت أدخل أصابعي في تلك الضربات ألعب وأنا صغير» قال عروة: «وكان معه عبد الله بن الزبير يومئذ وهو ابن عشر سنين فحمله على فرس ووكل به رجلا»", "3975"], ["باب قتل أبي جهل", "حدثني عبد الله بن محمد، سمع روح بن عبادة، حدثنا سعيد بن أبي عروبة، عن قتادة، قال: ذكر لنا أنس بن مالك، عن أبي طلحة، أن نبي الله صلى الله عليه وسلم أمر يوم بدر بأربعة وعشرين رجلا من صناديد قريش، فقذفوا في طوي من أطواء بدر خبيث مخبث، وكان إذا ظهر على قوم أقام بالعرصة ثلاث ليال، فلما كان ببدر اليوم الثالث أمر براحلته فشد عليها رحلها، ثم مشى واتبعه أصحابه، وقالوا: ما نرى ينطلق إلا لبعض حاجته، حتى قام على شفة الركي، فجعل يناديهم بأسمائهم وأسماء آبائهم: «يا فلان بن فلان، ويا فلان بن فلان، أيسركم أنكم أطعتم الله ورسوله، فإنا قد وجدنا ما وعدنا ربنا حقا، فهل وجدتم ما وعد ربكم حقا؟» قال: فقال عمر: يا رسول الله، ما تكلم من أجساد لا أرواح لها؟ فقال رسول الله صلى الله عليه وسلم: «والذي نفس محمد بيده، ما أنتم بأسمع لما أقول منهم»، قال قتادة: أحياهم الله حتى أسمعهم، قوله توبيخا وتصغيرا ونقيمة وحسرة وندما", "3976"], ["باب قتل أبي جهل", "حدثنا الحميدي، حدثنا سفيان، حدثنا عمرو، عن عطاء، عن ابن عباس رضي الله عنهما: {الذين بدلوا نعمة الله كفرا} [إبراهيم: 28]. قال: «هم والله كفار قريش» قال عمرو: هم قريش، ومحمد صلى الله عليه وسلم نعمة الله {وأحلوا قومهم دار البوار} [إبراهيم: 28] قال: «النار، يوم بدر»", "3977"], ["باب قتل أبي جهل", "حدثني عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، قال: ذكر عند عائشة رضي الله عنها، أن ابن عمر رفع إلى النبي صلى الله عليه وسلم: «إن الميت يعذب في قبره ببكاء أهله» فقالت: وهل؟ إنما قال رسول الله صلى الله عليه وسلم: «إنه ليعذب بخطيئته وذنبه، وإن أهله ليبكون عليه الآن»، قالت: وذاك مثل قوله: إن رسول الله صلى الله عليه وسلم قام على القليب وفيه قتلى بدر من المشركين، فقال لهم ما قال: «إنهم ليسمعون ما أقول» إنما قال: «إنهم الآن ليعلمون أن ما كنت أقول لهم حق»، ثم قرأت {إنك لا تسمع الموتى} [النمل: 80]، {وما أنت بمسمع من في القبور} [فاطر: 22] يقول حين تبوءوا مقاعدهم من النار", "3978"], ["باب قتل أبي جهل", "حدثني عثمان، حدثنا عبدة، عن هشام، عن أبيه، عن ابن عمر رضي الله عنهما، قال: وقف النبي صلى الله عليه وسلم على قليب بدر فقال: «هل وجدتم ما وعد ربكم حقا» ثم قال: «إنهم الآن يسمعون ما أقول»، فذكر لعائشة، فقالت: إنما قال النبي صلى الله عليه وسلم: «إنهم الآن ليعلمون أن الذي كنت أقول لهم هو الحق» ثم قرأت {إنك لا تسمع الموتى} [النمل: 80] حتى قرأت الآية", "3980"], ["باب فضل من شهد بدرا", "حدثني عبد الله بن محمد، حدثنا معاوية بن عمرو، حدثنا أبو إسحاق، عن حميد، قال: سمعت أنسا رضي الله عنه، يقول: أصيب حارثة يوم بدر وهو غلام، فجاءت أمه إلى النبي صلى الله عليه وسلم فقالت: يا رسول الله، قد عرفت منزلة حارثة مني، فإن يكن في الجنة أصبر وأحتسب، وإن تك الأخرى ترى ما أصنع، فقال: «ويحك، أوهبلت، أوجنة واحدة هي، إنها جنان كثيرة، وإنه في جنة الفردوس»", "3982"], ["باب فضل من شهد بدرا", "حدثني إسحاق بن إبراهيم، أخبرنا عبد الله بن إدريس، قال: سمعت حصين بن عبد الرحمن، عن سعد بن عبيدة، عن أبي عبد الرحمن السلمي، عن علي رضي الله عنه، قال: بعثني رسول الله صلى الله عليه وسلم وأبا مرثد الغنوي، والزبير بن العوام، وكلنا فارس، قال: «انطلقوا حتى تأتوا روضة خاخ، فإن بها امرأة من المشركين، معها كتاب من حاطب بن أبي بلتعة إلى المشركين» فأدركناها تسير على بعير لها، حيث قال رسول الله صلى الله عليه وسلم، فقلنا: الكتاب، فقالت: ما معنا كتاب، فأنخناها فالتمسنا فلم نر كتابا، فقلنا: ما كذب رسول الله صلى الله عليه وسلم، لتخرجن الكتاب أو لنجردنك، فلما رأت الجد أهوت الى حجزتها، وهي محتجزة بكساء، فأخرجته، فانطلقنا بها إلى رسول الله صلى الله عليه وسلم، فقال عمر: يا رسول الله، قد خان الله ورسوله والمؤمنين، فدعني فلأضرب عنقه، فقال النبي صلى الله عليه وسلم: «ما حملك على ما صنعت» قال حاطب: والله ما بي أن لا أكون مؤمنا بالله ورسوله صلى الله عليه وسلم، أردت أن يكون لي عند القوم يد يدفع الله بها عن أهلي ومالي، وليس أحد من أصحابك إلا له هناك من عشيرته من يدفع الله به عن أهله وماله، فقال النبي صلى الله عليه وسلم: «صدق ولا تقولوا له إلا خيرا» فقال عمر: إنه قد خان الله ورسوله والمؤمنين، فدعني فلأضرب عنقه، فقال: «أليس من أهل بدر؟» فقال: \" لعل الله اطلع إلى أهل بدر؟ فقال: اعملوا ما شئتم، فقد وجبت لكم الجنة، أو: فقد غفرت لكم \" فدمعت عينا عمر، وقال: الله ورسوله أعلم", "3983"], ["باب", "حدثني عبد الله بن محمد الجعفي، حدثنا أبو أحمد الزبيري، حدثنا عبد الرحمن بن الغسيل، عن حمزة بن أبي أسيد، والزبير بن المنذر بن أبي أسيد، عن أبي أسيد رضي الله عنه، قال: قال لنا رسول الله صلى الله عليه وسلم يوم بدر: «إذا أكثبوكم فارموهم، واستبقوا نبلكم»", "3984"], ["باب", "حدثني محمد بن عبد الرحيم، حدثنا أبو أحمد الزبيري، حدثنا عبد الرحمن بن الغسيل، عن حمزة بن أبي أسيد، والمنذر بن أبي أسيد، عن أبي أسيد رضي الله عنه، قال: قال لنا رسول الله صلى الله عليه وسلم يوم بدر: «إذا أكثبوكم - يعني كثروكم - فارموهم، واستبقوا نبلكم»", "3985"], ["باب", "حدثني عمرو بن خالد، حدثنا زهير، حدثنا أبو إسحاق، قال: سمعت البراء بن عازب رضي الله عنهما، قال: \" جعل النبي صلى الله عليه وسلم على الرماة يوم أحد عبد الله بن جبير، فأصابوا منا سبعين، وكان النبي صلى الله عليه وسلم وأصحابه أصابوا من المشركين يوم بدر أربعين ومائة، سبعين أسيرا، وسبعين قتيلا قال أبو سفيان: يوم بيوم بدر والحرب سجال", "3986"], ["باب", "حدثني محمد بن العلاء، حدثنا أبو أسامة، عن بريد، عن جده أبي بردة، عن أبي موسى، أراه عن النبي صلى الله عليه وسلم، قال: «وإذا الخير ما جاء الله به من الخير بعد، وثواب الصدق الذي آتانا بعد يوم بدر»", "3987"], ["باب", "حدثني يعقوب بن إبراهيم، حدثنا إبراهيم بن سعد، عن أبيه، عن جده، قال: قال عبد الرحمن بن عوف: \" إني لفي الصف يوم بدر إذ التفت فإذا عن يميني وعن يساري فتيان حديثا السن، فكأني لم آمن بمكانهما، إذ قال لي أحدهما سرا من صاحبه: يا عم أرني أبا جهل، فقلت: يا ابن أخي، وما تصنع به؟ قال: عاهدت الله إن رأيته أن أقتله أو أموت دونه، فقال لي الآخر سرا من صاحبه مثله، قال: فما سرني أني بين رجلين مكانهما، فأشرت لهما إليه، فشدا عليه مثل الصقرين حتى ضرباه، وهما ابنا عفراء \"", "3988"], ["باب", "حدثنا موسى بن إسماعيل، حدثنا إبراهيم، أخبرنا ابن شهاب، قال: أخبرني عمر بن أسيد بن جارية الثقفي، حليف بني زهرة، وكان من أصحاب أبي هريرة، عن أبي هريرة رضي الله عنه، قال: «بعث رسول الله صلى الله عليه وسلم عشرة عينا، وأمر عليهم عاصم بن ثابت الأنصاري جد عاصم بن عمر بن الخطاب» حتى إذا كانوا بالهدة بين عسفان، ومكة ذكروا لحي من هذيل يقال لهم بنو لحيان، فنفروا لهم بقريب من مائة رجل رام، فاقتصوا آثارهم حتى وجدوا مأكلهم التمر في منزل نزلوه، فقالوا: تمر يثرب، فاتبعوا آثارهم، فلما حس بهم عاصم وأصحابه لجئوا إلى موضع فأحاط بهم القوم، فقالوا لهم: انزلوا فأعطوا بأيديكم، ولكم العهد والميثاق: أن لا نقتل منكم أحدا، فقال عاصم بن ثابت: أيها القوم: أما أنا فلا أنزل في ذمة كافر، ثم قال: اللهم أخبر عنا نبيك صلى الله عليه وسلم، فرموهم بالنبل فقتلوا عاصما، ونزل إليهم ثلاثة نفر على العهد والميثاق، منهم خبيب، وزيد بن الدثنة، ورجل آخر، فلما استمكنوا منهم أطلقوا أوتار قسيهم، فربطوهم بها، قال الرجل الثالث: هذا أول الغدر، والله لا أصحبكم، إن لي بهؤلاء أسوة، يريد القتلى، فجرروه وعالجوه فأبى أن يصحبهم، فانطلق بخبيب، وزيد بن الدثنة حتى باعوهما بعد وقعة بدر، فابتاع بنو الحارث بن عامر بن نوفل خبيبا، وكان خبيب هو قتل الحارث بن عامر يوم بدر، فلبث خبيب عندهم أسيرا حتى أجمعوا قتله، فاستعار من بعض بنات الحارث موسى يستحد بها فأعارته، فدرج بني لها وهي غافلة حتى أتاه، فوجدته مجلسه على فخذه والموسى بيده، قالت: ففزعت فزعة عرفها خبيب، فقال: أتخشين أن أقتله؟ ما كنت لأفعل ذلك، قالت: والله ما رأيت أسيرا قط خيرا من خبيب، والله لقد وجدته يوما يأكل قطفا من عنب في يده، وإنه لموثق بالحديد، وما بمكة من ثمرة، وكانت تقول: إنه لرزق رزقه الله خبيبا، فلما خرجوا به من الحرم ليقتلوه في الحل، قال لهم خبيب: دعوني أصلي ركعتين، فتركوه فركع ركعتين، فقال: والله لولا أن تحسبوا أن ما بي جزع لزدت، ثم قال: اللهم أحصهم عددا، واقتلهم بددا، ولا تبق منهم أحدا، ثم أنشأ يقول [البحر الطويل] فلست أبالي حين أقتل مسلما ... على أي جنب كان لله مصرعي وذلك في ذات الإله وإن يشأ ... يبارك على أوصال شلو ممزع ثم قام إليه أبو سروعة عقبة بن الحارث فقتله، وكان خبيب هو سن لكل مسلم قتل صبرا الصلاة، وأخبر أصحابه يوم أصيبوا خبرهم، وبعث ناس من قريش إلى عاصم بن ثابت - حين حدثوا أنه قتل - أن يؤتوا بشيء منه يعرف، وكان قتل رجلا عظيما من عظمائهم، فبعث الله لعاصم مثل الظلة من الدبر، فحمته من رسلهم، فلم يقدروا أن يقطعوا منه شيئا وقال كعب بن مالك: «ذكروا مرارة بن الربيع العمري، وهلال بن أمية الواقفي، رجلين صالحين قد شهدا بدرا»", "3989"], ["باب", "حدثنا قتيبة بن سعيد، حدثنا ليث، عن يحيى، عن نافع، أن ابن عمر رضي الله عنهما، ذكر له: أن سعيد بن زيد بن عمرو بن نفيل، وكان بدريا، مرض في يوم جمعة، فركب إليه بعد أن تعالى النهار، واقتربت الجمعة، وترك الجمعة،", "3990"], ["باب", "وقال الليث: حدثني يونس، عن ابن شهاب، قال: حدثني عبيد الله بن عبد الله بن عتبة، أن أباه كتب إلى عمر بن عبد الله بن الأرقم الزهري: يأمره أن يدخل على سبيعة بنت الحارث الأسلمية، فيسألها عن حديثها، وعن ما قال لها رسول الله صلى الله عليه وسلم حين استفتته. فكتب عمر بن عبد الله بن الأرقم، إلى عبد الله بن عتبة، يخبره أن سبيعة بنت الحارث أخبرته: أنها كانت تحت سعد ابن خولة، وهو من بني عامر بن لؤي، وكان ممن شهد بدرا، فتوفي عنها في حجة الوداع وهي حامل، فلم تنشب أن وضعت حملها بعد وفاته، فلما تعلت من نفاسها، تجملت للخطاب، فدخل عليها أبو السنابل بن بعكك، رجل من بني عبد الدار، فقال لها: ما لي أراك تجملت للخطاب، ترجين النكاح؟ فإنك والله ما أنت بناكح حتى تمر عليك أربعة أشهر وعشر، قالت سبيعة: فلما قال لي ذلك جمعت علي ثيابي حين أمسيت، وأتيت رسول الله صلى الله عليه وسلم فسألته عن ذلك «فأفتاني بأني قد حللت حين وضعت حملي، وأمرني بالتزوج إن بدا لي» تابعه أصبغ، عن ابن وهب، عن يونس، وقال الليث: حدثني يونس، عن ابن شهاب وسألناه فقال: أخبرني محمد بن عبد الرحمن بن ثوبان، مولى بني عامر بن لؤي، أن محمد بن إياس بن البكير وكان أبوه شهد بدرا، أخبره", "3991"], ["باب شهود الملائكة بدرا", "حدثني إسحاق بن إبراهيم، أخبرنا جرير، عن يحيى بن سعيد، عن معاذ بن رفاعة بن رافع الزرقي، عن أبيه، وكان أبوه من أهل بدر قال: جاء جبريل إلى النبي صلى الله عليه وسلم، فقال: \" ما تعدون أهل بدر فيكم، قال: من أفضل المسلمين أو كلمة نحوها، قال: وكذلك من شهد بدرا من الملائكة \"", "3992"], ["باب شهود الملائكة بدرا", "حدثنا سليمان بن حرب، حدثنا حماد، عن يحيى ، عن معاذ بن رفاعة بن رافع، وكان رفاعة من أهل بدر، وكان رافع من أهل العقبة، فكان يقول لابنه: ما يسرني أني شهدت بدرا، بالعقبة قال: سأل جبريل النبي صلى الله عليه وسلم بهذا \"", "3993"], ["باب شهود الملائكة بدرا", "حدثنا إسحاق بن منصور، أخبرنا يزيد، أخبرنا يحيى، سمع معاذ بن رفاعة، أن ملكا سأل النبي صلى الله عليه وسلم نحوه، وعن يحيى، أن يزيد بن الهاد، أخبره أنه كان معه يوم حدثه معاذ هذا الحديث فقال يزيد: فقال معاذ: «إن السائل هو جبريل عليه السلام»", "3994"], ["باب شهود الملائكة بدرا", "حدثني إبراهيم بن موسى، أخبرنا عبد الوهاب، حدثنا خالد، عن عكرمة، عن ابن عباس رضي الله عنهما، أن النبي صلى الله عليه وسلم قال يوم بدر: «هذا جبريل، آخذ برأس فرسه، عليه أداة الحرب»", "3995"], ["باب", "حدثني خليفة، حدثنا محمد بن عبد الله الأنصاري، حدثنا سعيد، عن قتادة، عن أنس رضي الله عنه قال: «مات أبو زيد، ولم يترك عقبا، وكان بدريا»", "3996"], ["باب", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني يحيى بن سعيد، عن القاسم بن محمد، عن ابن خباب، أن أبا سعيد بن مالك الخدري رضي الله عنه، قدم من سفر، فقدم إليه أهله لحما من لحوم الأضحى، فقال: ما أنا بآكله حتى أسأل، فانطلق إلى أخيه لأمه، وكان بدريا، قتادة بن النعمان، فسأله فقال: «إنه حدث بعدك أمر، نقض لما كانوا ينهون عنه من أكل لحوم الأضحى بعد ثلاثة أيام»", "3997"], ["باب", "حدثني عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام بن عروة، عن أبيه، قال: قال الزبير: لقيت يوم بدر عبيدة بن سعيد بن العاص، وهو مدجج، لا يرى منه إلا عيناه، وهو يكنى أبو ذات الكرش، فقال: أنا أبو ذات الكرش، فحملت عليه بالعنزة فطعنته في عينه فمات، قال هشام: - فأخبرت: أن الزبير قال: - لقد وضعت رجلي عليه، ثم تمطأت، فكان الجهد أن نزعتها وقد انثنى طرفاها، قال عروة: «فسأله إياها رسول الله صلى الله عليه وسلم فأعطاه، فلما قبض رسول الله صلى الله عليه وسلم أخذها» ثم طلبها أبو بكر فأعطاه، فلما قبض أبو بكر، سألها إياه عمر فأعطاه إياها، فلما قبض عمر أخذها، ثم طلبها عثمان منه فأعطاه إياها، فلما قتل عثمان وقعت عند آل علي، فطلبها عبد الله بن الزبير، فكانت عنده حتى قتل \"", "3998"], ["باب", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني أبو إدريس عائذ الله بن عبد الله، أن عبادة بن الصامت، وكان شهد بدرا أن رسول الله صلى الله عليه وسلم، قال: «بايعوني»", "3999"], ["باب", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، أخبرني عروة بن الزبير، عن عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم: أن أبا حذيفة، وكان ممن شهد بدرا مع رسول الله صلى الله عليه وسلم، تبنى سالما، وأنكحه بنت أخيه هند بنت الوليد بن عتبة، وهو مولى لامرأة من الأنصار، كما «تبنى رسول الله صلى الله عليه وسلم زيدا» وكان من تبنى رجلا في الجاهلية دعاه الناس إليه وورث من ميراثه، حتى أنزل الله تعالى: {ادعوهم لآبائهم} [الأحزاب: 5]. فجاءت سهلة النبي صلى الله عليه وسلم \" فذكر الحديث", "4000"], ["باب", "حدثنا علي، حدثنا بشر بن المفضل، حدثنا خالد بن ذكوان، عن الربيع بنت معوذ، قالت: دخل علي النبي صلى الله عليه وسلم غداة بني علي، فجلس على فراشي كمجلسك مني، وجويريات يضربن بالدف، يندبن من قتل من آبائهن يوم بدر، حتى قالت جارية: وفينا نبي يعلم ما في غد. فقال النبي صلى الله عليه وسلم: «لا تقولي هكذا وقولي ما كنت تقولين»", "4001"], ["باب", "حدثنا إبراهيم بن موسى، أخبرنا هشام، عن معمر، عن الزهري، ح حدثنا إسماعيل، قال: حدثني أخي، عن سليمان، عن محمد بن أبي عتيق، عن ابن شهاب، عن عبيد الله بن عبد الله بن عتبة بن مسعود، أن ابن عباس رضي الله عنهما، قال: أخبرني أبو طلحة رضي الله عنه، صاحب رسول الله صلى الله عليه وسلم وكان قد شهد بدرا مع رسول الله صلى الله عليه وسلم، أنه قال: «لا تدخل الملائكة بيتا فيه كلب ولا صورة» يريد التماثيل التي فيها الأرواح", "4002"], ["باب", "حدثنا عبدان، أخبرنا عبد الله، أخبرنا يونس، ح وحدثنا أحمد بن صالح، حدثنا عنبسة، حدثنا يونس، عن الزهري، أخبرنا علي بن حسين، أن حسين بن علي عليهم السلام، أخبره أن عليا قال: كانت لي شارف من نصيبي من المغنم يوم بدر، وكان النبي صلى الله عليه وسلم أعطاني مما أفاء الله عليه من الخمس يومئذ، فلما أردت أن أبتني بفاطمة عليها السلام، بنت النبي صلى الله عليه وسلم، واعدت رجلا صواغا في بني قينقاع أن يرتحل معي، فنأتي بإذخر، فأردت أن أبيعه من الصواغين، فنستعين به في وليمة عرسي، فبينا أنا أجمع لشارفي من الأقتاب والغرائر والحبال، وشارفاي مناخان إلى جنب حجرة رجل من الأنصار، حتى جمعت ما جمعت، فإذا أنا بشارفي قد أجبت أسنمتها، وبقرت خواصرهما، وأخذ من أكبادهما، فلم أملك عيني حين رأيت المنظر، قلت: من فعل هذا؟ قالوا فعله حمزة بن عبد المطلب، وهو في هذا البيت، في شرب من الأنصار، عنده قينة وأصحابه، فقالت في غنائها: [البحر الوافر] ألا يا حمز للشرف النواء، فوثب حمزة إلى السيف، فأجب أسنمتهما وبقر خواصرهما، وأخذ من أكبادهما، قال علي: فانطلقت حتى أدخل على النبي صلى الله عليه وسلم، وعنده زيد بن حارثة، وعرف النبي صلى الله عليه وسلم الذي لقيت، فقال: «ما لك» قلت: يا رسول الله، ما رأيت كاليوم، عدا حمزة على ناقتي، فأجب أسنمتهما، وبقر خواصرهما، وها هو ذا في بيت معه شرب، فدعا النبي صلى الله عليه وسلم بردائه فارتدى، ثم انطلق يمشي، واتبعته أنا وزيد بن حارثة، حتى جاء البيت الذي فيه حمزة، فاستأذن عليه، فأذن له، فطفق النبي صلى الله عليه وسلم يلوم حمزة فيما فعل، فإذا حمزة ثمل، محمرة عيناه، فنظر حمزة إلى النبي صلى الله عليه وسلم ثم صعد النظر فنظر إلى ركبته، ثم صعد النظر فنظر إلى وجهه، ثم قال حمزة: وهل أنتم إلا عبيد لأبي، فعرف النبي صلى الله عليه وسلم أنه ثمل فنكص رسول الله صلى الله عليه وسلم على عقبيه القهقرى فخرج وخرجنا معه", "4003"], ["باب", "حدثني محمد بن عباد، أخبرنا ابن عيينة، قال: أنفذه لنا ابن الأصبهاني، سمعه من ابن معقل، أن عليا رضي الله عنه، كبر على سهل بن حنيف فقال: «إنه شهد بدرا»", "4004"], ["باب", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني سالم بن عبد الله، أنه سمع عبد الله بن عمر رضي الله عنهما، يحدث: أن عمر بن الخطاب، حين تأيمت حفصة بنت عمر من خنيس بن حذافة السهمي، وكان من أصحاب رسول الله صلى الله عليه وسلم قد شهد بدرا، توفي بالمدينة، قال عمر: فلقيت عثمان بن عفان، فعرضت عليه حفصة، فقلت: إن شئت أنكحتك حفصة بنت عمر، قال: سأنظر في أمري، فلبثت ليالي، فقال: قد بدا لي أن لا أتزوج يومي هذا، قال عمر: فلقيت أبا بكر، فقلت: إن شئت أنكحتك حفصة بنت عمر، فصمت أبو بكر فلم يرجع إلي شيئا، فكنت عليه أوجد مني على عثمان، فلبثت ليالي ثم «خطبها رسول الله صلى الله عليه وسلم فأنكحتها إياه» فلقيني أبو بكر فقال: لعلك وجدت علي حين عرضت علي حفصة فلم أرجع إليك؟ قلت: نعم، قال: فإنه لم يمنعني أن أرجع إليك فيما عرضت، إلا أني قد علمت أن رسول الله صلى الله عليه وسلم قد ذكرها، فلم أكن لأفشي سر رسول الله صلى الله عليه وسلم، ولو تركها لقبلتها", "4005"], ["باب", "حدثنا مسلم، حدثنا شعبة، عن عدي، عن عبد الله بن يزيد، سمع أبا مسعود البدري، عن النبي صلى الله عليه وسلم، قال: «نفقة الرجل على أهله صدقة»", "4006"], ["باب", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، سمعت عروة بن الزبير، يحدث عمر بن عبد العزيز في إمارته: أخر المغيرة بن شعبة العصر، وهو أمير الكوفة، فدخل عليه أبو مسعود عقبة بن عمرو الأنصاري، جد زيد بن حسن، شهد بدرا، فقال: لقد علمت: نزل جبريل فصلى، فصلى رسول الله صلى الله عليه وسلم خمس صلوات، ثم قال: «هكذا أمرت» كذلك كان بشير بن أبي مسعود، يحدث عن أبيه", "4007"], ["باب", "حدثنا موسى، حدثنا أبو عوانة، عن الأعمش، عن إبراهيم، عن عبد الرحمن بن يزيد، عن علقمة، عن أبي مسعود البدري رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: «الآيتان من آخر سورة البقرة، من قرأهما في ليلة كفتاه»، قال عبد الرحمن: فلقيت أبا مسعود وهو يطوف بالبيت فسألته فحدثنيه", "4008"], ["باب", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، أخبرني محمود بن الربيع، «أن عتبان بن مالك، وكان من أصحاب النبي صلى الله عليه وسلم ممن شهد بدرا من الأنصار، أنه أتى رسول الله صلى الله عليه وسلم»،", "4009"], ["باب", "حدثنا أحمد هو ابن صالح، حدثنا عنبسة، حدثنا يونس، قال: ابن شهاب، ثم سألت الحصين بن محمد، وهو أحد بني سالم وهو من سراتهم، عن حديث محمود بن الربيع، عن عتبان بن مالك فصدقه", "4010"], ["باب", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني عبد الله بن عامر بن ربيعة، وكان من أكبر بني عدي، وكان أبوه شهد بدرا مع النبي صلى الله عليه وسلم: أن عمر «استعمل قدامة بن مظعون على البحرين، وكان شهد بدرا، وهو خال عبد الله بن عمر، وحفصة رضي الله عنهم»", "4011"], ["باب", "حدثنا عبد الله بن محمد بن أسماء، حدثنا جويرية، عن مالك، عن الزهري، أن سالم بن عبد الله، أخبره قال: أخبر رافع بن خديج عبد الله بن عمر، أن عميه، وكانا شهدا بدرا، أخبراه أن رسول الله صلى الله عليه وسلم: \" نهى عن كراء المزارع قلت لسالم: فتكريها أنت؟ قال: «نعم، إن رافعا أكثر على نفسه»", "4012"], ["باب", "حدثنا آدم، حدثنا شعبة، عن حصين بن عبد الرحمن قال: سمعت عبد الله بن شداد بن الهاد الليثي قال: «رأيت رفاعة بن رافع الأنصاري وكان شهد بدرا»", "4014"], ["باب", "حدثنا عبدان، أخبرنا عبد الله، أخبرنا معمر، ويونس، عن الزهري، عن عروة بن الزبير، أنه أخبره أن المسور بن مخرمة، أخبره أن عمرو بن عوف، وهو حليف لبني عامر بن لؤي، وكان شهد بدرا مع النبي صلى الله عليه وسلم أن رسول الله صلى الله عليه وسلم : بعث أبا عبيدة بن الجراح إلى البحرين يأتي بجزيتها، وكان رسول الله صلى الله عليه وسلم هو صالح أهل البحرين وأمر عليهم العلاء بن الحضرمي، فقدم أبو عبيدة بمال من البحرين، فسمعت الأنصار بقدوم أبي عبيدة، فوافوا صلاة الفجر مع النبي صلى الله عليه وسلم، فلما انصرف تعرضوا له، فتبسم رسول الله صلى الله عليه وسلم حين رآهم، ثم قال: «أظنكم سمعتم أن أبا عبيدة قدم بشيء» قالوا: أجل يا رسول الله، قال: «فأبشروا وأملوا ما يسركم، فوالله ما الفقر أخشى عليكم، ولكني أخشى أن تبسط عليكم الدنيا كما بسطت على من كان قبلكم، فتنافسوها كما تنافسوها، وتهلككم كما أهلكتهم»", "4015"], ["باب", "حدثنا أبو النعمان، حدثنا جرير بن حازم، عن نافع، أن ابن عمر رضي الله عنهما، كان يقتل الحيات كلها، حتى حدثه أبو لبابة البدري أن النبي صلى الله عليه وسلم «نهى عن قتل جنان البيوت، فأمسك عنها»", "4016"], ["باب", "حدثني إبراهيم بن المنذر، حدثنا محمد بن فليح، عن موسى بن عقبة، قال ابن شهاب: حدثنا أنس بن مالك، أن رجالا من الأنصار استأذنوا رسول الله صلى الله عليه وسلم، فقالوا: ائذن لنا فلنترك لابن أختنا عباس فداءه قال: «والله لا تذرون منه درهما»", "4017"], ["باب", "حدثنا أبو عاصم، عن ابن جريج، عن الزهري، عن عطاء بن يزيد، عن عبيد الله بن عدي، عن المقداد بن الأسود، ح حدثني إسحاق، حدثنا يعقوب بن إبراهيم بن سعد، حدثنا ابن أخي ابن شهاب، عن عمه، قال: أخبرني عطاء بن يزيد الليثي ثم الجندعي، أن عبيد الله بن عدي بن الخيار أخبره، أن المقداد بن عمرو الكندي، وكان حليفا لبني زهرة، وكان ممن شهد بدرا مع رسول الله صلى الله عليه وسلم أخبره: أنه قال لرسول الله صلى الله عليه وسلم: أرأيت إن لقيت رجلا من الكفار فاقتتلنا، فضرب إحدى يدي بالسيف فقطعها، ثم لاذ مني بشجرة، فقال: أسلمت لله، أأقتله يا رسول الله بعد أن قالها؟ فقال رسول الله صلى الله عليه وسلم: «لا تقتله» فقال: يا رسول الله إنه قطع إحدى يدي، ثم قال ذلك بعد ما قطعها؟ فقال رسول الله صلى الله عليه وسلم: «لا تقتله، فإن قتلته فإنه بمنزلتك قبل أن تقتله، وإنك بمنزلته قبل أن يقول كلمته التي قال»", "4019"], ["باب", "حدثني يعقوب بن إبراهيم، حدثنا ابن علية، حدثنا سليمان التيمي، حدثنا أنس رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم يوم بدر: «من ينظر ما صنع أبو جهل» فانطلق ابن مسعود، فوجده قد ضربه ابنا عفراء حتى برد، فقال: آنت أبا جهل؟ قال ابن علية، قال سليمان: هكذا قالها أنس، قال : \" أنت أبا جهل؟ قال: وهل فوق رجل قتلتموه \" قال سليمان: أو قال: «قتله قومه» قال: وقال أبو مجلز: «قال أبو جهل فلو غير أكار قتلني»", "4020"], ["باب", "حدثنا موسى، حدثنا عبد الواحد، حدثنا معمر، عن الزهري، عن عبيد الله بن عبد الله، حدثني ابن عباس، عن عمر رضي الله عنهم، \" لما توفي النبي صلى الله عليه وسلم قلت لأبي بكر: انطلق بنا إلى إخواننا من الأنصار، فلقينا منهم رجلان صالحان شهدا بدرا \" فحدثت به عروة بن الزبير، فقال: «هما عويم بن ساعدة ومعن بن عدي»", "4021"], ["باب", "حدثنا إسحاق بن إبراهيم، سمع محمد بن فضيل، عن إسماعيل، عن قيس، كان عطاء البدريين خمسة آلاف، خمسة آلاف وقال عمر: «لأفضلنهم على من بعدهم»", "4022"], ["باب", "حدثني إسحاق بن منصور، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن محمد بن جبير، عن أبيه، قال: سمعت النبي صلى الله عليه وسلم: «يقرأ في المغرب بالطور، وذلك أول ما وقر الإيمان في قلبي»", "4023"], ["باب", "وعن الزهري، عن محمد بن جبير بن مطعم، عن أبيه، أن النبي صلى الله عليه وسلم، قال: في أسارى بدر: «لو كان المطعم بن عدي حيا، ثم كلمني في هؤلاء النتنى، لتركتهم له» وقال الليث، عن يحيى بن سعيد، عن سعيد بن المسيب: وقعت الفتنة الأولى - يعني مقتل عثمان - فلم تبق من أصحاب بدر أحدا، ثم وقعت الفتنة الثانية، - يعني الحرة - فلم تبق من أصحاب الحديبية أحدا، ثم وقعت الثالثة، فلم ترتفع وللناس طباخ \"", "4024"], ["باب", "حدثنا الحجاج بن منهال، حدثنا عبد الله بن عمر النميري، حدثنا يونس بن يزيد، قال: سمعت الزهري، قال: سمعت عروة بن الزبير، وسعيد بن المسيب، وعلقمة بن وقاص، وعبيد الله بن عبد الله، عن حديث عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم، كل حدثني طائفة من الحديث، قالت: فأقبلت أنا وأم مسطح، فعثرت أم مسطح في مرطها، فقالت: تعس مسطح، فقلت: «بئس ما قلت، تسبين رجلا شهد بدرا» فذكر حديث الإفك", "4025"], ["باب", "حدثنا إبراهيم بن المنذر، حدثنا محمد بن فليح بن سليمان، عن موسى بن عقبة، عن ابن شهاب، قال: هذه مغازي رسول الله صلى الله عليه وسلم فذكر الحديث، فقال رسول الله صلى الله عليه وسلم وهو يلقيهم «هل وجدتم ما وعدكم ربكم حقا؟» قال موسى: قال نافع: قال عبد الله: قال ناس من أصحابه: يا رسول الله، تنادي ناسا أمواتا؟ قال رسول الله صلى الله عليه وسلم: «ما أنتم بأسمع لما قلت منهم» قال أبو عبد الله: «فجميع من شهد بدرا من قريش ممن ضرب له بسهمه أحد وثمانون رجلا»، وكان عروة بن الزبير يقول: قال الزبير: «قسمت سهمانهم، فكانوا مائة، والله أعلم»", "4026"], ["باب", "حدثني إبراهيم بن موسى، أخبرنا هشام، عن معمر، عن هشام بن عروة، عن أبيه، عن الزبير، قال: «ضربت يوم بدر للمهاجرين بمائة سهم»", "4027"], ["باب غزوة أحد", "حدثنا إبراهيم بن موسى، أخبرنا عبد الوهاب، حدثنا خالد، عن عكرمة، عن ابن عباس رضي الله عنهما، قال: قال النبي صلى الله عليه وسلم يوم أحد: «هذا جبريل آخذ برأس فرسه عليه أداة الحرب»", "4041"], ["باب غزوة أحد", "حدثنا محمد بن عبد الرحيم، أخبرنا زكرياء بن عدي، أخبرنا ابن المبارك، عن حيوة، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر، قال: صلى رسول الله صلى الله عليه وسلم على قتلى أحد بعد ثماني سنين، كالمودع للأحياء والأموات، ثم طلع المنبر فقال: «إني بين أيديكم فرط، وأنا عليكم شهيد، وإن موعدكم الحوض، وإني لأنظر إليه من مقامي هذا، وإني لست أخشى عليكم أن تشركوا، ولكني أخشى عليكم الدنيا أن تنافسوها»، قال: فكانت آخر نظرة نظرتها إلى رسول الله صلى الله عليه وسلم", "4042"], ["باب غزوة أحد", "حدثنا عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء رضي الله عنه، قال: لقينا المشركين يومئذ، وأجلس النبي صلى الله عليه وسلم جيشا من الرماة، وأمر عليهم عبد الله، وقال: «لا تبرحوا، إن رأيتمونا ظهرنا عليهم فلا تبرحوا، وإن رأيتموهم ظهروا علينا فلا تعينونا» فلما لقينا هربوا حتى رأيت النساء يشتددن في الجبل، رفعن عن سوقهن، قد بدت خلاخلهن، فأخذوا يقولون: الغنيمة الغنيمة، فقال عبد الله: عهد إلي النبي صلى الله عليه وسلم أن لا تبرحوا، فأبوا، فلما أبوا صرف وجوههم، فأصيب سبعون قتيلا، وأشرف أبو سفيان فقال: أفي القوم محمد؟ فقال: «لا تجيبوه» فقال: أفي القوم ابن أبي قحافة؟ قال: «لا تجيبوه» فقال: أفي القوم ابن الخطاب؟ فقال: إن هؤلاء قتلوا، فلو كانوا أحياء لأجابوا، فلم يملك عمر نفسه، فقال: كذبت يا عدو الله، أبقى الله عليك ما يخزيك، قال أبو سفيان: اعل هبل، فقال النبي صلى الله عليه وسلم: «أجيبوه» قالوا: ما نقول؟ قال: \" قولوا: الله أعلى وأجل \" قال أبو سفيان: لنا العزى ولا عزى لكم، فقال النبي صلى الله عليه وسلم: «أجيبوه» قالوا: ما نقول؟ قال: «قولوا الله مولانا، ولا مولى لكم» قال أبو سفيان: يوم بيوم بدر، والحرب سجال، وتجدون مثلة، لم آمر بها ولم تسؤني", "4043"], ["باب غزوة أحد", "أخبرني عبد الله بن محمد، حدثنا سفيان، عن عمرو، عن جابر، قال: «اصطبح الخمر يوم أحد ناس، ثم قتلوا شهداء»", "4044"], ["باب غزوة أحد", "حدثنا عبدان، حدثنا عبد الله، أخبرنا شعبة، عن سعد بن إبراهيم، عن أبيه إبراهيم، أن عبد الرحمن بن عوف، \" أتي بطعام، وكان صائما، فقال: قتل مصعب بن عمير وهو خير مني، كفن في بردة: إن غطي رأسه بدت رجلاه، وإن غطي رجلاه بدا رأسه، وأراه قال: وقتل حمزة وهو خير مني، ثم بسط لنا من الدنيا ما بسط، أو قال: أعطينا من الدنيا ما أعطينا، وقد خشينا أن تكون حسناتنا عجلت لنا، ثم جعل يبكي حتى ترك الطعام \"", "4045"], ["باب غزوة أحد", "حدثنا عبد الله بن محمد، حدثنا سفيان، عن عمرو، سمع جابر بن عبد الله رضي الله عنهما، قال: قال رجل للنبي صلى الله عليه وسلم يوم أحد أرأيت إن قتلت فأين أنا؟ قال: «في الجنة فألقى تمرات في يده، ثم قاتل حتى قتل»", "4046"], ["باب غزوة أحد", "حدثنا أحمد بن يونس، حدثنا زهير، حدثنا الأعمش، عن شقيق، عن خباب بن الأرت رضي الله عنه، قال: هاجرنا مع رسول الله صلى الله عليه وسلم نبتغي وجه الله، فوجب أجرنا على الله، ومنا من مضى، أو ذهب، لم يأكل من أجره شيئا، كان منهم مصعب بن عمير، قتل يوم أحد، لم يترك إلا نمرة , كنا إذا غطينا بها رأسه خرجت رجلاه، وإذا غطي بها رجلاه خرج رأسه، فقال لنا النبي صلى الله عليه وسلم: «غطوا بها رأسه، واجعلوا على رجله الإذخر»، أو قال: «ألقوا على رجله من الإذخر» ومنا من قد أينعت له ثمرته فهو يهدبها", "4047"], ["باب غزوة أحد", "أخبرنا حسان بن حسان، حدثنا محمد بن طلحة، حدثنا حميد، عن أنس رضي الله عنه أن عمه غاب عن بدر، فقال: غبت عن أول قتال النبي صلى الله عليه وسلم، لئن أشهدني الله مع النبي صلى الله عليه وسلم ليرين الله ما أجد، فلقي يوم أحد، فهزم الناس، فقال: «اللهم إني أعتذر إليك مما صنع هؤلاء، يعني المسلمين وأبرأ إليك مما جاء به المشركون» فتقدم بسيفه فلقي سعد بن معاذ، فقال: أين يا سعد، إني أجد ريح الجنة دون أحد، فمضى فقتل، فما عرف حتى عرفته أخته بشامة أو ببنانه، وبه بضع وثمانون من طعنة وضربة ورمية بسهم", "4048"], ["باب غزوة أحد", "حدثنا موسى بن إسماعيل، حدثنا إبراهيم بن سعد، حدثنا ابن شهاب، أخبرني خارجة بن زيد بن ثابت، أنه سمع زيد بن ثابت رضي الله عنه، يقول: \" فقدت آية من الأحزاب حين نسخنا المصحف، كنت أسمع رسول الله صلى الله عليه وسلم يقرأ بها فالتمسناها فوجدناها مع خزيمة بن ثابت الأنصاري {من المؤمنين، رجال صدقوا ما عاهدوا الله عليه، فمنهم من قضى نحبه ومنهم من ينتظر} [الأحزاب: 23] فألحقناها في سورتها في المصحف \"", "4049"], ["باب غزوة أحد", "حدثنا أبو الوليد، حدثنا شعبة، عن عدي بن ثابت، سمعت عبد الله بن يزيد، يحدث عن زيد بن ثابت رضي الله عنه، قال: لما خرج النبي صلى الله عليه وسلم إلى أحد، رجع ناس ممن خرج معه، وكان أصحاب النبي صلى الله عليه وسلم فرقتين: فرقة تقول: نقاتلهم، وفرقة تقول: لا نقاتلهم، فنزلت {فما لكم في المنافقين فئتين والله أركسهم بما كسبوا} [النساء: 88] وقال: «إنها طيبة، تنفي الذنوب، كما تنفي النار خبث الفضة»", "4050"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا محمد بن يوسف، عن ابن عيينة، عن عمرو، عن جابر رضي الله عنه، قال: \" نزلت هذه الآية فينا: {إذ همت طائفتان منكم أن تفشلا} [آل عمران: 122] بني سلمة، وبني حارثة، وما أحب أنها لم تنزل، والله يقول: {والله وليهما} [آل عمران: 122]", "4051"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا قتيبة، حدثنا سفيان، أخبرنا عمرو، عن جابر، قال: قال لي رسول الله صلى الله عليه وسلم «هل نكحت يا جابر؟» قلت: نعم، قال: «ماذا أبكرا أم ثيبا؟» قلت: لا بل ثيبا، قال «فهلا جارية تلاعبك» قلت: يا رسول الله إن أبي قتل يوم أحد، وترك تسع بنات، كن لي تسع أخوات، فكرهت أن أجمع إليهن جارية خرقاء مثلهن، ولكن امرأة تمشطهن وتقوم عليهن، قال: «أصبت»", "4052"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثني أحمد بن أبي سريج، أخبرنا عبيد الله بن موسى، حدثنا شيبان، عن فراس، عن الشعبي، قال: حدثني جابر بن عبد الله رضي الله عنهما، أن أباه، استشهد يوم أحد وترك عليه دينا، وترك ست بنات، فلما حضر جزاز النخل قال: أتيت رسول الله صلى الله عليه وسلم فقلت: قد علمت أن والدي قد استشهد يوم أحد وترك دينا كثيرا، وإني أحب أن يراك الغرماء، فقال: «اذهب فبيدر كل تمر على ناحية»، ففعلت ثم دعوته، فلما نظروا إليه كأنهم أغروا بي تلك الساعة، فلما رأى ما يصنعون أطاف حول أعظمها بيدرا ثلاث مرات، ثم جلس عليه، ثم قال: «ادع لي أصحابك» فما زال يكيل لهم حتى أدى الله عن والدي أمانته، وأنا أرضى أن يؤدي الله أمانة والدي، ولا أرجع إلى أخواتي بتمرة، فسلم الله البيادر كلها، وحتى إني أنظر إلى البيدر الذي كان عليه النبي صلى الله عليه وسلم كأنها لم تنقص تمرة واحدة", "4053"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا عبد العزيز بن عبد الله، حدثنا إبراهيم بن سعد، عن أبيه، عن جده، عن سعد بن أبي وقاص رضي الله عنه، قال: «رأيت رسول الله صلى الله عليه وسلم يوم أحد، ومعه رجلان يقاتلان عنه، عليهما ثياب بيض، كأشد القتال ما رأيتهما قبل ولا بعد»", "4054"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثني عبد الله بن محمد، حدثنا مروان بن معاوية، حدثنا هاشم بن هاشم السعدي، قال: سمعت سعيد بن المسيب، يقول: سمعت سعد بن أبي وقاص، يقول: نثل لي النبي صلى الله عليه وسلم كنانته يوم أحد، فقال «ارم فداك أبي وأمي»", "4055"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا مسدد، حدثنا يحيى، عن يحيى بن سعيد، قال: سمعت سعيد بن المسيب، قال: سمعت سعدا، يقول: «جمع لي النبي صلى الله عليه وسلم، أبويه يوم أحد»", "4056"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا قتيبة، حدثنا ليث، عن يحيى، عن ابن المسيب، أنه قال: قال سعد بن أبي وقاص رضي الله عنه، لقد جمع لي رسول الله صلى الله عليه وسلم يوم أحد أبويه كليهما يريد حين قال: «فداك أبي وأمي» وهو يقاتل", "4057"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا أبو نعيم، حدثنا مسعر، عن سعد، عن ابن شداد، قال: سمعت عليا رضي الله عنه، يقول: «ما سمعت النبي صلى الله عليه وسلم يجمع أبويه لأحد غير سعد»", "4058"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا يسرة بن صفوان، حدثنا إبراهيم، عن أبيه، عن عبد الله بن شداد، عن علي رضي الله عنه، قال: ما سمعت النبي صلى الله عليه وسلم جمع أبويه لأحد إلا لسعد بن مالك، فإني سمعته يقول يوم أحد: «يا سعد ارم فداك أبي وأمي»", "4059"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا موسى بن إسماعيل، عن معتمر، عن أبيه، قال زعم أبو عثمان: «أنه لم يبق مع النبي صلى الله عليه وسلم، في بعض تلك الأيام التي يقاتل فيهن، غير طلحة، وسعد» عن حديثهما", "4060"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا عبد الله بن أبي الأسود، حدثنا حاتم بن إسماعيل، عن محمد بن يوسف، قال: سمعت السائب بن يزيد، قال: صحبت عبد الرحمن بن عوف، وطلحة بن عبيد الله، والمقداد، وسعدا رضي الله عنهم فما سمعت أحدا منهم يحدث عن النبي صلى الله عليه وسلم، إلا أني سمعت طلحة: «يحدث عن يوم أحد»", "4062"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثني عبد الله بن أبي شيبة، حدثنا وكيع، عن إسماعيل، عن قيس، قال: «رأيت يد طلحة شلاء وقى بها النبي صلى الله عليه وسلم يوم أحد»", "4063"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثنا أبو معمر، حدثنا عبد الوارث، حدثنا عبد العزيز، عن أنس رضي الله عنه، قال: لما كان يوم أحد انهزم الناس عن النبي صلى الله عليه وسلم، وأبو طلحة بين يدي النبي صلى الله عليه وسلم مجوب عليه بحجفة له ، وكان أبو طلحة رجلا راميا شديد النزع، كسر يومئذ قوسين أو ثلاثا، وكان الرجل يمر معه بجعبة من النبل، فيقول: «انثرها لأبي طلحة» قال: ويشرف النبي صلى الله عليه وسلم ينظر إلى القوم، فيقول أبو طلحة: بأبي أنت وأمي، لا تشرف، يصيبك سهم من سهام القوم، نحري دون نحرك، ولقد رأيت عائشة بنت أبي بكر وأم سليم، وإنهما لمشمرتان، أرى خدم سوقهما تنقزان القرب على متونهما تفرغانه في أفواه القوم، ثم ترجعان فتملآنها، ثم تجيئان فتفرغانه في أفواه القوم، ولقد وقع السيف من يدي أبي طلحة إما مرتين وإما ثلاثا", "4064"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون} [آل عمران: 122]", "حدثني عبيد الله بن سعيد، حدثنا أبو أسامة، عن هشام بن عروة، عن أبيه، عن عائشة رضي الله عنها، قالت: \" لما كان يوم أحد هزم المشركون، فصرخ إبليس لعنة الله عليه: أي عباد الله أخراكم، فرجعت أولاهم فاجتلدت هي وأخراهم، فبصر حذيفة فإذا هو بأبيه اليمان، فقال: أي عباد الله أبي أبي، قال: قالت: فوالله ما احتجزوا حتى قتلوه، فقال حذيفة: يغفر الله لكم \" قال عروة: فوالله ما زالت في حذيفة بقية خير، حتى لحق بالله عز وجل \" بصرت: علمت، من البصيرة في الأمر، وأبصرت: من بصر العين، ويقال: بصرت وأبصرت واحد \"", "4065"], ["باب قول الله تعالى: {إن الذين تولوا منكم يوم التقى الجمعان إنما استزلهم الشيطان ببعض ما كسبوا ولقد عفا الله عنهم إن الله غفور حليم} [آل عمران: 155]", "حدثنا عبدان، أخبرنا أبو حمزة، عن عثمان بن موهب، قال: جاء رجل حج البيت، فرأى قوما جلوسا، فقال: من هؤلاء القعود؟ قالوا: هؤلاء قريش. قال: من الشيخ؟ قالوا ابن عمر، فأتاه فقال: إني سائلك عن شيء أتحدثني؟ قال: أنشدك بحرمة هذا البيت، أتعلم أن عثمان بن عفان فر يوم أحد؟ قال: نعم، قال: فتعلمه تغيب عن بدر، فلم يشهدها؟ قال: نعم، قال: فتعلم أنه تخلف عن بيعة الرضوان فلم يشهدها؟ قال: نعم، قال: فكبر، قال ابن عمر: تعال لأخبرك ولأبين لك عما سألتني عنه، أما فراره يوم أحد فأشهد أن الله عفا عنه، وأما تغيبه عن بدر، فإنه كان تحته بنت رسول الله صلى الله عليه وسلم، وكانت مريضة، فقال له النبي صلى الله عليه وسلم: «إن لك أجر رجل ممن شهد بدرا وسهمه» وأما تغيبه عن بيعة الرضوان، فإنه لو كان أحد أعز ببطن مكة من عثمان بن عفان لبعثه مكانه، فبعث عثمان، وكانت بيعة الرضوان بعدما ذهب عثمان إلى مكة، فقال النبي صلى الله عليه وسلم بيده اليمنى: «هذه يد عثمان - فضرب بها على يده، فقال - هذه لعثمان» اذهب بهذا الآن معك", "4066"], ["باب {إذ تصعدون ولا تلوون على أحد والرسول يدعوكم في أخراكم فأثابكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما أصابكم والله خبير بما تعملون} [آل عمران: 153] \"", "حدثني عمرو بن خالد، حدثنا زهير، حدثنا أبو إسحاق، قال: سمعت البراء بن عازب رضي الله عنهما، قال \" جعل النبي صلى الله عليه وسلم على الرجالة يوم أحد عبد الله بن جبير، وأقبلوا منهزمين فذاك: إذ يدعوهم الرسول في أخراهم \"", "4067"], ["باب {ثم أنزل عليكم من بعد الغم أمنة نعاسا يغشى طائفة منكم وطائفة قد أهمتهم أنفسهم يظنون بالله غير الحق ظن الجاهلية يقولون هل لنا من الأمر من شيء قل إن الأمر كله لله يخفون في أنفسهم ما لا يبدون لك يقولون لو كان لنا من الأمر شيء ما قتلنا هاهنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل إلى مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور} [آل عمران: 154]", "وقال لي خليفة، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، عن أنس، عن أبي طلحة رضي الله عنهما، قال: «كنت فيمن تغشاه النعاس يوم أحد حتى سقط سيفي من يدي مرارا يسقط وآخذه ويسقط فآخذه»", "4068"], ["باب {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] قال حميد وثابت، عن أنس شج النبي صلى الله عليه وسلم يوم أحد فقال: «كيف يفلح قوم شجوا نبيهم» فنزلت: {ليس لك من الأمر شيء} [آل عمران: 128]", "حدثنا يحيى بن عبد الله السلمي، أخبرنا عبد الله، أخبرنا معمر، عن الزهري، حدثني سالم، عن أبيه، أنه سمع رسول الله صلى الله عليه وسلم إذا رفع رأسه من الركوع من الركعة الآخرة من الفجر يقول: «اللهم العن فلانا وفلانا وفلانا» بعد ما يقول «سمع الله لمن حمده، ربنا ولك الحمد» فأنزل الله: {ليس لك من الأمر شيء} [آل عمران: 128]- إلى قوله - {فإنهم ظالمون} [آل عمران: 128]", "4069"], ["باب {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} [آل عمران: 128] قال حميد وثابت، عن أنس شج النبي صلى الله عليه وسلم يوم أحد فقال: «كيف يفلح قوم شجوا نبيهم» فنزلت: {ليس لك من الأمر شيء} [آل عمران: 128]", "وعن حنظلة بن أبي سفيان، سمعت سالم بن عبد الله يقول: كان رسول الله صلى الله عليه وسلم \" يدعو على صفوان بن أمية، وسهيل بن عمرو، والحارث بن هشام فنزلت {ليس لك من الأمر شيء} [آل عمران: 128]- إلى قوله - {فإنهم ظالمون} [آل عمران: 128]", "4070"], ["باب ذكر أم سليط", "حدثنا يحيى بن بكير، حدثنا الليث، عن يونس، عن ابن شهاب، وقال ثعلبة بن أبي مالك: إن عمر بن الخطاب رضي الله عنه، قسم مروطا بين نساء من نساء أهل المدينة، فبقي منها مرط جيد، فقال له بعض من عنده: يا أمير المؤمنين، أعط هذا بنت رسول الله صلى الله عليه وسلم التي عندك، يريدون أم كلثوم بنت علي، فقال عمر: أم سليط أحق به، «وأم سليط من نساء الأنصار، ممن بايع رسول الله صلى الله عليه وسلم» قال عمر: فإنها كانت تزفر لنا القرب يوم أحد", "4071"], ["باب قتل حمزة بن عبد المطلب رضي الله عنه", "حدثني أبو جعفر محمد بن عبد الله، حدثنا حجين بن المثنى، حدثنا عبد العزيز بن عبد الله بن أبي سلمة، عن عبد الله بن الفضل، عن سليمان بن يسار، عن جعفر بن عمرو بن أمية الضمري، قال: خرجت مع عبيد الله بن عدي بن الخيار، فلما قدمنا حمص، قال لي عبيد الله بن عدي: هل لك في وحشي، نسأله عن قتل حمزة؟ قلت: نعم، وكان وحشي يسكن حمص، فسألنا عنه، فقيل لنا: هو ذاك في ظل قصره، كأنه حميت، قال: فجئنا حتى وقفنا عليه بيسير، فسلمنا فرد السلام، قال: وعبيد الله معتجر بعمامته، ما يرى وحشي إلا عينيه ورجليه، فقال عبيد الله: يا وحشي أتعرفني؟ قال: فنظر إليه ثم قال: لا والله، إلا أني أعلم أن عدي بن الخيار تزوج امرأة يقال لها أم قتال بنت أبي العيص، فولدت له غلاما بمكة، فكنت أسترضع له، فحملت ذلك الغلام مع أمه فناولتها إياه، فلكأني نظرت إلى قدميك، قال: فكشف عبيد الله عن وجهه ثم قال: ألا تخبرنا بقتل حمزة؟ قال: نعم، إن حمزة قتل طعيمة بن عدي بن الخيار ببدر، فقال لي مولاي جبير بن مطعم: إن قتلت حمزة بعمي فأنت حر، قال: فلما أن خرج الناس عام عينين، وعينين جبل بحيال أحد، بينه وبينه واد، خرجت مع الناس إلى القتال، فلما أن اصطفوا للقتال، خرج سباع فقال: هل من مبارز؟ قال: فخرج إليه حمزة بن عبد المطلب، فقال: يا سباع، يا ابن أم أنمار مقطعة البظور، أتحاد الله ورسوله صلى الله عليه وسلم؟ قال: ثم شد عليه، فكان كأمس الذاهب، قال: وكمنت لحمزة تحت صخرة، فلما دنا مني رميته بحربتي، فأضعها في ثنته حتى خرجت من بين وركيه، قال: فكان ذاك العهد به، فلما رجع الناس رجعت معهم، فأقمت بمكة حتى فشا فيها الإسلام، ثم خرجت إلى الطائف، فأرسلوا إلى رسول الله صلى الله عليه وسلم رسولا، فقيل لي: إنه لا يهيج الرسل، قال: فخرجت معهم حتى قدمت على رسول الله صلى الله عليه وسلم، فلما رآني قال: «آنت وحشي» قلت: نعم، قال: «أنت قتلت حمزة» قلت: قد كان من الأمر ما بلغك، قال: «فهل تستطيع أن تغيب وجهك عني» قال: فخرجت فلما قبض رسول الله صلى الله عليه وسلم فخرج مسيلمة الكذاب، قلت: لأخرجن إلى مسيلمة، لعلي أقتله فأكافئ به حمزة، قال: فخرجت مع الناس، فكان من أمره ما كان، قال: فإذا رجل قائم في ثلمة جدار، كأنه جمل أورق ثائر الرأس، قال: فرميته بحربتي، فأضعها بين ثدييه حتى خرجت من بين كتفيه، قال: ووثب إليه رجل من الأنصار فضربه بالسيف على هامته، قال: قال عبد الله بن الفضل: فأخبرني سليمان بن يسار، أنه سمع عبد الله بن عمر، يقول: \" فقالت جارية على ظهر بيت: وا أمير المؤمنين، قتله العبد الأسود \"", "4072"], ["باب ما أصاب النبي صلى الله عليه وسلم من الجراح يوم أحد", "حدثنا إسحاق بن نصر، حدثنا عبد الرزاق، عن معمر، عن همام، سمع أبا هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: «اشتد غضب الله على قوم فعلوا بنبيه، يشير إلى رباعيته، اشتد غضب الله على رجل يقتله رسول الله في سبيل الله»", "4073"], ["باب ما أصاب النبي صلى الله عليه وسلم من الجراح يوم أحد", "حدثني مخلد بن مالك، حدثنا يحيى بن سعيد الأموي، حدثنا ابن جريج، عن عمرو بن دينار، عن عكرمة، عن ابن عباس رضي الله عنهما، قال: «اشتد غضب الله على من قتله النبي صلى الله عليه وسلم في سبيل الله، اشتد غضب الله على قوم دموا وجه نبي الله صلى الله عليه وسلم»", "4074"], ["باب", "حدثنا قتيبة بن سعيد، حدثنا يعقوب، عن أبي حازم، أنه سمع سهل بن سعد، وهو يسأل عن جرح رسول الله صلى الله عليه وسلم، فقال: \" أما والله إني لأعرف من كان يغسل جرح رسول الله صلى الله عليه وسلم، ومن كان يسكب الماء، وبما دووي، قال: كانت فاطمة عليها السلام بنت رسول الله صلى الله عليه وسلم تغسله، وعلي بن أبي طالب يسكب الماء بالمجن، فلما رأت فاطمة أن الماء لا يزيد الدم إلا كثرة، أخذت قطعة من حصير، فأحرقتها وألصقتها، فاستمسك الدم، وكسرت رباعيته يومئذ، وجرح وجهه، وكسرت البيضة على رأسه \"", "4075"], ["باب", "حدثني عمرو بن علي، حدثنا أبو عاصم، حدثنا ابن جريج، عن عمرو بن دينار، عن عكرمة، عن ابن عباس، قال: «اشتد غضب الله على من قتله نبي، واشتد غضب الله على من دمى وجه رسول الله صلى الله عليه وسلم»", "4076"], ["باب {الذين استجابوا لله والرسول} [آل عمران: 172]", "حدثنا محمد، حدثنا أبو معاوية، عن هشام، عن أبيه، عن عائشة رضي الله عنها، {الذين استجابوا لله والرسول من بعد ما أصابهم القرح} [آل عمران: 172] للذين أحسنوا منهم واتقوا أجر عظيم، قالت لعروة: يا ابن أختي، كان أبواك منهم: الزبير، وأبو بكر، لما أصاب رسول الله صلى الله عليه وسلم ما أصاب يوم أحد، وانصرف عنه المشركون، خاف أن يرجعوا، قال: «من يذهب في إثرهم» فانتدب منهم سبعون رجلا، قال: كان فيهم أبو بكر، والزبير", "4077"], ["باب من قتل من المسلمين يوم أحد", "حدثني عمرو بن علي، حدثنا معاذ بن هشام، قال: حدثني أبي، عن قتادة، قال: ما نعلم حيا من أحياء العرب أكثر شهيدا أعز يوم القيامة من الأنصار قال قتادة: وحدثنا أنس بن مالك أنه \" قتل منهم يوم أحد سبعون، ويوم بئر معونة سبعون، ويوم اليمامة سبعون، قال: «وكان بئر معونة على عهد رسول الله صلى الله عليه وسلم، ويوم اليمامة على عهد أبي بكر، يوم مسيلمة الكذاب»", "4078"], ["باب من قتل من المسلمين يوم أحد", "حدثنا قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب، عن عبد الرحمن بن كعب بن مالك، أن جابر بن عبد الله رضي الله عنهما، أخبره أن رسول الله صلى الله عليه وسلم كان يجمع بين الرجلين من قتلى أحد في ثوب واحد، ثم يقول: «أيهم أكثر أخذا للقرآن» فإذا أشير له إلى أحد قدمه في اللحد، وقال: «أنا شهيد على هؤلاء يوم القيامة» وأمر بدفنهم بدمائهم، ولم يصل عليهم ولم يغسلوا", "4079"], ["باب من قتل من المسلمين يوم أحد", "وقال أبو الوليد، عن شعبة، عن ابن المنكدر، قال: سمعت جابر بن عبد الله، قال: لما قتل أبي جعلت أبكي، وأكشف الثوب عن وجهه، فجعل أصحاب النبي صلى الله عليه وسلم ينهوني والنبي صلى الله عليه وسلم لم ينه، وقال النبي صلى الله عليه وسلم: \" لا تبكيه - أو: ما تبكيه - ما زالت الملائكة تظله بأجنحتها حتى رفع \"", "4080"], ["باب من قتل من المسلمين يوم أحد", "حدثنا محمد بن العلاء، حدثنا أبو أسامة، عن بريد بن عبد الله بن أبي بردة، عن جده أبي بردة، عن أبي موسى رضي الله عنه، - أرى - عن النبي صلى الله عليه وسلم، قال: «رأيت في رؤياي أني هززت سيفا فانقطع صدره، فإذا هو ما أصيب من المؤمنين يوم أحد، ثم هززته أخرى فعاد أحسن ما كان، فإذا هو ما جاء به الله من الفتح واجتماع المؤمنين، ورأيت فيها بقرا، والله خير، فإذا هم المؤمنون يوم أحد»", "4081"], ["باب من قتل من المسلمين يوم أحد", "حدثنا أحمد بن يونس، حدثنا زهير، حدثنا الأعمش، عن شقيق، عن خباب رضي الله عنه، قال: هاجرنا مع النبي صلى الله عليه وسلم ونحن نبتغي وجه الله، فوجب أجرنا على الله، فمنا من مضى، أو ذهب، لم يأكل من أجره شيئا، كان منهم مصعب بن عمير، قتل يوم أحد، فلم يترك إلا نمرة، كنا إذا غطينا بها رأسه خرجت رجلاه، وإذا غطي بها رجلاه خرج رأسه، فقال لنا النبي صلى الله عليه وسلم: «غطوا بها رأسه، واجعلوا على رجليه الإذخر» أو قال: «ألقوا على رجليه من الإذخر» ومنا من أينعت له ثمرته فهو يهدبها", "4082"], ["باب: أحد يحبنا ونحبه", "حدثني نصر بن علي، قال: أخبرني أبي، عن قرة بن خالد، عن قتادة، سمعت أنسا رضي الله عنه، أن النبي صلى الله عليه وسلم، قال: «هذا جبل يحبنا ونحبه»", "4083"], ["باب: أحد يحبنا ونحبه", "حدثنا عبد الله بن يوسف، أخبرنا مالك، عن عمرو، مولى المطلب، عن أنس بن مالك رضي الله عنه، أن رسول الله صلى الله عليه وسلم طلع له أحد فقال: «هذا جبل يحبنا ونحبه، اللهم إن إبراهيم حرم مكة وإني حرمت ما بين لابتيها»", "4084"], ["باب: أحد يحبنا ونحبه", "حدثني عمرو بن خالد، حدثنا الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة: أن النبي صلى الله عليه وسلم خرج يوما، فصلى على أهل أحد صلاته على الميت، ثم انصرف إلى المنبر فقال: «إني فرط لكم، وأنا شهيد عليكم، وإني لأنظر إلى حوضي الآن، وإني أعطيت مفاتيح خزائن الأرض، أو مفاتيح الأرض، وإني والله ما أخاف عليكم أن تشركوا بعدي، ولكني أخاف عليكم أن تنافسوا فيها»", "4085"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثني إبراهيم بن موسى، أخبرنا هشام بن يوسف، عن معمر، عن الزهري، عن عمرو بن أبي سفيان الثقفي، عن أبي هريرة رضي الله عنه، قال: «بعث النبي صلى الله عليه وسلم سرية عينا، وأمر عليهم عاصم بن ثابت» وهو جد عاصم بن عمر بن الخطاب، فانطلقوا حتى إذا كان بين عسفان ومكة ذكروا لحي من هذيل يقال لهم: بنو لحيان، فتبعوهم بقريب من مائة رام، فاقتصوا آثارهم حتى أتوا منزلا نزلوه، فوجدوا فيه نوى تمر تزودوه من المدينة، فقالوا: هذا تمر يثرب، فتبعوا آثارهم حتى لحقوهم، فلما انتهى عاصم وأصحابه لجئوا إلى فدفد، وجاء القوم فأحاطوا بهم، فقالوا: لكم العهد والميثاق إن نزلتم إلينا، أن لا نقتل منكم رجلا، فقال عاصم: أما أنا فلا أنزل في ذمة كافر، اللهم أخبر عنا نبيك، فقاتلوهم حتى قتلوا عاصما في سبعة نفر بالنبل، وبقي خبيب وزيد ورجل آخر، فأعطوهم العهد والميثاق، فلما أعطوهم العهد والميثاق نزلوا إليهم، فلما استمكنوا منهم حلوا أوتار قسيهم، فربطوهم بها، فقال الرجل الثالث الذي معهما: هذا أول الغدر، فأبى أن يصحبهم فجرروه وعالجوه على أن يصحبهم فلم يفعل فقتلوه، وانطلقوا بخبيب، وزيد حتى باعوهما بمكة، فاشترى خبيبا بنو الحارث بن عامر بن نوفل، وكان خبيب هو قتل الحارث يوم بدر، فمكث عندهم أسيرا، حتى إذا أجمعوا قتله، استعار موسى من بعض بنات الحارث ليستحد بها فأعارته، قالت: فغفلت عن صبي لي، فدرج إليه حتى أتاه فوضعه على فخذه، فلما رأيته فزعت فزعة عرف ذاك مني وفي يده الموسى، فقال: أتخشين أن أقتله؟ ما كنت لأفعل ذاك إن شاء الله، وكانت تقول: ما رأيت أسيرا قط خيرا من خبيب، لقد رأيته يأكل من قطف عنب وما بمكة يومئذ ثمرة، وإنه لموثق في الحديد، وما كان إلا رزق رزقه الله، فخرجوا به من الحرم ليقتلوه، فقال: دعوني أصلي ركعتين، ثم انصرف إليهم، فقال: لولا أن تروا أن ما بي جزع من الموت لزدت، فكان أول من سن الركعتين عند القتل هو، ثم قال: اللهم أحصهم عددا، ثم قال: [البحر الطويل] ما أبالي حين أقتل مسلما ... على أي شق كان لله مصرعي، وذلك في ذات الإله وإن يشأ ... يبارك على أوصال شلو ممزع ثم قام إليه عقبة بن الحارث فقتله، وبعثت قريش إلى عاصم ليؤتوا بشيء من جسده يعرفونه، وكان عاصم قتل عظيما من عظمائهم يوم بدر، فبعث الله عليه مثل الظلة من الدبر، فحمته من رسلهم، فلم يقدروا منه على شيء", "4086"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا عبد الله بن محمد، حدثنا سفيان، عن عمرو، سمع جابرا، يقول: «الذي قتل خبيبا، هو أبو سروعة»", "4087"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا أبو معمر، حدثنا عبد الوارث، حدثنا عبد العزيز، عن أنس رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم سبعين رجلا لحاجة، يقال لهم القراء، فعرض لهم حيان من بني سليم، رعل، وذكوان، عند بئر يقال لها بئر معونة، فقال القوم: والله ما إياكم أردنا، إنما نحن مجتازون في حاجة للنبي صلى الله عليه وسلم، فقتلوهم «فدعا النبي صلى الله عليه وسلم عليهم شهرا في صلاة الغداة، وذلك بدء القنوت، وما كنا نقنت» قال عبد العزيز وسأل رجل أنسا عن القنوت أبعد الركوع أو عند فراغ من القراءة؟ قال: «لا بل عند فراغ من القراءة»", "4088"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا مسلم، حدثنا هشام، حدثنا قتادة، عن أنس، قال: «قنت رسول الله صلى الله عليه وسلم شهرا، بعد الركوع يدعو على أحياء من العرب»", "4089"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثني عبد الأعلى بن حماد، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، عن أنس بن مالك رضي الله عنه، أن رعلا، وذكوان، وعصية، وبني لحيان، استمدوا رسول الله صلى الله عليه وسلم على عدو، فأمدهم بسبعين من الأنصار، كنا نسميهم القراء في زمانهم، كانوا يحتطبون بالنهار، ويصلون بالليل، حتى كانوا ببئر معونة قتلوهم وغدروا بهم، فبلغ النبي صلى الله عليه وسلم «فقنت شهرا يدعو في الصبح على أحياء من أحياء العرب، على رعل، وذكوان، وعصية، وبني لحيان» قال أنس: \" فقرأنا فيهم قرآنا، ثم إن ذلك رفع: بلغوا عنا قومنا أنا لقينا ربنا فرضي عنا وأرضانا \" وعن قتادة، عن أنس بن مالك حدثه أن نبي الله صلى الله عليه وسلم: «قنت شهرا في صلاة الصبح يدعو على أحياء من أحياء العرب، على رعل، وذكوان، وعصية، وبني لحيان» زاد خليفة، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، حدثنا أنس: «أن أولئك السبعين من الأنصار قتلوا ببئر معونة قرآنا كتابا» نحوه", "4090"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا موسى بن إسماعيل، حدثنا همام، عن إسحاق بن عبد الله بن أبي طلحة، قال: حدثني أنس، أن النبي صلى الله عليه وسلم: «بعث خاله، أخ لأم سليم، في سبعين راكبا» وكان رئيس المشركين عامر بن الطفيل، خير بين ثلاث خصال، فقال: يكون لك أهل السهل ولي أهل المدر، أو أكون خليفتك، أو أغزوك بأهل غطفان بألف وألف؟ فطعن عامر في بيت أم فلان، فقال: غدة كغدة البكر، في بيت امرأة من آل فلان، ائتوني بفرسي، فمات على ظهر فرسه، فانطلق حرام أخو أم سليم وهو رجل أعرج، ورجل من بني فلان، قال: كونا قريبا حتى آتيهم فإن آمنوني كنتم، وإن قتلوني أتيتم أصحابكم، فقال: أتؤمنوني أبلغ رسالة رسول الله صلى الله عليه وسلم، فجعل يحدثهم، وأومئوا إلى رجل، فأتاه من خلفه فطعنه، - قال همام أحسبه - حتى أنفذه بالرمح، قال: الله أكبر ، فزت ورب الكعبة، فلحق الرجل، فقتلوا كلهم غير الأعرج، كان في رأس جبل، فأنزل الله علينا، ثم كان من المنسوخ: إنا قد لقينا ربنا فرضي عنا وأرضانا «فدعا النبي صلى الله عليه وسلم عليهم ثلاثين صباحا، على رعل، وذكوان، وبني لحيان، وعصية، الذين عصوا الله ورسوله صلى الله عليه وسلم»", "4091"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثني حبان، أخبرنا عبد الله، أخبرنا معمر، قال: حدثني ثمامة بن عبد الله بن أنس، أنه سمع أنس بن مالك رضي الله عنه، يقول: \" لما طعن حرام بن ملحان، وكان خاله يوم بئر معونة، قال: بالدم هكذا فنضحه على وجهه ورأسه، ثم قال: فزت ورب الكعبة \"", "4092"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، عن عائشة رضي الله عنها، قالت: استأذن النبي صلى الله عليه وسلم أبو بكر في الخروج حين اشتد عليه الأذى، فقال له: أقم فقال يا رسول الله أتطمع أن يؤذن لك؟ فكان رسول الله صلى الله عليه وسلم يقول: «إني لأرجو ذلك» قالت: فانتظره أبو بكر، فأتاه رسول الله صلى الله عليه وسلم ذات يوم ظهرا، فناداه فقال: «أخرج من عندك» فقال أبو بكر: إنما هما ابنتاي، فقال «أشعرت أنه قد أذن لي في الخروج» فقال: يا رسول الله الصحبة، فقال النبي صلى الله عليه وسلم: «الصحبة» قال: يا رسول الله، عندي ناقتان، قد كنت أعددتهما للخروج، فأعطى النبي صلى الله عليه وسلم إحداهما - وهي الجدعاء - فركبا، فانطلقا حتى أتيا الغار - وهو بثور - فتواريا فيه، فكان عامر بن فهيرة غلاما لعبد الله بن الطفيل بن سخبرة، أخو عائشة لأمها، وكانت لأبي بكر منحة، فكان يروح بها ويغدو عليهم ويصبح، فيدلج إليهما ثم يسرح، فلا يفطن به أحد من الرعاء، فلما خرج خرج معهما يعقبانه حتى قدما المدينة، فقتل عامر بن فهيرة يوم بئر معونة وعن أبي أسامة، قال: قال هشام بن عروة، فأخبرني أبي، قال: لما قتل الذين ببئر معونة، وأسر عمرو بن أمية الضمري، قال: له عامر بن الطفيل من هذا؟ فأشار إلى قتيل، فقال له عمرو بن أمية: هذا عامر بن فهيرة، فقال: لقد رأيته بعد ما قتل رفع إلى السماء، حتى إني لأنظر إلى السماء بينه وبين الأرض، ثم وضع، فأتى النبي صلى الله عليه وسلم خبرهم فنعاهم، فقال: \" إن أصحابكم قد أصيبوا، وإنهم قد سألوا ربهم، فقالوا: ربنا أخبر عنا إخواننا بما رضينا عنك، ورضيت عنا، فأخبرهم عنهم \" وأصيب يومئذ فيهم عروة بن أسماء بن الصلت، فسمي عروة، به ومنذر بن عمرو، سمي به منذرا", "4093"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا محمد، أخبرنا عبد الله، أخبرنا سليمان التيمي، عن أبي مجلز، عن أنس رضي الله عنه، قال: «قنت النبي صلى الله عليه وسلم بعد الركوع شهرا يدعو على رعل، وذكوان، ويقول عصية عصت الله ورسوله»", "4094"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا يحيى بن بكير، حدثنا مالك، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك، قال: «دعا النبي صلى الله عليه وسلم على الذين قتلوا يعني أصحابه ببئر معونة ثلاثين صباحا حين يدعو على رعل، ولحيان، وعصية عصت الله ورسوله صلى الله عليه وسلم» قال أنس: \" فأنزل الله تعالى لنبيه صلى الله عليه وسلم في الذين قتلوا - أصحاب بئر معونة - قرآنا قرأناه حتى نسخ بعد: بلغوا قومنا فقد لقينا ربنا فرضي عنا ورضينا عنه \"", "4095"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا موسى بن إسماعيل، حدثنا عبد الواحد، حدثنا عاصم الأحول، قال: سألت أنس بن مالك رضي الله عنه، عن القنوت في الصلاة؟ فقال: نعم، فقلت: كان قبل الركوع أو بعده؟ قال: قبله، قلت: فإن فلانا أخبرني عنك أنك قلت بعده، قال: كذب «إنما قنت رسول الله صلى الله عليه وسلم بعد الركوع شهرا أنه كان بعث ناسا يقال لهم القراء، وهم سبعون رجلا إلى ناس من المشركين، وبينهم وبين رسول الله صلى الله عليه وسلم عهد قبلهم، فظهر هؤلاء الذين كان بينهم وبين رسول الله صلى الله عليه وسلم عهد، فقنت رسول الله صلى الله عليه وسلم بعد الركوع شهرا يدعو عليهم»", "4096"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثنا إسحاق بن نصر، حدثنا عبد الرزاق، أخبرنا ابن جريج، عن موسى بن عقبة، عن نافع، عن ابن عمر رضي الله عنهما، قال: \" حاربت النضير، وقريظة، فأجلى بني النضير، وأقر قريظة ومن عليهم، حتى حاربت قريظة، فقتل رجالهم، وقسم نساءهم وأولادهم وأموالهم بين المسلمين، إلا بعضهم لحقوا بالنبي صلى الله عليه وسلم فآمنهم وأسلموا، وأجلى يهود المدينة كلهم: بني قينقاع، وهم رهط عبد الله بن سلام، ويهود بني حارثة، وكل يهود المدينة \"", "4028"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثني الحسن بن مدرك، حدثنا يحيى بن حماد، أخبرنا أبو عوانة، عن أبي بشر، عن سعيد بن جبير، قال: قلت لابن عباس: سورة الحشر، قال: «قل سورة النضير» تابعه هشيم، عن أبي بشر", "4029"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثنا عبد الله بن أبي الأسود، حدثنا معتمر، عن أبيه، سمعت أنس بن مالك رضي الله عنه، قال: «كان الرجل يجعل للنبي صلى الله عليه وسلم النخلات، حتى افتتح قريظة، والنضير، فكان بعد ذلك يرد عليهم»", "4030"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثنا آدم، حدثنا الليث، عن نافع، عن ابن عمر رضي الله عنهما، قال: «حرق رسول الله صلى الله عليه وسلم نخل بني النضير وقطع، وهي البويرة» فنزلت: {ما قطعتم من لينة أو تركتموها قائمة على أصولها فبإذن الله} [الحشر: 5]", "4031"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثني إسحاق، أخبرنا حبان، أخبرنا جويرية بن أسماء، عن نافع، عن ابن عمر رضي الله عنهما، \" أن النبي صلى الله عليه وسلم: حرق نخل بني النضير \" قال: ولها يقول حسان بن ثابت: [البحر الوافر] وهان على سراة بني لؤي ... حريق بالبويرة مستطير قال: فأجابه أبو سفيان بن الحارث [البحر الوافر] أدام الله ذلك من صنيع ... وحرق في نواحيها السعير، ستعلم أينا منها بنزه ... وتعلم أي أرضينا تضير", "4032"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني مالك بن أوس بن الحدثان النصري، أن عمر بن الخطاب رضي الله عنه دعاه، إذ جاءه حاجبه يرفا، فقال: هل لك في عثمان، وعبد الرحمن، والزبير، وسعد يستأذنون؟ فقال: نعم فأدخلهم، فلبث قليلا ثم جاء فقال: هل لك في عباس، وعلي يستأذنان؟ قال: نعم، فلما دخلا قال عباس: يا أمير المؤمنين اقض بيني وبين هذا، وهما يختصمان في الذي أفاء الله على رسوله صلى الله عليه وسلم من بني النضير، فاستب علي، وعباس، فقال الرهط: يا أمير المؤمنين اقض بينهما، وأرح أحدهما من الآخر، فقال عمر: اتئدوا أنشدكم بالله الذي بإذنه تقوم السماء والأرض، هل تعلمون أن رسول الله صلى الله عليه وسلم، قال: «لا نورث ما تركنا صدقة» يريد بذلك نفسه؟ قالوا: قد قال ذلك، فأقبل عمر على عباس، وعلي فقال: أنشدكما بالله، هل تعلمان أن رسول الله صلى الله عليه وسلم قد قال ذلك؟ قالا: نعم، قال: فإني أحدثكم عن هذا الأمر، إن الله سبحانه كان خص رسوله صلى الله عليه وسلم في هذا الفيء بشيء لم يعطه أحدا غيره، فقال جل ذكره: {وما أفاء الله على رسوله منهم فما أوجفتم عليه من خيل ولا ركاب} [الحشر: 6]- إلى قوله - {قدير} [الحشر: 6]، فكانت هذه خالصة لرسول الله صلى الله عليه وسلم، ثم والله ما احتازها دونكم، ولا استأثرها عليكم، لقد أعطاكموها وقسمها فيكم حتى بقي هذا المال منها، فكان رسول الله صلى الله عليه وسلم ينفق على أهله نفقة سنتهم من هذا المال، ثم يأخذ ما بقي فيجعله مجعل مال الله، فعمل ذلك رسول الله صلى الله عليه وسلم حياته، ثم توفي النبي صلى الله عليه وسلم، فقال أبو بكر: فأنا ولي رسول الله صلى الله عليه وسلم، فقبضه أبو بكر فعمل فيه بما عمل به رسول الله صلى الله عليه وسلم، وأنتم حينئذ، فأقبل على علي، وعباس وقال: تذكران أن أبا بكر فيه كما تقولان، والله يعلم: إنه فيه لصادق بار راشد تابع للحق؟ ثم توفى الله أبا بكر، فقلت: أنا ولي رسول الله صلى الله عليه وسلم، وأبي بكر، فقبضته سنتين من إمارتي أعمل فيه بما عمل فيه رسول الله صلى الله عليه وسلم، وأبو بكر، والله يعلم: أني فيه صادق بار راشد تابع للحق؟ ثم جئتماني كلاكما، وكلمتكما واحدة وأمركما جميع، فجئتني - يعني عباسا - فقلت لكما: إن رسول الله صلى الله عليه وسلم، قال: «لا نورث ما تركنا صدقة» فلما بدا لي أن أدفعه إليكما قلت: إن شئتما دفعته إليكما، على أن عليكما عهد الله وميثاقه: لتعملان فيه بما عمل فيه رسول الله صلى الله عليه وسلم وأبو بكر وما عملت فيه منذ وليت، وإلا فلا تكلماني، فقلتما ادفعه إلينا بذلك، فدفعته إليكما، أفتلتمسان مني قضاء غير ذلك، فوالله الذي بإذنه تقوم السماء والأرض، لا أقضي فيه بقضاء غير ذلك حتى تقوم الساعة، فإن عجزتما عنه فادفعا إلي فأنا أكفيكماه،", "4033"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "قال: فحدثت هذا الحديث عروة بن الزبير، فقال: صدق مالك بن أوس: أنا سمعت عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم، تقول: \" أرسل أزواج النبي صلى الله عليه وسلم عثمان إلى أبي بكر، يسألنه ثمنهن مما أفاء الله على رسوله صلى الله عليه وسلم فكنت أنا أردهن، فقلت لهن: ألا تتقين الله، ألم تعلمن أن النبي صلى الله عليه وسلم كان يقول: «لا نورث، ما تركنا صدقة - يريد بذلك نفسه - إنما يأكل آل محمد صلى الله عليه وسلم في هذا المال» فانتهى أزواج النبي صلى الله عليه وسلم إلى ما أخبرتهن، قال: فكانت هذه الصدقة بيد علي، منعها علي عباسا فغلبه عليها، ثم كان بيد حسن بن علي، ثم بيد حسين بن علي، ثم بيد علي بن حسين، وحسن بن حسن، كلاهما كانا يتداولانها، ثم بيد زيد بن حسن، وهي صدقة رسول الله صلى الله عليه وسلم حقا", "4034"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثنا إبراهيم بن موسى، أخبرنا هشام، أخبرنا معمر، عن الزهري، عن عروة، عن عائشة، أن فاطمة عليها السلام، والعباس، أتيا أبا بكر يلتمسان ميراثهما، أرضه من فدك، وسهمه من خيبر، فقال أبو بكر: سمعت النبي صلى الله عليه وسلم، يقول: «لا نورث ما تركنا صدقة، إنما يأكل آل محمد في هذا المال» والله لقرابة رسول الله صلى الله عليه وسلم أحب إلي أن أصل من قرابتي", "4035"], ["باب قتل كعب بن الأشرف", "حدثنا علي بن عبد الله، حدثنا سفيان، قال عمرو: سمعت جابر بن عبد الله رضي الله عنهما، يقول: قال رسول الله صلى الله عليه وسلم: «من لكعب بن الأشرف، فإنه قد آذى الله ورسوله»، فقام محمد بن مسلمة فقال: يا رسول الله، أتحب أن أقتله؟ قال: «نعم»، قال: فأذن لي أن أقول شيئا، قال: «قل»، فأتاه محمد بن مسلمة فقال: إن هذا الرجل قد سألنا صدقة، وإنه قد عنانا وإني قد أتيتك أستسلفك، قال: وأيضا والله لتملنه، قال: إنا قد اتبعناه، فلا نحب أن ندعه حتى ننظر إلى أي شيء يصير شأنه، وقد أردنا أن تسلفنا وسقا أو وسقين - وحدثنا عمرو غير مرة فلم يذكر وسقا أو وسقين أو: فقلت له: فيه وسقا أو وسقين؟ فقال: أرى فيه وسقا أو وسقين - فقال: نعم، ارهنوني، قالوا: أي شيء تريد؟ قال: ارهنوني نساءكم، قالوا: كيف نرهنك نساءنا وأنت أجمل العرب، قال: فارهنوني أبناءكم، قالوا: كيف نرهنك أبناءنا، فيسب أحدهم، فيقال: رهن بوسق أو وسقين، هذا عار علينا، ولكنا نرهنك اللأمة - قال سفيان: يعني السلاح - فواعده أن يأتيه، فجاءه ليلا ومعه أبو نائلة، وهو أخو كعب من الرضاعة، فدعاهم إلى الحصن، فنزل إليهم، فقالت له امرأته: أين تخرج هذه الساعة؟ فقال إنما هو محمد بن مسلمة، وأخي أبو نائلة، وقال غير عمرو، قالت: أسمع صوتا كأنه يقطر منه الدم، قال: إنما هو أخي محمد بن مسلمة ورضيعي أبو نائلة إن الكريم لو دعي إلى طعنة بليل لأجاب، قال: ويدخل محمد بن مسلمة معه رجلين - قيل لسفيان: سماهم عمرو؟ قال: سمى بعضهم - قال عمرو: جاء معه برجلين، وقال: غير عمرو: أبو عبس بن جبر، والحارث بن أوس، وعباد بن بشر، قال عمرو: جاء معه برجلين، فقال: إذا ما جاء فإني قائل بشعره فأشمه، فإذا رأيتموني استمكنت من رأسه، فدونكم فاضربوه، وقال مرة: ثم أشمكم، فنزل إليهم متوشحا وهو ينفح منه ريح الطيب، فقال: ما رأيت كاليوم ريحا، أي أطيب، وقال غير عمرو: قال: عندي أعطر نساء العرب وأكمل العرب، قال عمرو: فقال أتأذن لي أن أشم رأسك؟ قال: نعم، فشمه ثم أشم أصحابه، ثم قال: أتأذن لي؟ قال: نعم، فلما استمكن منه، قال: دونكم، فقتلوه، ثم أتوا النبي صلى الله عليه وسلم فأخبروه", "4037"], ["باب قتل أبي رافع عبد الله بن أبي الحقيق", "حدثني إسحاق بن نصر، حدثنا يحيى بن آدم، حدثنا ابن أبي زائدة، عن أبيه، عن أبي إسحاق، عن البراء بن عازب، رضي الله عنهما، قال: «بعث رسول الله صلى الله عليه وسلم رهطا إلى أبي رافع، فدخل عليه عبد الله بن عتيك بيته ليلا وهو نائم فقتله»", "4038"], ["باب قتل أبي رافع عبد الله بن أبي الحقيق", "حدثنا يوسف بن موسى، حدثنا عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء بن عازب، قال: بعث رسول الله صلى الله عليه وسلم إلى أبي رافع اليهودي رجالا من الأنصار، فأمر عليهم عبد الله بن عتيك، وكان أبو رافع يؤذي رسول الله صلى الله عليه وسلم ويعين عليه، وكان في حصن له بأرض الحجاز، فلما دنوا منه، وقد غربت الشمس، وراح الناس بسرحهم، فقال عبد الله لأصحابه: اجلسوا مكانكم، فإني منطلق، ومتلطف للبواب، لعلي أن أدخل، فأقبل حتى دنا من الباب، ثم تقنع بثوبه كأنه يقضي حاجة، وقد دخل الناس، فهتف به البواب، يا عبد الله: إن كنت تريد أن تدخل فادخل، فإني أريد أن أغلق الباب، فدخلت فكمنت، فلما دخل الناس أغلق الباب، ثم علق الأغاليق على وتد، قال: فقمت إلى الأقاليد فأخذتها، ففتحت الباب، وكان أبو رافع يسمر عنده، وكان في علالي له، فلما ذهب عنه أهل سمره صعدت إليه، فجعلت كلما فتحت بابا أغلقت علي من داخل، قلت: إن القوم نذروا بي لم يخلصوا إلي حتى أقتله، فانتهيت إليه، فإذا هو في بيت مظلم وسط عياله، لا أدري أين هو من البيت، فقلت: يا أبا رافع، قال: من هذا؟ فأهويت نحو الصوت فأضربه ضربة بالسيف وأنا دهش، فما أغنيت شيئا، وصاح، فخرجت من البيت، فأمكث غير بعيد، ثم دخلت إليه، فقلت: ما هذا الصوت يا أبا رافع؟ فقال: لأمك الويل، إن رجلا في البيت ضربني قبل بالسيف، قال: فأضربه ضربة أثخنته ولم أقتله، ثم وضعت ظبة السيف في بطنه حتى أخذ في ظهره، فعرفت أني قتلته، فجعلت أفتح الأبواب بابا بابا، حتى انتهيت إلى درجة له، فوضعت رجلي، وأنا أرى أني قد انتهيت إلى الأرض، فوقعت في ليلة مقمرة، فانكسرت ساقي فعصبتها بعمامة، ثم انطلقت حتى جلست على الباب، فقلت: لا أخرج الليلة حتى أعلم: أقتلته؟ فلما صاح الديك قام الناعي على السور، فقال: أنعى أبا رافع تاجر أهل الحجاز، فانطلقت إلى أصحابي، فقلت: النجاء، فقد قتل الله أبا رافع، فانتهيت إلى النبي صلى الله عليه وسلم فحدثته، فقال: «ابسط رجلك» فبسطت رجلي فمسحها، فكأنها لم أشتكها قط", "4039"], ["باب قتل أبي رافع عبد الله بن أبي الحقيق", "حدثنا أحمد بن عثمان، حدثنا شريح هو ابن مسلمة، حدثنا إبراهيم بن يوسف، عن أبيه، عن أبي إسحاق، قال: سمعت البراء بن عازب رضي الله عنه، قال: «بعث رسول الله صلى الله عليه وسلم إلى أبي رافع عبد الله بن عتيك، وعبد الله بن عتبة، في ناس معهم، فانطلقوا حتى دنوا من الحصن» فقال لهم عبد الله بن عتيك: امكثوا أنتم حتى أنطلق أنا فأنظر، قال: فتلطفت أن أدخل الحصن، ففقدوا حمارا لهم، قال: فخرجوا بقبس يطلبونه، قال: فخشيت أن أعرف، قال: فغطيت رأسي وجلست كأني أقضي حاجة، ثم نادى صاحب الباب، من أراد أن يدخل فليدخل قبل أن أغلقه، فدخلت ثم اختبأت في مربط حمار عند باب الحصن، فتعشوا عند أبي رافع، وتحدثوا حتى ذهبت ساعة من الليل، ثم رجعوا إلى بيوتهم، فلما هدأت الأصوات، ولا أسمع حركة خرجت، قال: ورأيت صاحب الباب، حيث وضع مفتاح الحصن في كوة، فأخذته ففتحت به باب الحصن، قال: قلت: إن نذر بي القوم انطلقت على مهل، ثم عمدت إلى أبواب بيوتهم، فغلقتها عليهم من ظاهر، ثم صعدت إلى أبي رافع في سلم، فإذا البيت مظلم، قد طفئ سراجه، فلم أدر أين الرجل، فقلت: يا أبا رافع قال: من هذا؟ قال: فعمدت نحو الصوت فأضربه وصاح، فلم تغن شيئا، قال: ثم جئت كأني أغيثه، فقلت: ما لك يا أبا رافع؟ وغيرت صوتي، فقال: ألا أعجبك لأمك الويل، دخل علي رجل فضربني بالسيف، قال: فعمدت له أيضا فأضربه أخرى، فلم تغن شيئا، فصاح وقام أهله، قال: ثم جئت وغيرت صوتي كهيئة المغيث فإذا هو مستلق على ظهره، فأضع السيف في بطنه ثم أنكفئ عليه حتى سمعت صوت العظم ثم خرجت دهشا حتى أتيت السلم، أريد أن أنزل فأسقط منه، فانخلعت رجلي فعصبتها، ثم أتيت أصحابي أحجل، فقلت: انطلقوا فبشروا رسول الله صلى الله عليه وسلم، فإني لا أبرح حتى أسمع الناعية، فلما كان في وجه الصبح صعد الناعية، فقال: أنعى أبا رافع، قال: فقمت أمشي ما بي قلبة، فأدركت أصحابي قبل أن يأتوا النبي صلى الله عليه وسلم فبشرته", "4040"], ["باب غزوة بني المصطلق، من خزاعة، وهي غزوة المريسيع", "حدثنا قتيبة بن سعيد، أخبرنا إسماعيل بن جعفر، عن ربيعة بن أبي عبد الرحمن، عن محمد بن يحيى بن حبان، عن ابن محيريز، أنه قال: دخلت المسجد، فرأيت أبا سعيد الخدري فجلست إليه، فسألته عن العزل، قال أبو سعيد: خرجنا مع رسول الله صلى الله عليه وسلم في غزوة بني المصطلق، فأصبنا سبيا من سبي العرب، فاشتهينا النساء، واشتدت علينا العزبة وأحببنا العزل، فأردنا أن نعزل، وقلنا نعزل ورسول الله صلى الله عليه وسلم بين أظهرنا قبل أن نسأله ، فسألناه عن ذلك، فقال: «ما عليكم أن لا تفعلوا، ما من نسمة كائنة إلى يوم القيامة إلا وهي كائنة»", "4138"], ["باب غزوة بني المصطلق، من خزاعة، وهي غزوة المريسيع", "حدثنا محمود، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن أبي سلمة، عن جابر بن عبد الله، قال: غزونا مع رسول الله صلى الله عليه وسلم غزوة نجد، فلما أدركته القائلة، وهو في واد كثير العضاه، فنزل تحت شجرة واستظل بها وعلق سيفه، فتفرق الناس في الشجر يستظلون، وبينا نحن كذلك إذ دعانا رسول الله صلى الله عليه وسلم فجئنا، فإذا أعرابي قاعد بين يديه، فقال: \" إن هذا أتاني وأنا نائم، فاخترط سيفي، فاستيقظت وهو قائم على رأسي، مخترط صلتا، قال: من يمنعك مني؟ قلت: الله، فشامه ثم قعد، فهو هذا \" قال: ولم يعاقبه رسول الله صلى الله عليه وسلم", "4139"], ["باب غزوة أنمار", "حدثنا آدم، حدثنا ابن أبي ذئب، حدثنا عثمان بن عبد الله بن سراقة، عن جابر بن عبد الله الأنصاري، قال: «رأيت النبي صلى الله عليه وسلم في غزوة أنمار يصلي على راحلته متوجها قبل المشرق متطوعا»", "4140"], ["باب حديث", "حدثنا عبد العزيز بن عبد الله، حدثنا إبراهيم بن سعد، عن صالح، عن ابن شهاب، قال: حدثني عروة بن الزبير، وسعيد بن المسيب، وعلقمة بن وقاص، وعبيد الله بن عبد الله بن عتبة بن مسعود، عن عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم، حين قال لها: أهل الإفك ما قالوا، وكلهم حدثني طائفة من حديثها، وبعضهم كان أوعى لحديثها من بعض، وأثبت له اقتصاصا، وقد وعيت عن كل رجل منهم الحديث الذي حدثني عن عائشة، وبعض حديثهم يصدق بعضا، وإن كان بعضهم أوعى له من بعض، قالوا: قالت عائشة: كان رسول الله صلى الله عليه وسلم إذا أراد سفرا أقرع بين أزواجه، فأيهن خرج سهمها خرج بها رسول الله صلى الله عليه وسلم معه، قالت عائشة: فأقرع بيننا في غزوة غزاها فخرج فيها سهمي، فخرجت مع رسول الله صلى الله عليه وسلم بعد ما أنزل الحجاب، فكنت أحمل في هودجي وأنزل فيه، فسرنا حتى إذا فرغ رسول الله صلى الله عليه وسلم من غزوته تلك وقفل، دنونا من المدينة قافلين، آذن ليلة بالرحيل، فقمت حين آذنوا بالرحيل، فمشيت حتى جاوزت الجيش، فلما قضيت شأني أقبلت إلى رحلي، فلمست صدري، فإذا عقد لي من جزع ظفار قد انقطع، فرجعت فالتمست عقدي فحبسني ابتغاؤه، قالت: وأقبل الرهط الذين كانوا يرحلوني، فاحتملوا هودجي فرحلوه على بعيري الذي كنت أركب عليه، وهم يحسبون أني فيه، وكان النساء إذ ذاك خفافا لم يهبلن، ولم يغشهن اللحم، إنما يأكلن العلقة من الطعام، فلم يستنكر القوم خفة الهودج حين رفعوه وحملوه، وكنت جارية حديثة السن، فبعثوا الجمل فساروا، ووجدت عقدي بعد ما استمر الجيش، فجئت منازلهم وليس بها منهم داع ولا مجيب، فتيممت منزلي الذي كنت به، وظننت أنهم سيفقدوني فيرجعون إلي، فبينا أنا جالسة في منزلي، غلبتني عيني فنمت، وكان صفوان بن المعطل السلمي ثم الذكواني من وراء الجيش، فأصبح عند منزلي، فرأى سواد إنسان نائم فعرفني حين رآني، وكان رآني قبل الحجاب، فاستيقظت باسترجاعه حين عرفني، فخمرت وجهي بجلبابي، ووالله ما تكلمنا بكلمة، ولا سمعت منه كلمة غير استرجاعه، وهوى حتى أناخ راحلته، فوطئ على يدها، فقمت إليها فركبتها، فانطلق يقود بي الراحلة حتى أتينا الجيش موغرين في نحر الظهيرة وهم نزول، قالت: فهلك من هلك، وكان الذي تولى كبر الإفك عبد الله بن أبي ابن سلول، قال عروة: أخبرت أنه كان يشاع ويتحدث به عنده، فيقره ويستمعه ويستوشيه، وقال عروة أيضا: لم يسم من أهل الإفك أيضا إلا حسان بن ثابت، ومسطح بن أثاثة، وحمنة بنت جحش، في ناس آخرين لا علم لي بهم، غير أنهم عصبة، كما قال الله تعالى، وإن كبر ذلك يقال له: عبد الله بن أبي ابن سلول، قال عروة: كانت عائشة تكره أن يسب عندها حسان، وتقول: إنه الذي قال: [البحر الوافر] فإن أبي ووالده وعرضي لعرض محمد منكم وقاء قالت عائشة: فقدمنا المدينة، فاشتكيت حين قدمت شهرا، والناس يفيضون في قول أصحاب الإفك، لا أشعر بشيء من ذلك، وهو يريبني في وجعي أني لا أعرف من رسول الله صلى الله عليه وسلم اللطف الذي كنت أرى منه حين أشتكي، إنما يدخل علي رسول الله صلى الله عليه وسلم فيسلم، ثم يقول: «كيف تيكم»، ثم ينصرف، فذلك يريبني ولا أشعر بالشر، حتى خرجت حين نقهت، فخرجت مع أم مسطح قبل المناصع، وكان متبرزنا، وكنا لا نخرج إلا ليلا إلى ليل، وذلك قبل أن نتخذ الكنف قريبا من بيوتنا، قالت: وأمرنا أمر العرب الأول في البرية قبل الغائط، وكنا نتأذى بالكنف أن نتخذها عند بيوتنا، قالت: فانطلقت أنا وأم مسطح، وهي ابنة أبي رهم بن المطلب بن عبد مناف، وأمها بنت صخر بن عامر، خالة أبي بكر الصديق، وابنها مسطح بن أثاثة بن عباد بن المطلب، فأقبلت أنا وأم مسطح قبل بيتي حين فرغنا من شأننا، فعثرت أم مسطح في مرطها فقالت: تعس مسطح، فقلت لها: بئس ما قلت، أتسبين رجلا شهد بدرا؟ فقالت: أي هنتاه ولم تسمعي ما قال؟ قالت: وقلت: ما قال؟ فأخبرتني بقول أهل الإفك، قالت: فازددت مرضا على مرضي، فلما رجعت إلى بيتي دخل علي رسول الله صلى الله عليه وسلم فسلم، ثم قال: «كيف تيكم»، فقلت له: أتأذن لي أن آتي أبوي؟ قالت: وأريد أن أستيقن الخبر من قبلهما، قالت: فأذن لي رسول الله صلى الله عليه وسلم، فقلت لأمي: يا أمتاه، ماذا يتحدث الناس؟ قالت: يا بنية، هوني عليك، فوالله لقلما كانت امرأة قط وضيئة عند رجل يحبها، لها ضرائر، إلا كثرن عليها، قالت: فقلت: سبحان الله، أولقد تحدث الناس بهذا؟ قالت: فبكيت تلك الليلة حتى أصبحت لا يرقأ لي دمع ولا أكتحل بنوم، ثم أصبحت أبكي، قالت: ودعا رسول الله صلى الله عليه وسلم علي بن أبي طالب وأسامة بن زيد حين استلبث الوحي، يسألهما ويستشيرهما في فراق أهله، قالت: فأما أسامة فأشار على رسول الله صلى الله عليه وسلم بالذي يعلم من براءة أهله، وبالذي يعلم لهم في نفسه، فقال أسامة: أهلك، ولا نعلم إلا خيرا، وأما علي فقال: يا رسول الله، لم يضيق الله عليك، والنساء سواها كثير، وسل الجارية تصدقك، قالت: فدعا رسول الله صلى الله عليه وسلم بريرة، فقال: «أي بريرة، هل رأيت من شيء يريبك؟». قالت له بريرة: والذي بعثك بالحق، ما رأيت عليها أمرا قط أغمصه غير أنها جارية حديثة السن، تنام عن عجين أهلها، فتأتي الداجن فتأكله، قالت: فقام رسول الله صلى الله عليه وسلم من يومه فاستعذر من عبد الله بن أبي، وهو على المنبر، فقال: «يا معشر المسلمين، من يعذرني من رجل قد بلغني عنه أذاه في أهلي، والله ما علمت على أهلي إلا خيرا، ولقد ذكروا رجلا ما علمت عليه إلا خيرا، وما يدخل على أهلي إلا معي». قالت: فقام سعد بن معاذ أخو بني عبد الأشهل، فقال : أنا يا رسول الله أعذرك، فإن كان من الأوس ضربت عنقه، وإن كان من إخواننا من الخزرج أمرتنا ففعلنا أمرك، قالت: فقام رجل من الخزرج، وكانت أم حسان بنت عمه من فخذه، وهو سعد بن عبادة، وهو سيد الخزرج، قالت: وكان قبل ذلك رجلا صالحا، ولكن احتملته الحمية، فقال لسعد: كذبت لعمر الله لا تقتله، ولا تقدر على قتله، ولو كان من رهطك ما أحببت أن يقتل. فقام أسيد بن حضير، وهو ابن عم سعد، فقال لسعد بن عبادة: كذبت لعمر الله لنقتلنه، فإنك منافق تجادل عن المنافقين، قالت: فثار الحيان الأوس، والخزرج حتى هموا أن يقتتلوا، ورسول الله صلى الله عليه وسلم قائم على المنبر، قالت: فلم يزل رسول الله صلى الله عليه وسلم يخفضهم، حتى سكتوا وسكت، قالت: فبكيت يومي ذلك كله لا يرقأ لي دمع ولا أكتحل بنوم، قالت: وأصبح أبواي عندي، وقد بكيت ليلتين ويوما، لا يرقأ لي دمع ولا أكتحل بنوم، حتى إني لأظن أن البكاء فالق كبدي، فبينا أبواي جالسان عندي وأنا أبكي، فاستأذنت علي امرأة من الأنصار فأذنت لها، فجلست تبكي معي، قالت: فبينا نحن على ذلك دخل رسول الله صلى الله عليه وسلم علينا فسلم ثم جلس، قالت: ولم يجلس عندي منذ قيل ما قيل قبلها، وقد لبث شهرا لا يوحى إليه في شأني بشيء، قالت: فتشهد رسول الله صلى الله عليه وسلم حين جلس، ثم قال: «أما بعد، يا عائشة، إنه بلغني عنك كذا وكذا، فإن كنت بريئة، فسيبرئك الله، وإن كنت ألممت بذنب، فاستغفري الله وتوبي إليه، فإن العبد إذا اعترف ثم تاب، تاب الله عليه»، قالت: فلما قضى رسول الله صلى الله عليه وسلم مقالته قلص دمعي حتى ما أحس منه قطرة، فقلت لأبي: أجب رسول الله صلى الله عليه وسلم عني فيما قال: فقال أبي: والله ما أدري ما أقول لرسول الله صلى الله عليه وسلم، فقلت لأمي: أجيبي رسول الله صلى الله عليه وسلم فيما قال: قالت أمي: والله ما أدري ما أقول لرسول الله صلى الله عليه وسلم، فقلت: وأنا جارية حديثة السن: لا أقرأ من القرآن كثيرا: إني والله لقد علمت: لقد سمعتم هذا الحديث حتى استقر في أنفسكم وصدقتم به، فلئن قلت لكم: إني بريئة، لا تصدقوني، ولئن اعترفت لكم بأمر، والله يعلم أني منه بريئة، لتصدقني، فوالله لا أجد لي ولكم مثلا إلا أبا يوسف حين قال: {فصبر جميل والله المستعان على ما تصفون} [يوسف: 18] ثم تحولت واضطجعت على فراشي، والله يعلم أني حينئذ بريئة، وأن الله مبرئي ببراءتي، ولكن والله ما كنت أظن أن الله منزل في شأني وحيا يتلى، لشأني في نفسي كان أحقر من أن يتكلم الله في بأمر، ولكن كنت أرجو أن يرى رسول الله صلى الله عليه وسلم في النوم رؤيا يبرئني الله بها، فوالله ما رام رسول الله صلى الله عليه وسلم مجلسه، ولا خرج أحد من أهل البيت، حتى أنزل عليه، فأخذه ما كان يأخذه من البرحاء، حتى إنه ليتحدر منه من العرق مثل الجمان، وهو في يوم شات من ثقل القول الذي أنزل عليه، قالت: فسري عن رسول الله صلى الله عليه وسلم وهو يضحك، فكانت أول كلمة تكلم بها أن قال: «يا عائشة، أما الله فقد برأك». قالت: فقالت لي أمي: قومي إليه، فقلت: والله لا أقوم إليه، فإني لا أحمد إلا الله عز وجل، قالت: وأنزل الله تعالى: {إن الذين جاءوا بالإفك عصبة منكم} العشر الآيات، ثم أنزل الله هذا في براءتي، قال أبو بكر الصديق: وكان ينفق على مسطح بن أثاثة لقرابته منه وفقره: والله لا أنفق على مسطح شيئا أبدا، بعد الذي قال لعائشة ما قال، فأنزل الله: {ولا يأتل أولو الفضل منكم} - إلى قوله - {غفور رحيم} [البقرة: 173]، قال أبو بكر الصديق: بلى والله إني لأحب أن يغفر الله لي، فرجع إلى مسطح النفقة التي كان ينفق عليه، وقال: والله لا أنزعها منه أبدا، قالت عائشة: وكان رسول الله صلى الله عليه وسلم سأل زينب بنت جحش عن أمري، فقال لزينب: «ماذا علمت، أو رأيت». فقالت: يا رسول الله أحمي سمعي وبصري، والله ما علمت إلا خيرا، قالت عائشة: وهي التي كانت تساميني من أزواج النبي صلى الله عليه وسلم فعصمها الله بالورع، قالت: وطفقت أختها حمنة تحارب لها، فهلكت، فيمن هلك قال ابن شهاب: «فهذا الذي بلغني من حديث هؤلاء الرهط» ثم قال عروة، قالت عائشة: \" والله إن الرجل الذي قيل له ما قيل ليقول: سبحان الله، فوالذي نفسي بيده ما كشفت من كنف أنثى قط، قالت: ثم قتل بعد ذلك في سبيل الله \"", "4141"], ["باب حديث", "حدثني عبد الله بن محمد، قال: أملى علي هشام بن يوسف من حفظه، أخبرنا معمر، عن الزهري، قال: قال لي الوليد بن عبد الملك: أبلغك أن عليا، كان فيمن قذف عائشة؟ قلت: لا، ولكن قد أخبرني رجلان من قومك، أبو سلمة بن عبد الرحمن، وأبو بكر بن عبد الرحمن بن الحارث، أن عائشة رضي الله عنها قالت لهما: \" كان علي مسلما في شأنها فراجعوه، فلم يرجع وقال: مسلما، بلا شك فيه وعليه، كان في أصل العتيق كذلك \"", "4142"], ["باب حديث", "حدثنا موسى بن إسماعيل، حدثنا أبو عوانة، عن حصين، عن أبي وائل، قال: حدثني مسروق بن الأجدع، قال: حدثتني أم رومان، وهي أم عائشة رضي الله عنهما قالت بينا أنا قاعدة أنا وعائشة، إذ ولجت امرأة من الأنصار فقالت: فعل الله بفلان وفعل، فقالت أم رومان: وما ذاك؟ قالت: ابني فيمن حدث الحديث، قالت: وما ذاك؟ قالت: كذا وكذا، قالت عائشة: سمع رسول الله صلى الله عليه وسلم؟ قالت: نعم، قالت: وأبو بكر؟ قالت: نعم: فخرت مغشيا عليها، فما أفاقت إلا وعليها حمى بنافض، فطرحت عليها ثيابها فغطيتها، فجاء النبي صلى الله عليه وسلم فقال: «ما شأن هذه؟». قلت: يا رسول الله أخذتها الحمى بنافض، قال: «فلعل في حديث تحدث به»، قالت: نعم، فقعدت عائشة فقالت: والله لئن حلفت لا تصدقوني، ولئن قلت لا تعذروني، مثلي ومثلكم كيعقوب وبنيه: {والله المستعان على ما تصفون} [يوسف: 18] قالت: وانصرف ولم يقل شيئا، فأنزل الله عذرها، قالت: بحمد الله لا بحمد أحد ولا بحمدك", "4143"], ["باب حديث", "حدثني يحيى، حدثنا وكيع، عن نافع بن عمر، عن ابن أبي مليكة، عن عائشة رضي الله عنها: \" كانت تقرأ: إذ تلقونه بألسنتكم، وتقول: الولق الكذب \" قال ابن أبي مليكة: «وكانت أعلم من غيرها بذلك لأنه نزل فيها»", "4144"], ["باب حديث", "حدثنا عثمان بن أبي شيبة، حدثنا عبدة، عن هشام، عن أبيه، قال: ذهبت أسب حسان عند عائشة، فقالت: لا تسبه، فإنه كان ينافح عن رسول الله صلى الله عليه وسلم، وقالت عائشة: استأذن النبي صلى الله عليه وسلم في هجاء المشركين، قال «كيف بنسبي؟» قال: لأسلنك منهم كما تسل الشعرة من العجين حدثنا محمد بن عقبة، حدثنا عثمان بن فرقد، سمعت هشاما، عن أبيه، قال: سببت حسان وكان ممن كثر عليها", "4145"], ["باب حديث", "حدثني بشر بن خالد، أخبرنا محمد بن جعفر، عن شعبة، عن سليمان، عن أبي الضحى، عن مسروق، قال: دخلنا على عائشة رضي الله عنها، وعندها حسان بن ثابت ينشدها شعرا، يشبب بأبيات له: وقال: حصان رزان ما تزن بريبة وتصبح غرثى من لحوم الغوافل، فقالت له عائشة: لكنك لست كذلك، قال مسروق: فقلت لها لم تأذنين له أن يدخل عليك؟ وقد قال الله تعالى: {والذي تولى كبره منهم له عذاب عظيم} [النور: 11] فقالت: \" وأي عذاب أشد من العمى؟ قالت له: إنه كان ينافح، أو يهاجي عن رسول الله صلى الله عليه وسلم \"", "4146"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا يعقوب بن إبراهيم، حدثنا يحيى بن سعيد، عن عبيد الله، قال: أخبرني نافع، عن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم: «عرضه يوم أحد وهو ابن أربع عشرة سنة، فلم يجزه، وعرضه يوم الخندق، وهو ابن خمس عشرة سنة، فأجازه»", "4097"], ["باب غزوة الخندق وهي الأحزاب", "حدثني قتيبة، حدثنا عبد العزيز، عن أبي حازم، عن سهل بن سعد رضي الله عنه، قال: كنا مع رسول الله صلى الله عليه وسلم في الخندق، وهم يحفرون ونحن ننقل التراب على أكتادنا، فقال رسول الله صلى الله عليه وسلم: «اللهم لا عيش إلا عيش الآخره، فاغفر للمهاجرين والأنصار»", "4098"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا عبد الله بن محمد، حدثنا معاوية بن عمرو، حدثنا أبو إسحاق، عن حميد، سمعت أنسا رضي الله عنه، يقول: خرج رسول الله صلى الله عليه وسلم إلى الخندق، فإذا المهاجرون، والأنصار يحفرون في غداة باردة، فلم يكن لهم عبيد يعملون ذلك لهم، فلما رأى ما بهم من النصب والجوع، قال: «اللهم إن العيش عيش الآخره، فاغفر للأنصار والمهاجره» فقالوا مجيبين له: نحن الذين بايعوا محمدا ... على الجهاد ما بقينا أبدا", "4099"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا أبو معمر، حدثنا عبد الوارث، عن عبد العزيز، عن أنس رضي الله عنه، قال: جعل المهاجرون والأنصار يحفرون الخندق حول المدينة، وينقلون التراب على متونهم، وهم يقولون نحن الذين بايعوا محمدا ... على الإسلام ما بقينا أبدا قال: يقول النبي صلى الله عليه وسلم، وهو يجيبهم: «اللهم إنه لا خير إلا خير الآخره ... فبارك في الأنصار والمهاجره» قال: يؤتون بملء كفي من الشعير، فيصنع لهم بإهالة سنخة، توضع بين يدي القوم، والقوم جياع، وهي بشعة في الحلق، ولها ريح منتن", "4100"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا خلاد بن يحيى، حدثنا عبد الواحد بن أيمن، عن أبيه، قال: أتيت جابرا رضي الله عنه، فقال: إنا يوم الخندق نحفر، فعرضت كدية شديدة، فجاءوا النبي صلى الله عليه وسلم فقالوا: هذه كدية عرضت في الخندق، فقال: «أنا نازل». ثم قام وبطنه معصوب بحجر، ولبثنا ثلاثة أيام لا نذوق ذواقا، فأخذ النبي صلى الله عليه وسلم المعول فضرب، فعاد كثيبا أهيل، أو أهيم، فقلت: يا رسول الله، ائذن لي إلى البيت، فقلت لامرأتي: رأيت بالنبي صلى الله عليه وسلم شيئا ما كان في ذلك صبر، فعندك شيء؟ قالت: عندي شعير وعناق، فذبحت العناق، وطحنت الشعير حتى جعلنا اللحم في البرمة، ثم جئت النبي صلى الله عليه وسلم والعجين قد انكسر، والبرمة بين الأثافي قد كادت أن تنضج، فقلت: طعيم لي، فقم أنت يا رسول الله ورجل أو رجلان، قال: «كم هو» فذكرت له، قال: \" كثير طيب، قال: قل لها: لا تنزع البرمة، ولا الخبز من التنور حتى آتي، فقال: قوموا \" فقام المهاجرون، والأنصار، فلما دخل على امرأته قال: ويحك جاء النبي صلى الله عليه وسلم بالمهاجرين والأنصار ومن معهم، قالت: هل سألك؟ قلت: نعم، فقال: «ادخلوا ولا تضاغطوا» فجعل يكسر الخبز، ويجعل عليه اللحم، ويخمر البرمة والتنور إذا أخذ منه، ويقرب إلى أصحابه ثم ينزع، فلم يزل يكسر الخبز، ويغرف حتى شبعوا وبقي بقية، قال: «كلي هذا وأهدي، فإن الناس أصابتهم مجاعة»", "4101"], ["باب غزوة الخندق وهي الأحزاب", "حدثني عمرو بن علي، حدثنا أبو عاصم، أخبرنا حنظلة بن أبي سفيان، أخبرنا سعيد بن ميناء، قال: سمعت جابر بن عبد الله، رضي الله عنهما قال: لما حفر الخندق رأيت بالنبي صلى الله عليه وسلم خمصا شديدا، فانكفأت إلى امرأتي، فقلت: هل عندك شيء؟ فإني رأيت برسول الله صلى الله عليه وسلم خمصا شديدا، فأخرجت إلي جرابا فيه صاع من شعير، ولنا بهيمة داجن فذبحتها، وطحنت الشعير، ففرغت إلى فراغي، وقطعتها في برمتها، ثم وليت إلى رسول الله صلى الله عليه وسلم، فقالت: لا تفضحني برسول الله صلى الله عليه وسلم وبمن معه، فجئته فساررته، فقلت: يا رسول الله ذبحنا بهيمة لنا وطحنا صاعا من شعير كان عندنا، فتعال أنت ونفر معك، فصاح النبي صلى الله عليه وسلم فقال: «يا أهل الخندق، إن جابرا قد صنع سورا، فحي هلا بهلكم» فقال رسول الله صلى الله عليه وسلم: «لا تنزلن برمتكم، ولا تخبزن عجينكم حتى أجيء». فجئت وجاء رسول الله صلى الله عليه وسلم يقدم الناس حتى جئت امرأتي، فقالت: بك وبك، فقلت: قد فعلت الذي قلت، فأخرجت له عجينا فبصق فيه وبارك، ثم عمد إلى برمتنا فبصق وبارك، ثم قال: «ادع خابزة فلتخبز معي، واقدحي من برمتكم ولا تنزلوها» وهم ألف، فأقسم بالله لقد أكلوا حتى تركوه وانحرفوا، وإن برمتنا لتغط كما هي، وإن عجيننا ليخبز كما هو", "4102"], ["باب غزوة الخندق وهي الأحزاب", "حدثني عثمان بن أبي شيبة، حدثنا عبدة، عن هشام، عن أبيه، عن عائشة رضي الله عنها: {إذ جاءوكم من فوقكم ومن أسفل منكم. وإذ زاغت الأبصار. وبلغت القلوب الحناجر} قالت: كان ذاك يوم الخندق", "4103"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا مسلم بن إبراهيم، حدثنا شعبة، عن أبي إسحاق، عن البراء رضي الله عنه، قال: كان النبي صلى الله عليه وسلم ينقل التراب يوم الخندق، حتى أغمر بطنه، أو اغبر بطنه، يقول: «والله لولا الله ما اهتدينا، ولا تصدقنا ولا صلينا، فأنزلن سكينة علينا، وثبت الأقدام إن لاقينا، إن الألى قد بغوا علينا، إذا أرادوا فتنة أبينا» ورفع بها صوته: «أبينا أبينا»", "4104"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا مسدد، حدثنا يحيى بن سعيد، عن شعبة، قال: حدثني الحكم، عن مجاهد، عن ابن عباس رضي الله عنهما، عن النبي صلى الله عليه وسلم قال: «نصرت بالصبا، وأهلكت عاد بالدبور»", "4105"], ["باب غزوة الخندق وهي الأحزاب", "حدثني أحمد بن عثمان، حدثنا شريح بن مسلمة، قال: حدثني إبراهيم بن يوسف، قال: حدثني أبي، عن أبي إسحاق، قال: سمعت البراء بن عازب يحدث، قال: لما كان يوم الأحزاب، وخندق رسول الله صلى الله عليه وسلم، رأيته ينقل من تراب الخندق، حتى وارى عني الغبار جلدة بطنه، وكان كثير الشعر، فسمعته يرتجز بكلمات ابن رواحة، وهو ينقل من التراب يقول: [البحر الرجز] اللهم لولا أنت ما اهتدينا ... ولا تصدقنا ولا صلينا، فأنزلن سكينة علينا ... وثبت الأقدام إن لاقينا، إن الألى قد بغوا علينا ... وإن أرادوا فتنة أبينا \" قال: ثم يمد صوته بآخرها", "4106"], ["باب غزوة الخندق وهي الأحزاب", "حدثني عبدة بن عبد الله، حدثنا عبد الصمد، عن عبد الرحمن هو ابن عبد الله بن دينار، عن أبيه، أن ابن عمر رضي الله عنهما، قال: «أول يوم شهدته يوم الخندق»", "4107"], ["باب غزوة الخندق وهي الأحزاب", "حدثني إبراهيم بن موسى، أخبرنا هشام، عن معمر، عن الزهري، عن سالم، عن ابن عمر، قال: وأخبرني ابن طاوس، عن عكرمة بن خالد، عن ابن عمر، قال: \" دخلت على حفصة ونسواتها تنطف، قلت: قد كان من أمر الناس ما ترين، فلم يجعل لي من الأمر شيء، فقالت: الحق فإنهم ينتظرونك، وأخشى أن يكون في احتباسك عنهم فرقة، فلم تدعه حتى ذهب، فلما تفرق الناس خطب معاوية قال: من كان يريد أن يتكلم في هذا الأمر فليطلع لنا قرنه، فلنحن أحق به منه ومن أبيه، قال حبيب بن مسلمة: فهلا أجبته؟ قال عبد الله: فحللت حبوتي، وهممت أن أقول: أحق بهذا الأمر منك من قاتلك وأباك على الإسلام، فخشيت أن أقول كلمة تفرق بين الجمع، وتسفك الدم، ويحمل عني غير ذلك، فذكرت ما أعد الله في الجنان، قال حبيب: حفظت وعصمت \" قال محمود، عن عبد الرزاق ونوساتها", "4108"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا أبو نعيم، حدثنا سفيان، عن أبي إسحاق، عن سليمان بن صرد، قال: قال النبي صلى الله عليه وسلم يوم الأحزاب: «نغزوهم، ولا يغزوننا»", "4109"], ["باب غزوة الخندق وهي الأحزاب", "حدثني عبد الله بن محمد، حدثنا يحيى بن آدم، حدثنا إسرائيل، سمعت أبا إسحاق، يقول: سمعت سليمان بن صرد، يقول: سمعت النبي صلى الله عليه وسلم، يقول: حين أجلى الأحزاب عنه: «الآن نغزوهم ولا يغزوننا، نحن نسير إليهم»", "4110"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا إسحاق، حدثنا روح، حدثنا هشام، عن محمد، عن عبيدة، عن علي رضي الله عنه، عن النبي صلى الله عليه وسلم، أنه قال يوم الخندق: «ملأ الله عليهم بيوتهم وقبورهم نارا، كما شغلونا عن صلاة الوسطى حتى غابت الشمس»", "4111"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا المكي بن إبراهيم، حدثنا هشام، عن يحيى، عن أبي سلمة، عن جابر بن عبد الله، أن عمر بن الخطاب رضي الله عنه، جاء يوم الخندق بعد ما غربت الشمس، جعل يسب كفار قريش، وقال: يا رسول الله، ما كدت أن أصلي، حتى كادت الشمس أن تغرب، قال النبي صلى الله عليه وسلم: «والله ما صليتها» فنزلنا مع النبي صلى الله عليه وسلم بطحان، فتوضأ للصلاة وتوضأنا لها، فصلى العصر بعدما غربت الشمس، ثم صلى بعدها المغرب", "4112"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا محمد بن كثير، أخبرنا سفيان، عن ابن المنكدر، قال: سمعت جابرا، يقول: قال رسول الله صلى الله عليه وسلم يوم الأحزاب: «من يأتينا بخبر القوم» فقال الزبير: أنا، ثم قال: «من يأتينا بخبر القوم». فقال الزبير: أنا، ثم قال: «من يأتينا بخبر القوم» فقال الزبير: أنا، ثم قال: «إن لكل نبي حواري، وإن حواري الزبير»", "4113"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا قتيبة بن سعيد، حدثنا الليث، عن سعيد بن أبي سعيد، عن أبيه، عن أبي هريرة رضي الله عنه: أن رسول الله صلى الله عليه وسلم كان يقول: «لا إله إلا الله وحده، أعز جنده، ونصر عبده، وغلب الأحزاب وحده، فلا شيء بعده»", "4114"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا محمد، أخبرنا الفزاري، وعبدة، عن إسماعيل بن أبي خالد، قال: سمعت عبد الله بن أبي أوفى رضي الله عنهما، يقول: دعا رسول الله صلى الله عليه وسلم على الأحزاب فقال: «اللهم منزل الكتاب، سريع الحساب، اهزم الأحزاب، اللهم اهزمهم وزلزلهم»", "4115"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا محمد بن مقاتل، أخبرنا عبد الله، أخبرنا موسى بن عقبة، عن سالم، ونافع، عن عبد الله رضي الله عنه، أن رسول الله صلى الله عليه وسلم كان إذا قفل من الغزو أو الحج أو العمرة يبدأ فيكبر ثلاث مرار، ثم يقول: «لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير. آيبون تائبون، عابدون ساجدون، لربنا حامدون صدق الله وعده، ونصر عبده، وهزم الأحزاب وحده»", "4116"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثني عبد الله بن أبي شيبة، حدثنا ابن نمير، عن هشام، عن أبيه، عن عائشة رضي الله عنها، قالت: لما رجع النبي صلى الله عليه وسلم من الخندق، ووضع السلاح واغتسل، أتاه جبريل عليه السلام، فقال: \" قد وضعت السلاح؟ والله ما وضعناه، فاخرج إليهم قال: فإلى أين؟ قال: ها هنا، وأشار إلى بني قريظة، فخرج النبي صلى الله عليه وسلم إليهم \"", "4117"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثنا موسى، حدثنا جرير بن حازم، عن حميد بن هلال، عن أنس رضي الله عنه ، قال: «كأني أنظر إلى الغبار ساطعا في زقاق بني غنم، موكب جبريل صلوات الله عليه حين سار رسول الله صلى الله عليه وسلم إلى بني قريظة»", "4118"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثنا عبد الله بن محمد بن أسماء، حدثنا جويرية بن أسماء، عن نافع، عن ابن عمر رضي الله عنهما، قال: قال النبي صلى الله عليه وسلم يوم الأحزاب: «لا يصلين أحد العصر إلا في بني قريظة» فأدرك بعضهم العصر في الطريق، فقال بعضهم: لا نصلي حتى نأتيها، وقال بعضهم: بل نصلي، لم يرد منا ذلك، فذكر ذلك للنبي صلى الله عليه وسلم فلم يعنف واحدا منهم", "4119"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثنا ابن أبي الأسود، حدثنا معتمر، ح وحدثني خليفة، حدثنا معتمر، قال: سمعت أبي، عن أنس رضي الله عنه، قال: كان الرجل يجعل للنبي صلى الله عليه وسلم النخلات، حتى افتتح قريظة والنضير، وإن أهلي أمروني أن آتي النبي صلى الله عليه وسلم، فأسأله الذي كانوا أعطوه أو بعضه، وكان النبي صلى الله عليه وسلم قد أعطاه أم أيمن، فجاءت أم أيمن فجعلت الثوب في عنقي، تقول: كلا والذي لا إله إلا هو لا يعطيكهم وقد أعطانيها، أو كما قالت: والنبي صلى الله عليه وسلم يقول: «لك كذا» وتقول: كلا والله، حتى أعطاها - حسبت أنه قال - عشرة أمثاله، أو كما قال", "4120"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن سعد، قال: سمعت أبا أمامة، قال: سمعت أبا سعيد الخدري رضي الله عنه، يقول: نزل أهل قريظة على حكم سعد بن معاذ، فأرسل النبي صلى الله عليه وسلم إلى سعد فأتى على حمار، فلما دنا من المسجد قال للأنصار: «قوموا إلى سيدكم، أو خيركم». فقال: «هؤلاء نزلوا على حكمك». فقال: تقتل مقاتلتهم، وتسبي ذراريهم، قال: «قضيت بحكم الله» وربما قال: «بحكم الملك»", "4121"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثنا زكرياء بن يحيى، حدثنا عبد الله بن نمير، حدثنا هشام، عن أبيه، عن عائشة رضي الله عنها، قالت: أصيب سعد يوم الخندق، رماه رجل من قريش، يقال له حبان بن العرقة وهو حبان بن قيس، من بني معيص بن عامر بن لؤي رماه في الأكحل، فضرب النبي صلى الله عليه وسلم خيمة في المسجد ليعوده من قريب، فلما رجع رسول الله صلى الله عليه وسلم من الخندق وضع السلاح واغتسل، فأتاه جبريل عليه السلام وهو ينفض رأسه من الغبار، فقال: \" قد وضعت السلاح، والله ما وضعته، اخرج إليهم، قال النبي صلى الله عليه وسلم: فأين فأشار إلى بني قريظة \" فأتاهم رسول الله صلى الله عليه وسلم فنزلوا على حكمه، فرد الحكم إلى سعد، قال: فإني أحكم فيهم: أن تقتل المقاتلة، وأن تسبى النساء والذرية، وأن تقسم أموالهم قال هشام، فأخبرني أبي، عن عائشة: \" أن سعدا قال: اللهم إنك تعلم أنه ليس أحد أحب إلي أن أجاهدهم فيك، من قوم كذبوا رسولك صلى الله عليه وسلم وأخرجوه، اللهم فإني أظن أنك قد وضعت الحرب بيننا وبينهم، فإن كان بقي من حرب قريش شيء فأبقني له، حتى أجاهدهم فيك، وإن كنت وضعت الحرب فافجرها واجعل موتتي فيها، فانفجرت من لبته فلم يرعهم، وفي المسجد خيمة من بني غفار، إلا الدم يسيل إليهم، فقالوا: يا أهل الخيمة، ما هذا الذي يأتينا من قبلكم؟ فإذا سعد يغذو جرحه دما، فمات منها رضي الله عنه \"", "4122"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثنا الحجاج بن منهال، أخبرنا شعبة، قال: أخبرني عدي، أنه سمع البراء رضي الله عنه، قال: قال النبي صلى الله عليه وسلم لحسان: «اهجهم - أو هاجهم - وجبريل معك»", "4123"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "وزاد إبراهيم بن طهمان، عن الشيباني، عن عدي بن ثابت، عن البراء بن عازب قال: قال رسول الله صلى الله عليه وسلم يوم قريظة لحسان بن ثابت: «اهج المشركين، فإن جبريل معك»", "4124"], ["باب غزوة ذات الرقاع", "قال أبو عبد الله: وقال لي عبد الله بن رجاء، أخبرنا عمران القطان، عن يحيى بن أبي كثير، عن أبي سلمة، عن جابر بن عبد الله رضي الله عنهما: «أن النبي صلى الله عليه وسلم صلى بأصحابه في الخوف في غزوة السابعة، غزوة ذات الرقاع» قال ابن عباس صلى النبي صلى الله عليه وسلم الخوف بذي قرد", "4125"], ["باب غزوة ذات الرقاع", "وقال بكر بن سوادة: حدثني زياد بن نافع، عن أبي موسى، أن جابرا حدثهم: «صلى النبي صلى الله عليه وسلم بهم يوم محارب، وثعلبة»", "4126"], ["باب غزوة ذات الرقاع", "وقال ابن إسحاق: سمعت وهب بن كيسان، سمعت جابرا، خرج النبي صلى الله عليه وسلم إلى ذات الرقاع من نخل، فلقي جمعا من غطفان، فلم يكن قتال، وأخاف الناس بعضهم بعضا، فصلى النبي صلى الله عليه وسلم ركعتي الخوف \" وقال يزيد: عن سلمة، غزوت مع النبي صلى الله عليه وسلم يوم القرد", "4127"], ["باب غزوة ذات الرقاع", "حدثنا محمد بن العلاء، حدثنا أبو أسامة، عن بريد بن عبد الله بن أبي بردة، عن أبي بردة، عن أبي موسى رضي الله عنه، قال: «خرجنا مع النبي صلى الله عليه وسلم في غزوة ونحن ستة نفر، بيننا بعير نعتقبه، فنقبت أقدامنا، ونقبت قدماي، وسقطت أظفاري، وكنا نلف على أرجلنا الخرق، فسميت غزوة ذات الرقاع، لما كنا نعصب من الخرق على أرجلنا»، وحدث أبو موسى بهذا ثم كره ذاك، قال: ما كنت أصنع بأن أذكره، كأنه كره أن يكون شيء من عمله أفشاه", "4128"], ["باب غزوة ذات الرقاع", "حدثنا قتيبة بن سعيد ، عن مالك، عن يزيد بن رومان، عن صالح بن خوات، عمن شهد \" رسول الله صلى الله عليه وسلم يوم ذات الرقاع صلى صلاة الخوف: أن طائفة صفت معه، وطائفة وجاه العدو، فصلى بالتي معه ركعة، ثم ثبت قائما، وأتموا لأنفسهم ثم انصرفوا، فصفوا وجاه العدو، وجاءت الطائفة الأخرى فصلى بهم الركعة التي بقيت من صلاته ثم ثبت جالسا، وأتموا لأنفسهم، ثم سلم بهم \"", "4129"], ["باب غزوة ذات الرقاع", "وقال معاذ: حدثنا هشام، عن أبي الزبير، عن جابر، قال: كنا مع النبي صلى الله عليه وسلم بنخل، فذكر صلاة الخوف، قال مالك: «وذلك أحسن ما سمعت في صلاة الخوف»", "4130"], ["باب غزوة ذات الرقاع", "حدثنا مسدد، حدثنا يحيى بن سعيد القطان، عن يحيى بن سعيد الأنصاري، عن القاسم بن محمد، عن صالح بن خوات، عن سهل بن أبي حثمة، قال: «يقوم الإمام مستقبل القبلة، وطائفة منهم معه، وطائفة من قبل العدو، وجوههم إلى العدو، فيصلي بالذين معه ركعة، ثم يقومون فيركعون لأنفسهم ركعة، ويسجدون سجدتين في مكانهم، ثم يذهب هؤلاء إلى مقام أولئك، فيركع بهم ركعة، فله ثنتان، ثم يركعون ويسجدون سجدتين» حدثنا مسدد، حدثنا يحيى، عن شعبة، عن عبد الرحمن بن القاسم، عن أبيه، عن صالح بن خوات، عن سهل بن أبي حثمة، عن النبي صلى الله عليه وسلم: مثله، حدثني محمد بن عبيد الله، قال: حدثني ابن أبي حازم، عن يحيى، سمع القاسم، أخبرني صالح بن خوات، عن سهل: حدثه: قوله، تابعه الليث، عن هشام، عن زيد بن أسلم، أن القاسم بن محمد، حدثه: صلى النبي صلى الله عليه وسلم في غزوة بني أنمار", "4131"], ["باب غزوة ذات الرقاع", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني سالم، أن ابن عمر رضي الله عنهما، قال: «غزوت مع رسول الله صلى الله عليه وسلم قبل نجد، فوازينا العدو، فصاففنا لهم»", "4132"], ["باب غزوة ذات الرقاع", "حدثنا مسدد، حدثنا يزيد بن زريع، حدثنا معمر، عن الزهري، عن سالم بن عبد الله بن عمر، عن أبيه، «أن رسول الله صلى الله عليه وسلم صلى بإحدى الطائفتين، والطائفة الأخرى مواجهة العدو، ثم انصرفوا فقاموا في مقام أصحابهم أولئك، فجاء أولئك، فصلى بهم ركعة، ثم سلم عليهم، ثم قام هؤلاء فقضوا ركعتهم، وقام هؤلاء فقضوا ركعتهم»", "4133"], ["باب غزوة ذات الرقاع", "حدثنا أبو اليمان، حدثنا شعيب، عن الزهري، قال: حدثني سنان، وأبو سلمة، أن جابرا أخبر: أنه «غزا مع رسول الله صلى الله عليه وسلم قبل نجد»", "4134"], ["باب غزوة ذات الرقاع", "حدثنا إسماعيل، قال: حدثني أخي، عن سليمان، عن محمد بن أبي عتيق، عن ابن شهاب، عن سنان بن أبي سنان الدؤلي، عن جابر بن عبد الله رضي الله عنهما، أخبره: أنه غزا مع رسول الله صلى الله عليه وسلم قبل نجد، فلما قفل رسول الله صلى الله عليه وسلم قفل معه، فأدركتهم القائلة في واد كثير العضاه، فنزل رسول الله صلى الله عليه وسلم وتفرق الناس في العضاه، يستظلون بالشجر، ونزل رسول الله صلى الله عليه وسلم تحت سمرة فعلق بها سيفه. قال جابر: فنمنا نومة، ثم إذا رسول الله صلى الله عليه وسلم يدعونا فجئناه، فإذا عنده أعرابي جالس، فقال رسول الله صلى الله عليه وسلم: \" إن هذا اخترط سيفي وأنا نائم، فاستيقظت وهو في يده صلتا، فقال لي: من يمنعك مني؟ قلت: الله، فها هو ذا جالس \" ثم لم يعاقبه رسول الله صلى الله عليه وسلم", "4135"], ["باب غزوة ذات الرقاع", "وقال أبان، حدثنا يحيى بن أبي كثير، عن أبي سلمة، عن جابر، قال: كنا مع النبي صلى الله عليه وسلم بذات الرقاع، فإذا أتينا على شجرة ظليلة تركناها للنبي صلى الله عليه وسلم، فجاء رجل من المشركين وسيف النبي صلى الله عليه وسلم معلق بالشجرة، فاخترطه، فقال: تخافني؟ قال: «لا»، قال: فمن يمنعك مني؟ قال: «الله» فتهدده أصحاب النبي صلى الله عليه وسلم، وأقيمت الصلاة، فصلى بطائفة ركعتين، ثم تأخروا، وصلى بالطائفة الأخرى ركعتين، وكان للنبي صلى الله عليه وسلم أربع، وللقوم ركعتان وقال مسدد، عن أبي عوانة، عن أبي بشر، اسم الرجل غورث بن الحارث، وقاتل فيها محارب خصفة، وقال أبو الزبير، عن جابر، كنا مع النبي صلى الله عليه وسلم بنخل، فصلى الخوف، وقال أبو هريرة: «صليت مع النبي صلى الله عليه وسلم غزوة نجد صلاة الخوف» وإنما جاء أبو هريرة إلى النبي صلى الله عليه وسلم أيام خيبر \"", "4136"], ["باب غزوة الحديبية", "حدثنا خالد بن مخلد، حدثنا سليمان بن بلال، قال: حدثني صالح بن كيسان، عن عبيد الله بن عبد الله، عن زيد بن خالد رضي الله عنه، قال: خرجنا مع رسول الله صلى الله عليه وسلم عام الحديبية، فأصابنا مطر ذات ليلة، فصلى لنا رسول الله صلى الله عليه وسلم الصبح، ثم أقبل علينا فقال: «أتدرون ماذا قال ربكم؟». قلنا: الله ورسوله أعلم، فقال: \" قال الله: أصبح من عبادي مؤمن بي وكافر بي، فأما من قال: مطرنا برحمة الله وبرزق الله وبفضل الله، فهو مؤمن بي، كافر بالكوكب، وأما من قال: مطرنا بنجم كذا، فهو مؤمن بالكوكب كافر بي \"", "4147"], ["باب غزوة الحديبية", "حدثنا هدبة بن خالد، حدثنا همام، عن قتادة، أن أنسا رضي الله عنه، أخبره قال: \" اعتمر رسول الله صلى الله عليه وسلم أربع عمر، كلهن في ذي القعدة، إلا التي كانت مع حجته: عمرة من الحديبية في ذي القعدة، وعمرة من العام المقبل في ذي القعدة، وعمرة من الجعرانة، حيث قسم غنائم حنين في ذي القعدة، وعمرة مع حجته \"", "4148"], ["باب غزوة الحديبية", "حدثنا سعيد بن الربيع، حدثنا علي بن المبارك، عن يحيى، عن عبد الله بن أبي قتادة، أن أباه، حدثه قال: انطلقنا مع النبي صلى الله عليه وسلم عام الحديبية، فأحرم أصحابه ولم أحرم \"", "4149"], ["باب غزوة الحديبية", "حدثنا عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء رضي الله عنه، قال: تعدون أنتم الفتح فتح مكة، وقد كان فتح مكة فتحا، ونحن نعد الفتح بيعة الرضوان يوم الحديبية، كنا مع النبي صلى الله عليه وسلم أربع عشرة مائة، والحديبية بئر، فنزحناها فلم نترك فيها قطرة، فبلغ ذلك النبي صلى الله عليه وسلم فأتاها، فجلس على شفيرها ثم «دعا بإناء من ماء فتوضأ، ثم مضمض ودعا ثم صبه فيها، فتركناها غير بعيد، ثم إنها أصدرتنا ما شئنا نحن وركابنا»", "4150"], ["باب غزوة الحديبية", "حدثني فضل بن يعقوب، حدثنا الحسن بن محمد بن أعين أبو علي الحراني، حدثنا زهير، حدثنا أبو إسحاق، قال: أنبأنا البراء بن عازب رضي الله عنهما، أنهم كانوا مع رسول الله صلى الله عليه وسلم يوم الحديبية ألفا وأربع مائة أو أكثر، فنزلوا على بئر فنزحوها، فأتوا رسول الله صلى الله عليه وسلم، فأتى البئر وقعد على شفيرها، ثم قال: «ائتوني بدلو من مائها»، فأتي به، فبصق فدعا، ثم قال: «دعوها ساعة». فأرووا أنفسهم وركابهم حتى ارتحلوا", "4151"], ["باب غزوة الحديبية", "حدثنا يوسف بن عيسى، حدثنا ابن فضيل، حدثنا حصين، عن سالم، عن جابر رضي الله عنه، قال: عطش الناس يوم الحديبية، ورسول الله صلى الله عليه وسلم بين يديه ركوة فتوضأ منها، ثم أقبل الناس نحوه، فقال رسول الله صلى الله عليه وسلم: «ما لكم؟» قالوا يا رسول الله: ليس عندنا ماء نتوضأ به ولا نشرب، إلا ما في ركوتك، قال: «فوضع النبي صلى الله عليه وسلم يده في الركوة، فجعل الماء يفور من بين أصابعه كأمثال العيون». قال: فشربنا وتوضأنا فقلت لجابر: كم كنتم يومئذ؟ قال: لو كنا مائة ألف لكفانا، كنا خمس عشرة مائة", "4152"], ["باب غزوة الحديبية", "حدثنا الصلت بن محمد، حدثنا يزيد بن زريع، عن سعيد، عن قتادة، قلت لسعيد بن المسيب: بلغني أن جابر بن عبد الله كان يقول: «كانوا أربع عشرة مائة»، فقال لي سعيد: حدثني جابر: «كانوا خمس عشرة مائة، الذين بايعوا النبي صلى الله عليه وسلم يوم الحديبية» تابعه أبو داود، حدثنا قرة، عن قتادة", "4153"], ["باب غزوة الحديبية", "حدثنا علي، حدثنا سفيان، قال: عمرو، سمعت جابر بن عبد الله رضي الله عنهما، قال: قال لنا رسول الله صلى الله عليه وسلم يوم الحديبية: «أنتم خير أهل الأرض» وكنا ألفا وأربع مائة، ولو كنت أبصر اليوم لأريتكم مكان الشجرة تابعه الأعمش، سمع سالما، سمع جابرا ألفا وأربع مائة،", "4154"], ["باب غزوة الحديبية", "وقال عبيد الله بن معاذ: حدثنا أبي، حدثنا شعبة، عن عمرو بن مرة، حدثني عبد الله بن أبي أوفى رضي الله عنهما، كان أصحاب الشجرة ألفا وثلاث مائة، وكانت أسلم، ثمن المهاجرين \" تابعه محمد بن بشار، حدثنا أبو داود، حدثنا شعبة", "4155"], ["باب غزوة الحديبية", "حدثنا إبراهيم بن موسى، أخبرنا عيسى، عن إسماعيل، عن قيس، أنه سمع مرداسا الأسلمي، يقول: وكان من أصحاب الشجرة: «يقبض الصالحون، الأول فالأول، وتبقى حفالة كحفالة التمر والشعير، لا يعبأ الله بهم شيئا»", "4156"], ["باب غزوة الحديبية", "حدثنا علي بن عبد الله، حدثنا سفيان، عن الزهري، عن عروة، عن مروان، والمسور بن مخرمة، قالا: «خرج النبي صلى الله عليه وسلم عام الحديبية في بضع عشرة مائة من أصحابه، فلما كان بذي الحليفة قلد الهدي، وأشعر وأحرم منها» لا أحصي كم سمعته من سفيان، حتى سمعته يقول: لا أحفظ من الزهري الإشعار والتقليد، فلا أدري، يعني موضع الإشعار والتقليد، أو الحديث كله", "4157"], ["باب غزوة الحديبية", "حدثنا الحسن بن خلف، قال: حدثنا إسحاق بن يوسف، عن أبي بشر ورقاء، عن ابن أبي نجيح، عن مجاهد، قال: حدثني عبد الرحمن بن أبي ليلى، عن كعب بن عجرة، أن رسول الله صلى الله عليه وسلم رآه وقمله يسقط على وجهه، فقال: «أيؤذيك هوامك؟» قال: نعم، فأمره رسول الله صلى الله عليه وسلم أن يحلق، وهو بالحديبية، لم يبين لهم أنهم يحلون بها، وهم على طمع أن يدخلوا مكة، فأنزل الله الفدية، فأمره رسول الله صلى الله عليه وسلم: «أن يطعم فرقا بين ستة مساكين، أو يهدي شاة، أو يصوم ثلاثة أيام»", "4159"], ["باب غزوة الحديبية", "حدثنا إسماعيل بن عبد الله، قال: حدثني مالك، عن زيد بن أسلم، عن أبيه، قال: خرجت مع عمر بن الخطاب رضي الله عنه إلى السوق، فلحقت عمر امرأة شابة، فقالت: يا أمير المؤمنين، هلك زوجي وترك صبية صغارا، والله ما ينضجون كراعا، ولا لهم زرع ولا ضرع، وخشيت أن تأكلهم الضبع، وأنا بنت خفاف بن إيماء الغفاري، «وقد شهد أبي الحديبية مع النبي صلى الله عليه وسلم». فوقف معها عمر ولم يمض، ثم قال: مرحبا بنسب قريب، ثم انصرف إلى بعير ظهير كان مربوطا في الدار، فحمل عليه غرارتين ملأهما طعاما، وحمل بينهما نفقة وثيابا، ثم ناولها بخطامه، ثم قال: اقتاديه، فلن يفنى حتى يأتيكم الله بخير، فقال رجل: يا أمير المؤمنين، أكثرت لها؟ قال عمر: ثكلتك أمك، والله إني لأرى أبا هذه وأخاها، قد حاصرا حصنا زمانا فافتتحاه، ثم أصبحنا نستفيء سهمانهما فيه", "4160"], ["باب غزوة الحديبية", "حدثني محمد بن رافع، حدثنا شبابة بن سوار أبو عمرو الفزاري، حدثنا شعبة، عن قتادة، عن سعيد بن المسيب، عن أبيه، قال: «لقد رأيت الشجرة، ثم أتيتها بعد فلم أعرفها»", "4162"], ["باب غزوة الحديبية", "حدثنا محمود، حدثنا عبيد الله، عن إسرائيل، عن طارق بن عبد الرحمن، قال: انطلقت حاجا، فمررت بقوم يصلون، قلت: ما هذا المسجد؟ قالوا: هذه الشجرة، حيث بايع رسول الله صلى الله عليه وسلم بيعة الرضوان، فأتيت سعيد بن المسيب فأخبرته، فقال سعيد، حدثني أبي \" أنه كان فيمن بايع رسول الله صلى الله عليه وسلم تحت الشجرة، قال: فلما خرجنا من العام المقبل نسيناها، فلم نقدر عليها \"، فقال سعيد: «إن أصحاب محمد صلى الله عليه وسلم لم يعلموها وعلمتموها أنتم فأنتم أعلم»", "4163"], ["باب غزوة الحديبية", "حدثنا موسى، حدثنا أبو عوانة، حدثنا طارق، عن سعيد بن المسيب، عن أبيه، «أنه كان ممن بايع تحت الشجرة، فرجعنا إليها العام المقبل فعميت علينا»", "4164"], ["باب غزوة الحديبية", "حدثنا قبيصة، حدثنا سفيان، عن طارق، قال: ذكرت عند سعيد بن المسيب الشجرة فضحك، فقال: أخبرني أبي: «وكان شهدها»", "4165"], ["باب غزوة الحديبية", "حدثنا آدم بن أبي إياس، حدثنا شعبة، عن عمرو بن مرة، قال: سمعت عبد الله بن أبي أوفى، وكان من أصحاب الشجرة، قال: كان النبي صلى الله عليه وسلم إذا أتاه قوم بصدقة قال: «اللهم صل عليهم». فأتاه أبي بصدقته، فقال: «اللهم صل على آل أبي أوفى»", "4166"], ["باب غزوة الحديبية", "حدثنا إسماعيل، عن أخيه، عن سليمان، عن عمرو بن يحيى، عن عباد بن تميم، قال: لما كان يوم الحرة، والناس يبايعون لعبد الله بن حنظلة، فقال ابن زيد: على ما يبايع ابن حنظلة الناس؟ قيل له: على الموت، قال: «لا أبايع على ذلك أحدا بعد رسول الله صلى الله عليه وسلم، وكان شهد معه الحديبية»", "4167"], ["باب غزوة الحديبية", "حدثنا يحيى بن يعلى المحاربي، قال: حدثني أبي، حدثنا إياس بن سلمة بن الأكوع، قال: حدثني أبي، وكان من أصحاب الشجرة، قال: «كنا نصلي مع النبي صلى الله عليه وسلم الجمعة ثم ننصرف، وليس للحيطان ظل نستظل فيه»", "4168"], ["باب غزوة الحديبية", "حدثنا قتيبة بن سعيد، حدثنا حاتم، عن يزيد بن أبي عبيد، قال: قلت لسلمة بن الأكوع: \" على أي شيء بايعتم رسول الله صلى الله عليه وسلم يوم الحديبية؟ قال: على الموت \"", "4169"], ["باب غزوة الحديبية", "حدثني أحمد بن إشكاب، حدثنا محمد بن فضيل، عن العلاء بن المسيب، عن أبيه، قال: لقيت البراء بن عازب رضي الله عنهما، فقلت: \" طوبى لك، صحبت النبي صلى الله عليه وسلم وبايعته تحت الشجرة، فقال: يا ابن أخي، إنك لا تدري ما أحدثنا بعده \"", "4170"], ["باب غزوة الحديبية", "حدثنا إسحاق، حدثنا يحيى بن صالح، قال: حدثنا معاوية هو ابن سلام، عن يحيى، عن أبي قلابة، أن ثابت بن الضحاك، أخبره أنه «بايع النبي صلى الله عليه وسلم تحت الشجرة»", "4171"], ["باب غزوة الحديبية", "حدثني أحمد بن إسحاق، حدثنا عثمان بن عمر، أخبرنا شعبة، عن قتادة، عن أنس بن مالك رضي الله عنه، {إنا فتحنا لك فتحا مبينا} [الفتح: 1]. قال: الحديبية قال أصحابه: هنيئا مريئا، فما لنا؟ فأنزل الله: {ليدخل المؤمنين والمؤمنات جنات تجري من تحتها الأنهار} [الفتح: 5] قال شعبة: فقدمت الكوفة، فحدثت بهذا كله عن قتادة، ثم رجعت فذكرت له فقال أما: {إنا فتحنا لك} [الفتح: 1]. فعن أنس وأما هنيئا مريئا، فعن عكرمة", "4172"], ["باب غزوة الحديبية", "حدثنا عبد الله بن محمد، حدثنا أبو عامر، حدثنا إسرائيل، عن مجزأة بن زاهر الأسلمي، عن أبيه، وكان ممن شهد الشجرة، قال: إني لأوقد تحت القدر بلحوم الحمر، إذ نادى منادي رسول الله صلى الله عليه وسلم، إن رسول الله صلى الله عليه وسلم: «ينهاكم عن لحوم الحمر»", "4173"], ["باب غزوة الحديبية", "وعن مجزأة، عن رجل منهم من أصحاب الشجرة اسمه أهبان بن أوس: «وكان اشتكى ركبته، وكان إذا سجد جعل تحت ركبته وسادة»", "4174"], ["باب غزوة الحديبية", "حدثني محمد بن بشار، حدثنا ابن أبي عدي، عن شعبة، عن يحيى بن سعيد، عن بشير بن يسار، عن سويد بن النعمان، وكان من أصحاب الشجرة: «كان رسول الله صلى الله عليه وسلم وأصحابه أتوا بسويق فلاكوه» تابعه معاذ، عن شعبة", "4175"], ["باب غزوة الحديبية", "حدثنا محمد بن حاتم بن بزيع، حدثنا شاذان، عن شعبة، عن أبي جمرة، قال: سألت عائذ بن عمرو رضي الله عنه، وكان من أصحاب النبي صلى الله عليه وسلم من أصحاب الشجرة، هل ينقض الوتر؟ قال: «إذا أوترت من أوله، فلا توتر من آخره»", "4176"], ["باب غزوة الحديبية", "حدثني عبد الله بن يوسف، أخبرنا مالك، عن زيد بن أسلم، عن أبيه، أن رسول الله صلى الله عليه وسلم كان يسير في بعض أسفاره، وعمر بن الخطاب يسير معه ليلا، فسأله عمر بن الخطاب عن شيء فلم يجبه رسول الله صلى الله عليه وسلم، ثم سأله فلم يجبه، ثم سأله فلم يجبه، وقال عمر بن الخطاب: ثكلتك أمك يا عمر، نزرت رسول الله صلى الله عليه وسلم ثلاث مرات كل ذلك لا يجيبك، قال عمر: فحركت بعيري ثم تقدمت أمام المسلمين، وخشيت أن ينزل في قرآن، فما نشبت أن سمعت صارخا يصرخ بي، قال: فقلت: لقد خشيت أن يكون نزل في قرآن، وجئت رسول الله صلى الله عليه وسلم فسلمت عليه، فقال: «لقد أنزلت علي الليلة سورة، لهي أحب إلي مما طلعت عليه الشمس» ثم قرأ: {إنا فتحنا لك فتحا مبينا} [الفتح: 1]", "4177"], ["باب غزوة الحديبية", "حدثنا عبد الله بن محمد، حدثنا سفيان، قال: سمعت الزهري، حين حدث هذا الحديث، حفظت بعضه، وثبتني معمر، عن عروة بن الزبير، عن المسور بن مخرمة، ومروان بن الحكم، يزيد أحدهما على صاحبه قالا: خرج النبي صلى الله عليه وسلم عام الحديبية في بضع عشرة مائة من أصحابه، فلما أتى ذا الحليفة، قلد الهدي وأشعره وأحرم منها بعمرة، وبعث عينا له من خزاعة، وسار النبي صلى الله عليه وسلم حتى كان بغدير الأشطاط أتاه عينه، قال: إن قريشا جمعوا لك جموعا، وقد جمعوا لك الأحابيش، وهم مقاتلوك، وصادوك عن البيت، ومانعوك، فقال: «أشيروا أيها الناس علي، أترون أن أميل إلى عيالهم وذراري هؤلاء الذين يريدون أن يصدونا عن البيت، فإن يأتونا كان الله عز وجل قد قطع عينا من المشركين، وإلا تركناهم محروبين»، قال أبو بكر: يا رسول الله، خرجت عامدا لهذا البيت، لا تريد قتل أحد، ولا حرب أحد، فتوجه له، فمن صدنا عنه قاتلناه. قال: «امضوا على اسم الله»", "4178"], ["باب غزوة الحديبية", "حدثني إسحاق، أخبرنا يعقوب، حدثني ابن أخي ابن شهاب، عن عمه، أخبرني عروة بن الزبير، أنه سمع مروان بن الحكم، والمسور بن مخرمة: يخبران خبرا من خبر رسول الله صلى الله عليه وسلم في عمرة الحديبية، فكان فيما أخبرني عروة عنهما: أنه لما كاتب رسول الله صلى الله عليه وسلم سهيل بن عمرو يوم الحديبية على قضية المدة، وكان فيما اشترط سهيل بن عمرو أنه قال: لا يأتيك منا أحد، وإن كان على دينك إلا رددته إلينا، وخليت بيننا وبينه، وأبى سهيل أن يقاضي رسول الله صلى الله عليه وسلم إلا على ذلك، فكره المؤمنون ذلك وامعضوا، فتكلموا فيه، فلما أبى سهيل أن يقاضي رسول الله صلى الله عليه وسلم إلا على ذلك، كاتبه رسول الله صلى الله عليه وسلم، «فرد رسول الله صلى الله عليه وسلم أبا جندل بن سهيل يومئذ إلى أبيه سهيل بن عمرو، ولم يأت رسول الله صلى الله عليه وسلم أحد من الرجال إلا رده في تلك المدة، وإن كان مسلما، وجاءت المؤمنات مهاجرات، فكانت أم كلثوم بنت عقبة بن أبي معيط ممن خرج إلى رسول الله صلى الله عليه وسلم، وهي عاتق، فجاء أهلها يسألون رسول الله صلى الله عليه وسلم أن يرجعها إليهم، حتى أنزل الله تعالى في المؤمنات ما أنزل»", "4180"], ["باب غزوة الحديبية", "قال ابن شهاب: وأخبرني عروة بن الزبير، أن عائشة رضي الله عنها زوج النبي صلى الله عليه وسلم قالت: إن رسول الله صلى الله عليه وسلم كان «يمتحن من هاجر من المؤمنات بهذه الآية»: {يا أيها النبي إذا جاءك المؤمنات يبايعنك} [الممتحنة: 12] وعن عمه قال: \" بلغنا حين أمر الله رسوله صلى الله عليه وسلم أن يرد إلى المشركين ما أنفقوا على من هاجر من أزواجهم، وبلغنا أن أبا بصير: فذكره بطوله \"", "4182"], ["باب غزوة الحديبية", "حدثنا قتيبة، عن مالك، عن نافع، أن عبد الله بن عمر رضي الله عنهما، خرج معتمرا في الفتنة، فقال: إن صددت عن البيت صنعنا كما صنعنا مع رسول الله صلى الله عليه وسلم، فأهل بعمرة، من أجل «أن رسول الله صلى الله عليه وسلم كان أهل بعمرة عام الحديبية»", "4183"], ["باب غزوة الحديبية", "حدثنا مسدد، حدثنا يحيى، عن عبيد الله، عن نافع، عن ابن عمر أنه أهل وقال: \" إن حيل بيني وبينه لفعلت كما فعل النبي صلى الله عليه وسلم: حين حالت كفار قريش بينه \" وتلا: {لقد كان لكم في رسول الله أسوة حسنة} [الأحزاب: 21]", "4184"], ["باب غزوة الحديبية", "حدثنا عبد الله بن محمد بن أسماء، حدثنا جويرية، عن نافع، أن عبيد الله بن عبد الله، وسالم بن عبد الله، أخبراه: أنهما كلما عبد الله بن عمر ح وحدثنا موسى بن إسماعيل ، حدثنا جويرية، عن نافع، أن بعض بني عبد الله، قال له: لو أقمت العام، فإني أخاف أن لا تصل إلى البيت قال: \" خرجنا مع النبي صلى الله عليه وسلم فحال كفار قريش دون البيت، فنحر النبي صلى الله عليه وسلم هداياه، وحلق وقصر أصحابه، وقال: أشهدكم أني أوجبت عمرة، فإن خلي بيني وبين البيت طفت، وإن حيل بيني وبين البيت، صنعت كما صنع رسول الله صلى الله عليه وسلم فسار ساعة، ثم قال: ما أرى شأنهما إلا واحدا، أشهدكم أني قد أوجبت حجة مع عمرتي، فطاف طوافا واحدا، وسعيا واحدا، حتى حل منهما جميعا \"", "4185"], ["باب غزوة الحديبية", "حدثني شجاع بن الوليد، سمع النضر بن محمد، حدثنا صخر، عن نافع، قال: إن الناس يتحدثون أن ابن عمر، أسلم قبل عمر، وليس كذلك، ولكن عمر يوم الحديبية أرسل عبد الله إلى فرس له عند رجل من الأنصار، يأتي به ليقاتل عليه، ورسول الله صلى الله عليه وسلم يبايع عند الشجرة، وعمر لا يدري بذلك، فبايعه عبد الله ثم ذهب إلى الفرس، فجاء به إلى عمر، وعمر يستلئم للقتال، فأخبره أن رسول الله صلى الله عليه وسلم: «يبايع تحت الشجرة»، قال: فانطلق، فذهب معه حتى بايع رسول الله صلى الله عليه وسلم، فهي التي يتحدث الناس أن ابن عمر أسلم قبل عمر", "4186"], ["باب غزوة الحديبية", "وقال هشام بن عمار، حدثنا الوليد بن مسلم، حدثنا عمر بن محمد العمري، أخبرني نافع، عن ابن عمر رضي الله عنهما، \" أن الناس كانوا مع النبي صلى الله عليه وسلم يوم الحديبية تفرقوا في ظلال الشجر، فإذا الناس محدقون بالنبي صلى الله عليه وسلم، فقال: يا عبد الله، انظر ما شأن الناس قد أحدقوا برسول الله صلى الله عليه وسلم؟ فوجدهم يبايعون، فبايع ثم رجع إلى عمر فخرج فبايع \"", "4187"], ["باب غزوة الحديبية", "حدثنا ابن نمير، حدثنا يعلى، حدثنا إسماعيل، قال: سمعت عبد الله بن أبي أوفى رضي الله عنهما، قال: كنا مع النبي صلى الله عليه وسلم، حين اعتمر «فطاف فطفنا معه، وصلى وصلينا معه، وسعى بين الصفا والمروة، فكنا نستره من أهل مكة لا يصيبه أحد بشيء»", "4188"], ["باب غزوة الحديبية", "حدثنا الحسن بن إسحاق، حدثنا محمد بن سابق، حدثنا مالك بن مغول، قال: سمعت أبا حصين، قال: قال أبو وائل: لما قدم سهل بن حنيف من صفين أتيناه نستخبره، فقال: «اتهموا الرأي، فلقد رأيتني يوم أبي جندل ولو أستطيع أن أرد على رسول الله صلى الله عليه وسلم أمره لرددت، والله ورسوله أعلم، وما وضعنا أسيافنا على عواتقنا لأمر يفظعنا إلا أسهلن بنا إلى أمر نعرفه قبل هذا الأمر، ما نسد منها خصما إلا انفجر علينا خصم ما ندري كيف نأتي له»", "4189"], ["باب غزوة الحديبية", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن أيوب، عن مجاهد، عن ابن أبي ليلى، عن كعب بن عجرة رضي الله عنه، قال: أتى علي النبي صلى الله عليه وسلم زمن الحديبية، والقمل يتناثر على وجهي، فقال: «أيؤذيك هوام رأسك؟» قلت: نعم، قال: «فاحلق، وصم ثلاثة أيام، أو أطعم ستة مساكين، أو انسك نسيكة» قال أيوب: «لا أدري بأي هذا بدأ»", "4190"], ["باب غزوة الحديبية", "حدثني محمد بن هشام أبو عبد الله، حدثنا هشيم، عن أبي بشر، عن مجاهد، عن عبد الرحمن بن أبي ليلى، عن كعب بن عجرة، قال: كنا مع رسول الله صلى الله عليه وسلم بالحديبية ونحن محرمون، وقد حصرنا المشركون، قال: وكانت لي وفرة، فجعلت الهوام تساقط على وجهي، فمر بي النبي صلى الله عليه وسلم فقال: «أيؤذيك هوام رأسك؟» قلت: نعم، قال: وأنزلت هذه الآية: {فمن كان منكم مريضا أو به أذى من رأسه ففدية من صيام أو صدقة أو نسك} [البقرة: 196]", "4191"], ["باب قصة عكل وعرينة", "حدثني عبد الأعلى بن حماد، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، أن أنسا رضي الله عنه، حدثهم: أن ناسا من عكل وعرينة قدموا المدينة على النبي صلى الله عليه وسلم وتكلموا بالإسلام، فقالوا يا نبي الله: إنا كنا أهل ضرع، ولم نكن أهل ريف، واستوخموا المدينة، «فأمر لهم رسول الله صلى الله عليه وسلم بذود وراع، وأمرهم أن يخرجوا فيه فيشربوا من ألبانها وأبوالها»، فانطلقوا حتى إذا كانوا ناحية الحرة، كفروا بعد إسلامهم، وقتلوا راعي النبي صلى الله عليه وسلم، واستاقوا الذود، «فبلغ النبي صلى الله عليه وسلم فبعث الطلب في آثارهم، فأمر بهم فسمروا أعينهم، وقطعوا أيديهم، وتركوا في ناحية الحرة حتى ماتوا على حالهم» قال قتادة: بلغنا أن النبي صلى الله عليه وسلم بعد ذلك كان يحث على الصدقة وينهى عن المثلة وقال شعبة: وأبان، وحماد، عن قتادة، من عرينة، وقال يحيى بن أبي كثير: وأيوب، عن أبي قلابة، عن أنس قدم نفر من عكل", "4192"], ["باب قصة عكل وعرينة", "حدثني محمد بن عبد الرحيم، حدثنا حفص بن عمر أبو عمر الحوضي، حدثنا حماد بن زيد، حدثنا أيوب، والحجاج الصواف، قال: حدثني أبو رجاء، مولى أبي قلابة، وكان معه بالشأم: أن عمر بن عبد العزيز، استشار الناس يوما، قال: ما تقولون في هذه القسامة؟ فقالوا: «حق قضى بها رسول الله صلى الله عليه وسلم ، وقضت بها الخلفاء قبلك» قال: وأبو قلابة خلف سريره، فقال عنبسة بن سعيد فأين حديث أنس في العرنيين قال أبو قلابة، إياي حدثه أنس بن مالك، قال عبد العزيز بن صهيب، عن أنس، من عرينة، وقال أبو قلابة، عن أنس، من عكل ذكر القصة", "4193"], ["باب غزوة ذي قرد", "حدثنا قتيبة بن سعيد، حدثنا حاتم، عن يزيد بن أبي عبيد، قال: سمعت سلمة بن الأكوع، يقول: خرجت قبل أن يؤذن بالأولى، وكانت لقاح رسول الله صلى الله عليه وسلم ترعى بذي قرد، قال: فلقيني غلام لعبد الرحمن بن عوف، فقال: أخذت لقاح رسول الله صلى الله عليه وسلم، قلت: من أخذها؟ قال: غطفان، قال: فصرخت ثلاث صرخات يا صباحاه، قال فأسمعت ما بين لابتي المدينة، ثم اندفعت على وجهي حتى أدركتهم، وقد أخذوا يستقون من الماء، فجعلت أرميهم بنبلي، وكنت راميا، وأقول أنا ابن الأكوع ... واليوم يوم الرضع وأرتجز، حتى استنقذت اللقاح منهم، واستلبت منهم ثلاثين بردة، قال: وجاء النبي صلى الله عليه وسلم والناس، فقلت: يا نبي الله، قد حميت القوم الماء وهم عطاش، فابعث إليهم الساعة، فقال: «يا ابن الأكوع، ملكت فأسجح» قال: ثم رجعنا ويردفني رسول الله صلى الله عليه وسلم على ناقته حتى دخلنا المدينة", "4194"], ["باب غزوة خيبر", "حدثنا عبد الله بن مسلمة، عن مالك، عن يحيى بن سعيد، عن بشير بن يسار، أن سويد بن النعمان، أخبره: أنه خرج مع النبي صلى الله عليه وسلم عام خيبر، حتى إذا كنا بالصهباء، وهي من أدنى خيبر، «صلى العصر، ثم دعا بالأزواد فلم يؤت إلا بالسويق، فأمر به فثري، فأكل وأكلنا، ثم قام إلى المغرب، فمضمض ومضمضنا، ثم صلى ولم يتوضأ»", "4195"], ["باب غزوة خيبر", "حدثنا عبد الله بن مسلمة، حدثنا حاتم بن إسماعيل، عن يزيد بن أبي عبيد، عن سلمة بن الأكوع رضي الله عنه، قال: خرجنا مع النبي صلى الله عليه وسلم إلى خيبر، فسرنا ليلا، فقال رجل من القوم لعامر: يا عامر ألا تسمعنا من هنيهاتك؟ وكان عامر رجلا شاعرا، فنزل يحدو بالقوم يقول: [البحر الرجز] اللهم لولا أنت ما اهتدينا ... ولا تصدقنا ولا صلينا فاغفر فداء لك ما أبقينا ... وثبت الأقدام إن لاقينا وألقين سكينة علينا ... إنا إذا صيح بنا أبينا وبالصياح عولوا علينا، فقال رسول الله صلى الله عليه وسلم: «من هذا السائق»، قالوا: عامر بن الأكوع، قال: «يرحمه الله» قال رجل من القوم: وجبت يا نبي الله، لولا أمتعتنا به؟ فأتينا خيبر فحاصرناهم حتى أصابتنا مخمصة شديدة، ثم إن الله تعالى فتحها عليهم، فلما أمسى الناس مساء اليوم الذي فتحت عليهم، أوقدوا نيرانا كثيرة، فقال النبي صلى الله عليه وسلم: «ما هذه النيران على أي شيء توقدون؟» قالوا: على لحم، قال: «على أي لحم؟» قالوا: لحم حمر الإنسية، قال النبي صلى الله عليه وسلم: «أهريقوها واكسروها»، فقال رجل: يا رسول الله، أو نهريقها ونغسلها؟ قال: «أو ذاك». فلما تصاف القوم كان سيف عامر قصيرا، فتناول به ساق يهودي ليضربه، ويرجع ذباب سيفه، فأصاب عين ركبة عامر فمات منه، قال: فلما قفلوا قال سلمة: رآني رسول الله صلى الله عليه وسلم وهو آخذ بيدي، قال: «ما لك» قلت له: فداك أبي وأمي، زعموا أن عامرا حبط عمله؟ قال النبي صلى الله عليه وسلم: «كذب من قاله، إن له لأجرين - وجمع بين إصبعيه - إنه لجاهد مجاهد، قل عربي مشى بها مثله»، حدثنا قتيبة، حدثنا حاتم قال: «نشأ بها»", "4196"], ["باب غزوة خيبر", "حدثنا عبد الله بن يوسف، أخبرنا مالك، عن حميد الطويل، عن أنس رضي الله عنه، أن رسول الله صلى الله عليه وسلم أتى خيبر ليلا، وكان إذا أتى قوما بليل لم يغر بهم حتى يصبح، فلما أصبح خرجت اليهود بمساحيهم، ومكاتلهم فلما رأوه قالوا: محمد والله، محمد والخميس، فقال النبي صلى الله عليه وسلم: \" خربت خيبر، إنا إذا نزلنا بساحة قوم {فساء صباح المنذرين} [الصافات: 177] \"", "4197"], ["باب غزوة خيبر", "أخبرنا صدقة بن الفضل، أخبرنا ابن عيينة، حدثنا أيوب، عن محمد بن سيرين، عن أنس بن مالك رضي الله عنه، قال: صبحنا خيبر بكرة، فخرج أهلها بالمساحي، فلما بصروا بالنبي صلى الله عليه وسلم قالوا: محمد والله، محمد والخميس، فقال النبي صلى الله عليه وسلم: \" الله أكبر، خربت خيبر، إنا إذا نزلنا بساحة قوم {فساء صباح المنذرين} [الصافات: 177] \" فأصبنا من لحوم الحمر، فنادى منادي النبي صلى الله عليه وسلم: «إن الله ورسوله ينهيانكم عن لحوم الحمر، فإنها رجس»", "4198"], ["باب غزوة خيبر", "حدثنا عبد الله بن عبد الوهاب، حدثنا عبد الوهاب، حدثنا أيوب، عن محمد، عن أنس بن مالك رضي الله عنه، أن رسول الله صلى الله عليه وسلم جاءه جاء، فقال: أكلت الحمر، فسكت، ثم أتاه الثانية ، فقال: أكلت الحمر، فسكت، ثم أتاه الثالثة فقال: أفنيت الحمر، فأمر مناديا فنادى في الناس: «إن الله ورسوله ينهيانكم عن لحوم الحمر الأهلية». فأكفئت القدور وإنها لتفور باللحم", "4199"], ["باب غزوة خيبر", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن ثابت، عن أنس رضي الله عنه، قال: صلى النبي صلى الله عليه وسلم الصبح قريبا من خيبر بغلس، ثم قال: \" الله أكبر خربت خيبر، إنا إذا نزلنا بساحة قوم {فساء صباح المنذرين} [الصافات: 177] \" فخرجوا يسعون في السكك، فقتل النبي صلى الله عليه وسلم المقاتلة، وسبى الذرية، وكان في السبي صفية، فصارت إلى دحية الكلبي، ثم صارت إلى النبي صلى الله عليه وسلم، فجعل عتقها صداقها فقال عبد العزيز بن صهيب لثابت: يا أبا محمد، آنت قلت لأنس: ما أصدقها؟ فحرك ثابت رأسه تصديقا له", "4200"], ["باب غزوة خيبر", "حدثنا آدم، حدثنا شعبة، عن عبد العزيز بن صهيب، قال: سمعت أنس بن مالك رضي الله عنه، يقول: «سبى النبي صلى الله عليه وسلم صفية فأعتقها وتزوجها» فقال ثابت لأنس ما أصدقها؟ قال: «أصدقها نفسها فأعتقها»", "4201"], ["باب غزوة خيبر", "حدثنا قتيبة، حدثنا يعقوب، عن أبي حازم، عن سهل بن سعد الساعدي رضي الله عنه، أن رسول الله صلى الله عليه وسلم التقى هو والمشركون فاقتتلوا، فلما مال رسول الله صلى الله عليه وسلم إلى عسكره ومال الآخرون إلى عسكرهم، وفي أصحاب رسول الله صلى الله عليه وسلم رجل لا يدع لهم شاذة ولا فاذة إلا اتبعها يضربها بسيفه، فقيل: ما أجزأ منا اليوم أحد كما أجزأ فلان، فقال رسول الله صلى الله عليه وسلم: «أما إنه من أهل النار»، فقال رجل من القوم: أنا صاحبه، قال: فخرج معه كلما وقف وقف معه، وإذا أسرع أسرع معه، قال: فجرح الرجل جرحا شديدا، فاستعجل الموت، فوضع سيفه بالأرض وذبابه بين ثدييه، ثم تحامل على سيفه فقتل نفسه، فخرج الرجل إلى رسول الله صلى الله عليه وسلم فقال: أشهد أنك رسول الله، قال: «وما ذاك؟» قال: الرجل الذي ذكرت آنفا أنه من أهل النار، فأعظم الناس ذلك، فقلت: أنا لكم به، فخرجت في طلبه، ثم جرح جرحا شديدا، فاستعجل الموت، فوضع نصل سيفه في الأرض، وذبابه بين ثدييه، ثم تحامل عليه فقتل نفسه، فقال رسول الله صلى الله عليه وسلم عند ذلك: «إن الرجل ليعمل عمل أهل الجنة، فيما يبدو للناس، وهو من أهل النار، وإن الرجل ليعمل عمل أهل النار، فيما يبدو للناس وهو من أهل الجنة»", "4202"], ["باب غزوة خيبر", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني سعيد بن المسيب، أن أبا هريرة رضي الله عنه، قال: شهدنا خيبر، فقال رسول الله صلى الله عليه وسلم لرجل ممن معه يدعي الإسلام: «هذا من أهل النار». فلما حضر القتال قاتل الرجل أشد القتال، حتى كثرت به الجراحة، فكاد بعض الناس يرتاب، فوجد الرجل ألم الجراحة، فأهوى بيده إلى كنانته فاستخرج منها أسهما فنحر بها نفسه، فاشتد رجال من المسلمين، فقالوا: يا رسول الله، صدق الله حديثك، انتحر فلان فقتل نفسه، فقال: «قم يا فلان، فأذن أنه لا يدخل الجنة إلا مؤمن، إن الله يؤيد الدين بالرجل الفاجر» تابعه معمر، عن الزهري، وقال شبيب، عن يونس، عن ابن شهاب، أخبرني ابن المسيب، وعبد الرحمن بن عبد الله بن كعب، أن أبا هريرة، قال: «شهدنا مع النبي صلى الله عليه وسلم حنينا»، وقال ابن المبارك، عن يونس، عن الزهري، عن سعيد، عن النبي صلى الله عليه وسلم. تابعه صالح، عن الزهري، وقال: الزبيدي، أخبرني الزهري، أن عبد الرحمن بن كعب، أخبره أن عبيد الله بن كعب قال: «أخبرني من شهد مع النبي صلى الله عليه وسلم خيبر»، قال لزهري وأخبرني عبيد الله بن عبد الله، وسعيد عن النبي صلى الله عليه وسلم", "4203"], ["باب غزوة خيبر", "حدثنا موسى بن إسماعيل، حدثنا عبد الواحد، عن عاصم، عن أبي عثمان، عن أبي موسى الأشعري رضي الله عنه، قال: لما غزا رسول الله صلى الله عليه وسلم خيبر، أو قال: لما توجه رسول الله صلى الله عليه وسلم، أشرف الناس على واد، فرفعوا أصواتهم بالتكبير: الله أكبر الله أكبر، لا إله إلا الله، فقال رسول الله صلى الله عليه وسلم: «اربعوا على أنفسكم، إنكم لا تدعون أصم ولا غائبا، إنكم تدعون سميعا قريبا وهو معكم»، وأنا خلف دابة رسول الله صلى الله عليه وسلم، فسمعني وأنا أقول: لا حول ولا قوة إلا بالله، فقال لي: «يا عبد الله بن قيس». قلت: لبيك يا رسول الله، قال: «ألا أدلك على كلمة من كنز من كنوز الجنة» قلت: بلى يا رسول الله، فداك أبي وأمي، قال: «لا حول ولا قوة إلا بالله»", "4205"], ["باب غزوة خيبر", "حدثنا المكي بن إبراهيم، حدثنا يزيد بن أبي عبيد، قال: رأيت أثر ضربة في ساق سلمة، فقلت يا أبا مسلم، ما هذه الضربة؟ فقال: هذه ضربة أصابتني يوم خيبر، فقال الناس: أصيب سلمة، فأتيت النبي صلى الله عليه وسلم «فنفث فيه ثلاث نفثات، فما اشتكيتها حتى الساعة»", "4206"], ["باب غزوة خيبر", "حدثنا عبد الله بن مسلمة، حدثنا ابن أبي حازم، عن أبيه ، عن سهل، قال: التقى النبي صلى الله عليه وسلم والمشركون في بعض مغازيه، فاقتتلوا، فمال كل قوم إلى عسكرهم، وفي المسلمين رجل لا يدع من المشركين شاذة ولا فاذة إلا اتبعها فضربها بسيفه، فقيل: يا رسول الله، ما أجزأ أحد ما أجزأ فلان، فقال: «إنه من أهل النار»، فقالوا: أينا من أهل الجنة، إن كان هذا من أهل النار؟ فقال رجل من القوم: لأتبعنه، فإذا أسرع وأبطأ كنت معه، حتى جرح، فاستعجل الموت، فوضع نصاب سيفه بالأرض، وذبابه بين ثدييه، ثم تحامل عليه فقتل نفسه، فجاء الرجل إلى النبي صلى الله عليه وسلم فقال: أشهد أنك رسول الله، فقال: «وما ذاك». فأخبره، فقال: «إن الرجل ليعمل بعمل أهل الجنة، فيما يبدو للناس، وإنه لمن أهل النار، ويعمل بعمل أهل النار، فيما يبدو للناس، وهو من أهل الجنة»", "4207"], ["باب غزوة خيبر", "حدثنا محمد بن سعيد الخزاعي، حدثنا زياد بن الربيع، عن أبي عمران، قال: نظر أنس إلى الناس يوم الجمعة، فرأى طيالسة، فقال: «كأنهم الساعة يهود خيبر»", "4208"], ["باب غزوة خيبر", "حدثنا عبد الله بن مسلمة، حدثنا حاتم، عن يزيد بن أبي عبيد، عن سلمة رضي الله عنه، قال: كان علي بن أبي طالب رضي الله عنه، تخلف عن النبي صلى الله عليه وسلم في خيبر، وكان رمدا، فقال: أنا أتخلف عن النبي صلى الله عليه وسلم، فلحق به، فلما بتنا الليلة التي فتحت قال: «لأعطين الراية غدا أو ليأخذن الراية غدا رجل يحبه الله ورسوله، يفتح عليه» فنحن نرجوها، فقيل: هذا علي فأعطاه، ففتح عليه", "4209"], ["باب غزوة خيبر", "حدثنا قتيبة بن سعيد، حدثنا يعقوب بن عبد الرحمن، عن أبي حازم، قال: أخبرني سهل بن سعد رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال يوم خيبر: «لأعطين هذه الراية غدا رجلا يفتح الله على يديه، يحب الله ورسوله ويحبه الله ورسوله»، قال: فبات الناس يدوكون ليلتهم أيهم يعطاها، فلما أصبح الناس غدوا على رسول الله صلى الله عليه وسلم كلهم يرجو أن يعطاها، فقال: «أين علي بن أبي طالب». فقيل: هو يا رسول الله يشتكي عينيه، قال: «فأرسلوا إليه». فأتي به فبصق رسول الله صلى الله عليه وسلم في عينيه ودعا له، فبرأ حتى كأن لم يكن به وجع، فأعطاه الراية، فقال علي: يا رسول الله، أقاتلهم حتى يكونوا مثلنا؟ فقال: «انفذ على رسلك حتى تنزل بساحتهم، ثم ادعهم إلى الإسلام، وأخبرهم بما يجب عليهم من حق الله فيه، فوالله لأن يهدي الله بك رجلا واحدا، خير لك من أن يكون لك حمر النعم»", "4210"], ["باب غزوة خيبر", "حدثنا عبد الغفار بن داود، حدثنا يعقوب بن عبد الرحمن، ح وحدثني أحمد، حدثنا ابن وهب، قال: أخبرني يعقوب بن عبد الرحمن الزهري، عن عمرو، مولى المطلب، عن أنس بن مالك رضي الله عنه، قال: قدمنا خيبر فلما فتح الله عليه الحصن، ذكر له جمال صفية بنت حيي بن أخطب، وقد قتل زوجها وكانت عروسا، فاصطفاها النبي صلى الله عليه وسلم لنفسه، فخرج بها حتى بلغنا سد الصهباء حلت، فبنى بها رسول الله صلى الله عليه وسلم، ثم صنع حيسا في نطع صغير، ثم قال لي: «آذن من حولك». فكانت تلك وليمته على صفية، ثم خرجنا إلى المدينة، فرأيت النبي صلى الله عليه وسلم يحوي لها وراءه بعباءة، ثم يجلس عند بعيره فيضع ركبته، وتضع صفية رجلها على ركبته حتى تركب", "4211"], ["باب غزوة خيبر", "حدثنا إسماعيل، قال: حدثني أخي، عن سليمان، عن يحيى، عن حميد الطويل، سمع أنس بن مالك رضي الله عنه، أن النبي صلى الله عليه وسلم: «أقام على صفية بنت حيي بطريق خيبر ثلاثة أيام، حتى أعرس بها، وكانت فيمن ضرب عليها الحجاب»", "4212"], ["باب غزوة خيبر", "حدثنا سعيد بن أبي مريم، أخبرنا محمد بن جعفر بن أبي كثير، قال: أخبرني حميد، أنه سمع أنسا رضي الله عنه، يقول: «أقام النبي صلى الله عليه وسلم بين خيبر، والمدينة ثلاث ليال يبنى عليه بصفية»، فدعوت المسلمين إلى وليمته، وما كان فيها من خبز ولا لحم، وما كان فيها إلا أن أمر بلالا بالأنطاع فبسطت، فألقى عليها التمر والأقط والسمن، فقال المسلمون: إحدى أمهات المؤمنين، أو ما ملكت يمينه؟ قالوا: إن حجبها فهي إحدى أمهات المؤمنين، وإن لم يحجبها فهي مما ملكت يمينه، فلما ارتحل وطأ لها خلفه، ومد الحجاب", "4213"], ["باب غزوة خيبر", "حدثنا أبو الوليد، حدثنا شعبة، ح وحدثني عبد الله بن محمد، حدثنا وهب، حدثنا شعبة، عن حميد بن هلال، عن عبد الله بن مغفل رضي الله عنه، قال: «كنا محاصري خيبر، فرمى إنسان بجراب فيه شحم، فنزوت لآخذه، فالتفت فإذا النبي صلى الله عليه وسلم فاستحييت»", "4214"], ["باب غزوة خيبر", "حدثني عبيد بن إسماعيل، عن أبي أسامة، عن عبيد الله، عن نافع، وسالم، عن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم «نهى يوم خيبر عن أكل الثوم، وعن لحوم الحمر الأهلية» نهى عن أكل الثوم «هو عن نافع وحده،» ولحوم الحمر الأهلية \" عن سالم", "4215"], ["باب غزوة خيبر", "حدثني يحيى بن قزعة، حدثنا مالك، عن ابن شهاب، عن عبد الله، والحسن، ابني محمد بن علي، عن أبيهما، عن علي بن أبي طالب رضي الله عنه، أن رسول الله صلى الله عليه وسلم: «نهى عن متعة النساء يوم خيبر، وعن أكل لحوم الحمر الإنسية»", "4216"], ["باب غزوة خيبر", "حدثنا محمد بن مقاتل، أخبرنا عبد الله، حدثنا عبيد الله بن عمر، عن نافع، عن ابن عمر أن رسول الله صلى الله عليه وسلم: «نهى يوم خيبر عن لحوم الحمر الأهلية»", "4217"], ["باب غزوة خيبر", "حدثني إسحاق بن نصر، حدثنا محمد بن عبيد، حدثنا عبيد الله، عن نافع، وسالم، عن ابن عمر رضي الله عنهما، قال: «نهى النبي صلى الله عليه وسلم عن أكل لحوم الحمر الأهلية»", "4218"], ["باب غزوة خيبر", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن عمرو، عن محمد بن علي، عن جابر بن عبد الله رضي الله عنهما، قال: «نهى رسول الله صلى الله عليه وسلم يوم خيبر عن لحوم الحمر الأهلية، ورخص في الخيل»", "4219"], ["باب غزوة خيبر", "حدثنا سعيد بن سليمان، حدثنا عباد، عن الشيباني، قال: سمعت ابن أبي أوفى رضي الله عنهما، أصابتنا مجاعة يوم خيبر فإن القدور لتغلي، قال: وبعضها نضجت، فجاء منادي النبي صلى الله عليه وسلم: «لا تأكلوا من لحوم الحمر شيئا، وأهرقوها». قال ابن أبي أوفى: \" فتحدثنا أنه إنما نهى عنها لأنها لم تخمس، وقال بعضهم: نهى عنها البتة لأنها كانت تأكل العذرة \"", "4220"], ["باب غزوة خيبر", "حدثنا حجاج بن منهال، حدثنا شعبة، قال: أخبرني عدي بن ثابت، عن البراء، وعبد الله بن أبي أوفى رضي الله عنهم، أنهم كانوا مع النبي صلى الله عليه وسلم فأصابوا حمرا، فطبخوها فنادى منادي النبي صلى الله عليه وسلم: «أكفئوا القدور»", "4221"], ["باب غزوة خيبر", "حدثني إسحاق، حدثنا عبد الصمد، حدثنا شعبة، حدثنا عدي بن ثابت، سمعت البراء، وابن أبي أوفى، رضي الله عنهم، يحدثان عن النبي صلى الله عليه وسلم أنه قال: يوم خيبر وقد نصبوا القدور: «أكفئوا القدور»", "4223"], ["باب غزوة خيبر", "حدثنا مسلم، حدثنا شعبة، عن عدي بن ثابت، عن البراء قال: غزونا مع النبي صلى الله عليه وسلم نحوه", "4225"], ["باب غزوة خيبر", "حدثني إبراهيم بن موسى، أخبرنا ابن أبي زائدة، أخبرنا عاصم، عن عامر، عن البراء بن عازب رضي الله عنهما، قال: أمرنا النبي صلى الله عليه وسلم في غزوة خيبر «أن نلقي الحمر الأهلية نيئة ونضيجة، ثم لم يأمرنا بأكله بعد»", "4226"], ["باب غزوة خيبر", "حدثني محمد بن أبي الحسين، حدثنا عمر بن حفص، حدثنا أبي، عن عاصم، عن عامر، عن ابن عباس رضي الله عنهما، قال: «لا أدري أنهى عنه رسول الله صلى الله عليه وسلم من أجل أنه كان حمولة الناس فكره أن تذهب حمولتهم، أو حرمه في يوم خيبر لحم الحمر الأهلية»", "4227"], ["باب غزوة خيبر", "حدثنا الحسن بن إسحاق، حدثنا محمد بن سابق، حدثنا زائدة ، عن عبيد الله بن عمر، عن نافع، عن ابن عمر رضي الله عنهما، قال: «قسم رسول الله صلى الله عليه وسلم يوم خيبر للفرس سهمين، وللراجل سهما» قال: فسره نافع فقال: «إذا كان مع الرجل فرس فله ثلاثة أسهم، فإن لم يكن له فرس فله سهم»", "4228"], ["باب غزوة خيبر", "حدثنا يحيى بن بكير، حدثنا الليث، عن يونس، عن ابن شهاب، عن سعيد بن المسيب، أن جبير بن مطعم، أخبره قال: مشيت أنا وعثمان بن عفان، إلى النبي صلى الله عليه وسلم فقلنا: أعطيت بني المطلب من خمس خيبر، وتركتنا، ونحن بمنزلة واحدة منك، فقال «إنما بنو هاشم، وبنو المطلب شيء واحد» قال جبير: «ولم يقسم النبي صلى الله عليه وسلم لبني عبد شمس، وبني نوفل شيئا»", "4229"], ["باب غزوة خيبر", "حدثني محمد بن العلاء، حدثنا أبو أسامة، حدثنا بريد بن عبد الله، عن أبي بردة، عن أبي موسى رضي الله عنه، قال: بلغنا مخرج النبي صلى الله عليه وسلم ونحن باليمن، فخرجنا مهاجرين إليه أنا وأخوان لي أنا أصغرهم، أحدهما أبو بردة، والآخر أبو رهم، إما قال: بضع، وإما قال: في ثلاثة وخمسين، أو اثنين وخمسين رجلا من قومي، فركبنا سفينة، فألقتنا سفينتنا إلى النجاشي بالحبشة، فوافقنا جعفر بن أبي طالب، فأقمنا معه حتى قدمنا جميعا، فوافقنا النبي صلى الله عليه وسلم حين افتتح خيبر، وكان أناس من الناس يقولون لنا، يعني لأهل السفينة: سبقناكم بالهجرة، ودخلت أسماء بنت عميس، وهي ممن قدم معنا، على حفصة زوج النبي صلى الله عليه وسلم زائرة، وقد كانت هاجرت إلى النجاشي فيمن هاجر، فدخل عمر على حفصة، وأسماء عندها، فقال عمر حين رأى أسماء: من هذه؟ قالت: أسماء بنت عميس، قال عمر: الحبشية هذه البحرية هذه؟ قالت أسماء: نعم، قال: سبقناكم بالهجرة، فنحن أحق برسول الله صلى الله عليه وسلم منكم، فغضبت وقالت: كلا والله، كنتم مع رسول الله صلى الله عليه وسلم يطعم جائعكم، ويعظ جاهلكم، وكنا في دار - أو في أرض - البعداء البغضاء بالحبشة، وذلك في الله وفي رسوله صلى الله عليه وسلم، وايم الله لا أطعم طعاما ولا أشرب شرابا، حتى أذكر ما قلت لرسول الله صلى الله عليه وسلم، ونحن كنا نؤذى ونخاف، وسأذكر ذلك للنبي صلى الله عليه وسلم وأسأله، والله لا أكذب ولا أزيغ، ولا أزيد عليه،", "4230"], ["باب غزوة خيبر", "فلما جاء النبي صلى الله عليه وسلم قالت: يا نبي الله إن عمر قال: كذا وكذا؟ قال: «فما قلت له؟» قالت: قلت له: كذا وكذا، قال: «ليس بأحق بي منكم، وله ولأصحابه هجرة واحدة، ولكم أنتم - أهل السفينة - هجرتان»، قالت: فلقد رأيت أبا موسى وأصحاب السفينة يأتوني أرسالا، يسألوني عن هذا الحديث، ما من الدنيا شيء هم به أفرح ولا أعظم في أنفسهم مما قال لهم النبي صلى الله عليه وسلم، قال أبو بردة: قالت أسماء: فلقد رأيت أبا موسى وإنه ليستعيد هذا الحديث مني،", "4231"], ["باب غزوة خيبر", "قال أبو بردة، عن أبي موسى، قال النبي صلى الله عليه وسلم: \" إني لأعرف أصوات رفقة الأشعريين بالقرآن حين يدخلون بالليل، وأعرف منازلهم من أصواتهم بالقرآن بالليل، وإن كنت لم أر منازلهم حين نزلوا بالنهار، ومنهم حكيم، إذا لقي الخيل، أو قال: العدو، قال لهم: إن أصحابي يأمرونكم أن تنظروهم \"", "4232"], ["باب غزوة خيبر", "حدثني إسحاق بن إبراهيم، سمع حفص بن غياث، حدثنا بريد بن عبد الله، عن أبي بردة، عن أبي موسى، قال: «قدمنا على النبي صلى الله عليه وسلم بعد أن افتتح خيبر فقسم لنا، ولم يقسم لأحد لم يشهد الفتح غيرنا»", "4233"], ["باب غزوة خيبر", "حدثنا عبد الله بن محمد، حدثنا معاوية بن عمرو، حدثنا أبو إسحاق، عن مالك بن أنس، قال: حدثني ثور، قال: حدثني سالم، مولى ابن مطيع، أنه سمع أبا هريرة رضي الله عنه، يقول: افتتحنا خيبر، ولم نغنم ذهبا ولا فضة، إنما غنمنا البقر والإبل والمتاع والحوائط، ثم انصرفنا مع رسول الله صلى الله عليه وسلم إلى وادي القرى، ومعه عبد له يقال له مدعم، أهداه له أحد بني الضباب، فبينما هو يحط رحل رسول الله صلى الله عليه وسلم إذ جاءه سهم عائر، حتى أصاب ذلك العبد، فقال الناس: هنيئا له الشهادة، فقال رسول الله صلى الله عليه وسلم: «بل، والذي نفسي بيده، إن الشملة التي أصابها يوم خيبر من المغانم، لم تصبها المقاسم، لتشتعل عليه نارا» فجاء رجل حين سمع ذلك من النبي صلى الله عليه وسلم بشراك أو بشراكين، فقال: هذا شيء كنت أصبته، فقال رسول الله صلى الله عليه وسلم: «شراك - أو شراكان - من نار»", "4234"], ["باب غزوة خيبر", "حدثنا سعيد بن أبي مريم، أخبرنا محمد بن جعفر، قال: أخبرني زيد، عن أبيه، أنه سمع عمر بن الخطاب رضي الله عنه يقول: «أما والذي نفسي بيده لولا أن أترك آخر الناس ببانا ليس لهم شيء، ما فتحت علي قرية إلا قسمتها كما قسم النبي صلى الله عليه وسلم خيبر ولكني أتركها خزانة لهم يقتسمونها»", "4235"], ["باب غزوة خيبر", "حدثني محمد بن المثنى، حدثنا ابن مهدي، عن مالك بن أنس، عن زيد بن أسلم، عن أبيه، عن عمر رضي الله عنه، قال: «لولا آخر المسلمين، ما فتحت عليهم قرية إلا قسمتها، كما قسم النبي صلى الله عليه وسلم خيبر»", "4236"], ["باب غزوة خيبر", "حدثنا علي بن عبد الله، حدثنا سفيان، قال: سمعت الزهري، وسأله إسماعيل بن أمية، قال: أخبرني عنبسة بن سعيد، أن أبا هريرة رضي الله عنه، أتى النبي صلى الله عليه وسلم فسأله، قال له بعض بني سعيد بن العاص لا تعطه، فقال أبو هريرة هذا قاتل ابن قوقل فقال: «وا عجباه لوبر، تدلى من قدوم الضأن»", "4237"], ["باب غزوة خيبر", "ويذكر عن الزبيدي، عن الزهري، قال: أخبرني عنبسة بن سعيد أنه سمع أبا هريرة، يخبر سعيد بن العاص قال: بعث رسول الله صلى الله عليه وسلم أبان على سرية من المدينة قبل نجد، قال أبو هريرة: فقدم أبان وأصحابه على النبي صلى الله عليه وسلم بخيبر بعد ما افتتحها، وإن حزم خيلهم لليف قال أبو هريرة: قلت: يا رسول الله، لا تقسم لهم، قال أبان: وأنت بهذا يا وبر، تحدر من رأس ضأن. فقال النبي صلى الله عليه وسلم: «يا أبان اجلس» فلم يقسم لهم", "4238"], ["باب غزوة خيبر", "حدثنا موسى بن إسماعيل، حدثنا عمرو بن يحيى بن سعيد، قال: أخبرني جدي، أن أبان بن سعيد أقبل إلى النبي صلى الله عليه وسلم فسلم عليه، فقال أبو هريرة: يا رسول الله، هذا قاتل ابن قوقل، وقال أبان لأبي هريرة: «واعجبا لك، وبر تدأدأ من قدوم ضأن ينعى علي امرأ أكرمه الله بيدي، ومنعه أن يهينني بيده»", "4239"], ["باب غزوة خيبر", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عروة، عن عائشة، أن فاطمة عليها السلام، بنت النبي صلى الله عليه وسلم أرسلت إلى أبي بكر تسأله ميراثها من رسول الله صلى الله عليه وسلم مما أفاء الله عليه بالمدينة، وفدك وما بقي من خمس خيبر فقال أبو بكر: إن رسول الله صلى الله عليه وسلم قال: «لا نورث، ما تركنا صدقة، إنما يأكل آل محمد - صلى الله عليه وسلم - في هذا المال»، وإني والله لا أغير شيئا من صدقة رسول الله صلى الله عليه وسلم عن حالها التي كان عليها في عهد رسول الله صلى الله عليه وسلم، ولأعملن فيها بما عمل به رسول الله صلى الله عليه وسلم. فأبى أبو بكر أن يدفع إلى فاطمة منها شيئا، فوجدت فاطمة على أبي بكر في ذلك، فهجرته فلم تكلمه حتى توفيت، وعاشت بعد النبي صلى الله عليه وسلم ستة أشهر، فلما توفيت دفنها زوجها علي ليلا، ولم يؤذن بها أبا بكر وصلى عليها، وكان لعلي من الناس وجه حياة فاطمة، فلما توفيت استنكر علي وجوه الناس، فالتمس مصالحة أبي بكر ومبايعته، ولم يكن يبايع تلك الأشهر، فأرسل إلى أبي بكر: أن ائتنا ولا يأتنا أحد معك، كراهية لمحضر عمر، فقال عمر: لا والله لا تدخل عليهم وحدك، فقال أبو بكر: وما عسيتهم أن يفعلوا بي، والله لآتينهم، فدخل عليهم أبو بكر، فتشهد علي، فقال: إنا قد عرفنا فضلك وما أعطاك الله ، ولم ننفس عليك خيرا ساقه الله إليك، ولكنك استبددت علينا بالأمر، وكنا نرى لقرابتنا من رسول الله صلى الله عليه وسلم نصيبا، حتى فاضت عينا أبي بكر، فلما تكلم أبو بكر قال: والذي نفسي بيده لقرابة رسول الله صلى الله عليه وسلم أحب إلي أن أصل من قرابتي، وأما الذي شجر بيني وبينكم من هذه الأموال، فلم آل فيها عن الخير، ولم أترك أمرا رأيت رسول الله صلى الله عليه وسلم يصنعه فيها إلا صنعته، فقال علي لأبي بكر: موعدك العشية للبيعة، فلما صلى أبو بكر الظهر رقي على المنبر، فتشهد، وذكر شأن علي وتخلفه عن البيعة، وعذره بالذي اعتذر إليه، ثم استغفر وتشهد علي، فعظم حق أبي بكر، وحدث: أنه لم يحمله على الذي صنع نفاسة على أبي بكر، ولا إنكارا للذي فضله الله به، ولكنا نرى لنا في هذا الأمر نصيبا، فاستبد علينا، فوجدنا في أنفسنا، فسر بذلك المسلمون، وقالوا: أصبت، وكان المسلمون إلى علي قريبا، حين راجع الأمر المعروف", "4240"], ["باب غزوة خيبر", "حدثني محمد بن بشار، حدثنا حرمي، حدثنا شعبة، قال: أخبرني عمارة، عن عكرمة، عن عائشة رضي الله عنها، قالت: «لما فتحت خيبر قلنا الآن نشبع من التمر»", "4242"], ["باب غزوة خيبر", "حدثنا الحسن، حدثنا قرة بن حبيب، حدثنا عبد الرحمن بن عبد الله بن دينار، عن أبيه، عن ابن عمر رضي الله عنهما، قال: «ما شبعنا حتى فتحنا خيبر»", "4243"], ["باب استعمال النبي صلى الله عليه وسلم على أهل خيبر", "حدثنا إسماعيل، قال: حدثني مالك، عن عبد المجيد بن سهيل، عن سعيد بن المسيب، عن أبي سعيد الخدري، وأبي هريرة رضي الله عنهما، أن رسول الله صلى الله عليه وسلم استعمل رجلا على خيبر، فجاءه بتمر جنيب فقال رسول الله صلى الله عليه وسلم: «أكل تمر خيبر هكذا»، فقال: لا والله يا رسول الله، إنا لنأخذ الصاع من هذا بالصاعين، بالثلاثة، فقال: «لا تفعل، بع الجمع بالدراهم، ثم ابتع بالدراهم جنيبا»", "4244"], ["باب استعمال النبي صلى الله عليه وسلم على أهل خيبر", "وقال عبد العزيز بن محمد، عن عبد المجيد، عن سعيد، أن أبا سعيد، وأبا هريرة حدثاه أن النبي صلى الله عليه وسلم بعث أخا بني عدي من الأنصار إلى خيبر، فأمره عليها، وعن عبد المجيد، عن أبي صالح السمان، عن أبي هريرة، وأبي سعيد مثله", "4246"], ["باب معاملة النبي صلى الله عليه وسلم أهل خيبر", "حدثنا موسى بن إسماعيل، حدثنا جويرية، عن نافع، عن عبد الله رضي الله عنه، قال: \" أعطى النبي صلى الله عليه وسلم خيبر اليهود: أن يعملوها ويزرعوها، ولهم شطر ما يخرج منها \"", "4248"], ["باب الشاة التي سمت للنبي صلى الله عليه وسلم بخيبر", "حدثنا عبد الله بن يوسف، حدثنا الليث، حدثني سعيد، عن أبي هريرة رضي الله عنه، قال: «لما فتحت خيبر أهديت لرسول الله صلى الله عليه وسلم شاة فيها سم»", ""], ["باب غزوة زيد بن حارثة", "حدثنا مسدد، حدثنا يحيى بن سعيد، حدثنا سفيان بن سعيد، حدثنا عبد الله بن دينار، عن ابن عمر رضي الله عنهما، قال: أمر رسول الله صلى الله عليه وسلم أسامة على قوم فطعنوا في إمارته، فقال: «إن تطعنوا في إمارته فقد طعنتم في إمارة أبيه من قبله، وايم الله لقد كان خليقا للإمارة، وإن كان من أحب الناس إلي، وإن هذا لمن أحب الناس إلي بعده»", "4250"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "حدثني عمرو بن محمد، حدثنا هشيم، أخبرنا حصين، أخبرنا أبو ظبيان، قال: سمعت أسامة بن زيد رضي الله عنهما، يقول: بعثنا رسول الله صلى الله عليه وسلم إلى الحرقة، فصبحنا القوم فهزمناهم، ولحقت أنا ورجل من الأنصار رجلا منهم، فلما غشيناه، قال: لا إله إلا الله فكف الأنصاري فطعنته برمحي حتى قتلته، فلما قدمنا بلغ النبي صلى الله عليه وسلم، فقال: «يا أسامة، أقتلته بعد ما قال لا إله إلا الله» قلت: كان متعوذا، فما زال يكررها، حتى تمنيت أني لم أكن أسلمت قبل ذلك اليوم", "4269"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "حدثنا قتيبة بن سعيد، حدثنا حاتم، عن يزيد بن أبي عبيد، قال: سمعت سلمة بن الأكوع، يقول: «غزوت مع النبي صلى الله عليه وسلم سبع غزوات، وخرجت فيما يبعث من البعوث تسع غزوات مرة علينا أبو بكر، ومرة علينا أسامة»", "4270"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "وقال عمر بن حفص بن غياث، حدثنا أبي، عن يزيد بن أبي عبيد، قال: سمعت سلمة يقول: غزوت مع النبي صلى الله عليه وسلم سبع غزوات، وخرجت فيما يبعث من البعث تسع غزوات، علينا مرة أبو بكر، ومرة أسامة", "4271"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "حدثنا أبو عاصم الضحاك بن مخلد، حدثنا يزيد بن أبي عبيد، عن سلمة بن الأكوع رضي الله عنه، قال: «غزوت مع النبي صلى الله عليه وسلم سبع غزوات، وغزوت مع ابن حارثة استعمله علينا»", "4272"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "حدثنا محمد بن عبد الله، حدثنا حماد بن مسعدة ، عن يزيد بن أبي عبيد، عن سلمة بن الأكوع، قال \" غزوت مع النبي صلى الله عليه وسلم سبع غزوات، فذكر: خيبر، والحديبية، ويوم حنين، ويوم القرد \" قال يزيد: «ونسيت بقيتهم»", "4273"], ["باب عمرة القضاء", "حدثني عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء رضي الله عنه، قال: لما اعتمر النبي صلى الله عليه وسلم في ذي القعدة، فأبى أهل مكة أن يدعوه يدخل مكة، حتى قاضاهم على أن يقيم بها ثلاثة أيام، فلما كتبوا الكتاب، كتبوا: هذا ما قاضى عليه محمد رسول الله، قالوا: لا نقر لك بهذا، لو نعلم أنك رسول الله ما منعناك شيئا، ولكن أنت محمد بن عبد الله، فقال «أنا رسول الله، وأنا محمد بن عبد الله»، ثم قال: لعلي بن أبي طالب رضي الله عنه: «امح رسول الله»، قال علي: لا والله لا أمحوك أبدا، فأخذ رسول الله صلى الله عليه وسلم الكتاب، وليس يحسن يكتب، فكتب: هذا ما قاضى عليه محمد بن عبد الله، لا يدخل مكة السلاح إلا السيف في القراب، وأن لا يخرج من أهلها بأحد إن أراد أن يتبعه، وأن لا يمنع من أصحابه أحدا، إن أراد أن يقيم بها. فلما دخلها ومضى الأجل أتوا عليا، فقالوا: قل لصاحبك: اخرج عنا، فقد مضى الأجل، فخرج النبي صلى الله عليه وسلم، فتبعته ابنة حمزة، تنادي يا عم يا عم، فتناولها علي فأخذ بيدها، وقال لفاطمة عليها السلام: دونك ابنة عمك حملتها، فاختصم فيها علي وزيد وجعفر، قال علي: أنا أخذتها، وهي بنت عمي، وقال جعفر: ابنة عمي وخالتها تحتي، وقال زيد: ابنة أخي. فقضى بها النبي صلى الله عليه وسلم لخالتها، وقال: «الخالة بمنزلة الأم» وقال لعلي: «أنت مني وأنا منك» وقال لجعفر: «أشبهت خلقي وخلقي»، وقال لزيد: «أنت أخونا ومولانا»، وقال علي: ألا تتزوج بنت حمزة؟ قال: «إنها ابنة أخي من الرضاعة»", "4251"], ["باب عمرة القضاء", "حدثني محمد بن رافع، حدثنا سريج، حدثنا فليح، ح وحدثني محمد بن الحسين بن إبراهيم، قال: حدثني أبي، حدثنا فليح بن سليمان، عن نافع، عن ابن عمر رضي الله عنهما «أن رسول الله صلى الله عليه وسلم خرج معتمرا، فحال كفار قريش بينه وبين البيت، فنحر هديه وحلق رأسه بالحديبية، وقاضاهم على أن يعتمر العام المقبل، ولا يحمل سلاحا عليهم إلا سيوفا، ولا يقيم بها إلا ما أحبوا، فاعتمر من العام المقبل، فدخلها كما كان صالحهم، فلما أن أقام بها ثلاثا، أمروه أن يخرج فخرج»", "4252"], ["باب عمرة القضاء", "حدثني عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن مجاهد، قال: دخلت أنا وعروة بن الزبير المسجد، فإذا عبد الله بن عمر رضي الله عنهما، جالس إلى حجرة عائشة ثم قال: «كم اعتمر النبي صلى الله عليه وسلم؟» قال: أربعا،", "4253"], ["باب عمرة القضاء", "ثم سمعنا استنان عائشة، قال عروة: يا أم المؤمنين ألا تسمعين ما يقول أبو عبد الرحمن إن النبي صلى الله عليه وسلم اعتمر أربع عمر، فقالت: «ما اعتمر النبي صلى الله عليه وسلم عمرة إلا وهو شاهده. وما اعتمر في رجب قط»", "4254"], ["باب عمرة القضاء", "حدثنا علي بن عبد الله، حدثنا سفيان، عن إسماعيل بن أبي خالد، سمع ابن أبي أوفى، يقول «لما اعتمر رسول الله صلى الله عليه وسلم سترناه من غلمان المشركين ومنهم، أن يؤذوا رسول الله صلى الله عليه وسلم»", "4255"], ["باب عمرة القضاء", "حدثنا سليمان بن حرب، حدثنا حماد هو ابن زيد، عن أيوب، عن سعيد بن جبير، عن ابن عباس رضي الله عنهما، قال: قدم رسول الله صلى الله عليه وسلم وأصحابه، فقال المشركون: إنه يقدم عليكم وفد وهنهم حمى يثرب، «وأمرهم النبي صلى الله عليه وسلم أن يرملوا الأشواط الثلاثة، وأن يمشوا ما بين الركنين، ولم يمنعه أن يأمرهم، أن يرملوا الأشواط كلها إلا الإبقاء عليهم» قال أبو عبد الله: وزاد ابن سلمة، عن أيوب، عن سعيد بن جبير، عن ابن عباس، قال: لما قدم النبي صلى الله عليه وسلم لعامه الذي استأمن، قال: «ارملوا» ليرى المشركون قوتهم، والمشركون من قبل قعيقعان", "4256"], ["باب عمرة القضاء", "حدثني محمد، عن سفيان بن عيينة، عن عمرو، عن عطاء، عن ابن عباس رضي الله عنهما، قال: «إنما سعى النبي صلى الله عليه وسلم بالبيت، وبين الصفا والمروة، ليري المشركين قوته»", "4257"], ["باب عمرة القضاء", "حدثنا موسى بن إسماعيل، حدثنا وهيب، حدثنا أيوب، عن عكرمة، عن ابن عباس، قال: \" تزوج النبي صلى الله عليه وسلم ميمونة وهو محرم، وبنى بها وهو حلال، وماتت بسرف،", "4258"], ["باب عمرة القضاء", "قال أبو عبد الله: وزاد ابن إسحاق، حدثني ابن أبي نجيح، وأبان بن صالح، عن عطاء، ومجاهد، عن ابن عباس قال: «تزوج النبي صلى الله عليه وسلم ميمونة في عمرة القضاء»", "4259"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا أحمد، حدثنا ابن وهب، عن عمرو، عن ابن أبي هلال، قال: وأخبرني نافع، أن ابن عمر، أخبره: «أنه وقف على جعفر يومئذ، وهو قتيل، فعددت به خمسين، بين طعنة وضربة، ليس منها شيء في دبره» يعني في ظهره", "4260"], ["باب غزوة مؤتة من أرض الشأم", "أخبرنا أحمد بن أبي بكر، حدثنا مغيرة بن عبد الرحمن، عن عبد الله بن سعيد، عن نافع، عن عبد الله بن عمر رضي الله عنهما، قال: أمر رسول الله صلى الله عليه وسلم في غزوة مؤتة زيد بن حارثة، فقال رسول الله صلى الله عليه وسلم: «إن قتل زيد فجعفر، وإن قتل جعفر فعبد الله بن رواحة» قال عبد الله: كنت فيهم في تلك الغزوة، فالتمسنا جعفر بن أبي طالب، فوجدناه في القتلى، ووجدنا ما في جسده بضعا وتسعين، من طعنة ورمية \"", "4261"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا أحمد بن واقد، حدثنا حماد بن زيد، عن أيوب، عن حميد بن هلال، عن أنس رضي الله عنه، أن النبي صلى الله عليه وسلم نعى زيدا، وجعفرا، وابن رواحة للناس قبل أن يأتيهم خبرهم، فقال: «أخذ الراية زيد فأصيب، ثم أخذ جعفر فأصيب، ثم أخذ ابن رواحة فأصيب» وعيناه تذرفان: «حتى أخذ الراية سيف من سيوف الله، حتى فتح الله عليهم»", "4262"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا قتيبة، حدثنا عبد الوهاب، قال: سمعت يحيى بن سعيد، قال: أخبرتني عمرة قالت: سمعت عائشة رضي الله عنها، تقول: لما جاء قتل ابن حارثة، وجعفر بن أبي طالب، وعبد الله بن رواحة رضي الله عنهم، جلس رسول الله صلى الله عليه وسلم يعرف فيه الحزن، قالت عائشة: وأنا أطلع من صائر الباب، تعني من شق الباب، فأتاه رجل، فقال: أي رسول الله إن نساء جعفر، قال: وذكر بكاءهن، فأمره أن ينهاهن، قال: فذهب الرجل ثم أتى، فقال: قد نهيتهن، وذكر أنه لم يطعنه، قال: فأمر أيضا، فذهب ثم أتى فقال: والله لقد غلبننا، فزعمت أن رسول الله صلى الله عليه وسلم قال: «فاحث في أفواههن من التراب» قالت عائشة: فقلت: أرغم الله أنفك، فوالله ما أنت تفعل، وما تركت رسول الله صلى الله عليه وسلم من العناء", "4263"], ["باب غزوة مؤتة من أرض الشأم", "حدثني محمد بن أبي بكر، حدثنا عمر بن علي، عن إسماعيل بن أبي خالد، عن عامر، قال: كان ابن عمر إذا حيا ابن جعفر قال: «السلام عليك يا ابن ذي الجناحين»", "4264"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا أبو نعيم، حدثنا سفيان، عن إسماعيل، عن قيس بن أبي حازم، قال: سمعت خالد بن الوليد، يقول: «لقد انقطعت في يدي يوم مؤتة تسعة أسياف فما بقي في يدي إلا صفيحة يمانية»", "4265"], ["باب غزوة مؤتة من أرض الشأم", "حدثني محمد بن المثنى، حدثنا يحيى، عن إسماعيل، قال: حدثني قيس، قال: سمعت خالد بن الوليد، يقول: «لقد دق في يدي يوم مؤتة تسعة أسياف، وصبرت في يدي صفيحة لي يمانية»", "4266"], ["باب غزوة مؤتة من أرض الشأم", "حدثني عمران بن ميسرة، حدثنا محمد بن فضيل، عن حصين، عن عامر، عن النعمان بن بشير رضي الله عنهما، قال: أغمي على عبد الله بن رواحة، فجعلت أخته عمرة تبكي واجبلاه، واكذا واكذا، تعدد عليه، فقال حين أفاق: \" ما قلت شيئا إلا قيل لي: آنت كذلك «", "4267"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا قتيبة، حدثنا عبثر، عن حصين، عن الشعبي، عن النعمان بن بشير،» قال أغمي على عبد الله بن رواحة بهذا فلما مات لم تبك عليه \"", "4268"], ["باب غزوة الفتح", "حدثنا قتيبة بن سعيد، حدثنا سفيان، عن عمرو بن دينار، قال: أخبرني الحسن بن محمد، أنه سمع عبيد الله بن أبي رافع، يقول: سمعت عليا رضي الله عنه، يقول: بعثني رسول الله صلى الله عليه وسلم أنا والزبير، والمقداد، فقال: «انطلقوا حتى تأتوا روضة خاخ، فإن بها ظعينة معها كتاب، فخذوا منها» قال: فانطلقنا تعادى بنا خيلنا حتى أتينا الروضة، فإذا نحن بالظعينة، قلنا لها: أخرجي الكتاب، قالت: ما معي كتاب، فقلنا: لتخرجن الكتاب، أو لنلقين الثياب، قال: فأخرجته من عقاصها، فأتينا به رسول الله صلى الله عليه وسلم، فإذا فيه: من حاطب بن أبي بلتعة، إلى ناس بمكة من المشركين، يخبرهم ببعض أمر رسول الله صلى الله عليه وسلم. فقال رسول الله صلى الله عليه وسلم: «يا حاطب، ما هذا؟» قال: يا رسول الله، لا تعجل علي، إني كنت امرأ ملصقا في قريش، يقول: كنت حليفا، ولم أكن من أنفسها، وكان من معك من المهاجرين من لهم قرابات يحمون أهليهم وأموالهم، فأحببت إذ فاتني ذلك من النسب فيهم، أن أتخذ عندهم يدا يحمون قرابتي، ولم أفعله ارتدادا عن ديني، ولا رضا بالكفر بعد الإسلام، فقال رسول الله صلى الله عليه وسلم: «أما إنه قد صدقكم»، فقال عمر: يا رسول الله، دعني أضرب عنق هذا المنافق، فقال: \" إنه قد شهد بدرا، وما يدريك لعل الله اطلع على من شهد بدرا فقال: اعملوا ما شئتم فقد غفرت لكم \". فأنزل الله السورة: {يا أيها الذين آمنوا لا تتخذوا عدوي وعدوكم أولياء تلقون إليهم بالمودة وقد كفروا بما جاءكم من الحق} [الممتحنة: 1]- إلى قوله - {فقد ضل سواء السبيل} [البقرة: 108]", "4274"], ["باب غزوة الفتح في رمضان", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني عقيل، عن ابن شهاب، قال: أخبرني عبيد الله بن عبد الله بن عتبة، أن ابن عباس، أخبره: «أن رسول الله صلى الله عليه وسلم غزا غزوة الفتح في رمضان»، قال: وسمعت سعيد بن المسيب، يقول مثل ذلك، وعن عبيد الله بن عبد الله أخبره أن ابن عباس رضي الله عنهما قال: «صام رسول الله صلى الله عليه وسلم حتى إذا بلغ الكديد - الماء الذي بين قديد وعسفان - أفطر، فلم يزل مفطرا حتى انسلخ الشهر»", "4275"], ["باب غزوة الفتح في رمضان", "حدثني محمود، أخبرنا عبد الرزاق، أخبرنا معمر، قال: أخبرني الزهري، عن عبيد الله بن عبد الله، عن ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم «خرج في رمضان من المدينة ومعه عشرة آلاف، وذلك على رأس ثمان سنين ونصف من مقدمه المدينة، فسار هو ومن معه من المسلمين إلى مكة، يصوم ويصومون، حتى بلغ الكديد، وهو ماء بين عسفان، وقديد أفطر وأفطروا»، قال الزهري: «وإنما يؤخذ من أمر رسول الله صلى الله عليه وسلم الآخر فالآخر»", "4276"], ["باب غزوة الفتح في رمضان", "حدثني عياش بن الوليد، حدثنا عبد الأعلى، حدثنا خالد، عن عكرمة، عن ابن عباس، قال: \" خرج النبي صلى الله عليه وسلم في رمضان إلى حنين، والناس مختلفون، فصائم ومفطر، فلما استوى على راحلته، دعا بإناء من لبن أو ماء، فوضعه على راحته، أو على راحلته، ثم نظر إلى الناس فقال المفطرون للصوام: أفطروا \"", "4277"], ["باب غزوة الفتح في رمضان", "وقال عبد الرزاق، أخبرنا معمر، عن أيوب، عن عكرمة، عن ابن عباس رضي الله عنهما خرج النبي صلى الله عليه وسلم عام الفتح، وقال حماد بن زيد: عن أيوب، عن عكرمة، عن ابن عباس عن النبي صلى الله عليه وسلم", "4278"], ["باب غزوة الفتح في رمضان", "حدثنا علي بن عبد الله، حدثنا جرير، عن منصور، عن مجاهد، عن طاوس، عن ابن عباس، قال: «سافر رسول الله صلى الله عليه وسلم في رمضان، فصام حتى بلغ عسفان، ثم دعا بإناء من ماء، فشرب نهارا ليريه الناس، فأفطر حتى قدم مكة» قال: وكان ابن عباس يقول: «صام رسول الله صلى الله عليه وسلم في السفر، وأفطر فمن شاء صام ومن شاء أفطر»", "4279"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، قال: لما سار رسول الله صلى الله عليه وسلم عام الفتح، فبلغ ذلك قريشا، خرج أبو سفيان بن حرب، وحكيم بن حزام، وبديل بن ورقاء، يلتمسون الخبر عن رسول الله صلى الله عليه وسلم، فأقبلوا يسيرون حتى أتوا مر الظهران، فإذا هم بنيران كأنها نيران عرفة، فقال أبو سفيان: ما هذه، لكأنها نيران عرفة؟ فقال بديل بن ورقاء: نيران بني عمرو، فقال أبو سفيان: عمرو أقل من ذلك، فرآهم ناس من حرس رسول الله صلى الله عليه وسلم فأدركوهم فأخذوهم، فأتوا بهم رسول الله صلى الله عليه وسلم فأسلم أبو سفيان، فلما سار قال للعباس: «احبس أبا سفيان عند حطم الخيل، حتى ينظر إلى المسلمين». فحبسه العباس، فجعلت القبائل تمر مع النبي صلى الله عليه وسلم، تمر كتيبة كتيبة على أبي سفيان، فمرت كتيبة، قال: يا عباس من هذه؟ قال: هذه غفار، قال: ما لي ولغفار، ثم مرت جهينة، قال مثل ذلك، ثم مرت سعد بن هذيم فقال مثل ذلك، ومرت سليم، فقال مثل ذلك، حتى أقبلت كتيبة لم ير مثلها، قال: من هذه؟ قال: هؤلاء الأنصار، عليهم سعد بن عبادة معه الراية، فقال سعد بن عبادة: يا أبا سفيان، اليوم يوم الملحمة، اليوم تستحل الكعبة، فقال أبو سفيان: يا عباس حبذا يوم الذمار، ثم جاءت كتيبة، وهي أقل الكتائب، فيهم رسول الله صلى الله عليه وسلم وأصحابه، وراية النبي صلى الله عليه وسلم مع الزبير بن العوام، فلما مر رسول الله صلى الله عليه وسلم بأبي سفيان قال: ألم تعلم ما قال سعد بن عبادة؟ قال: «ما قال؟» قال: كذا وكذا، فقال: «كذب سعد، ولكن هذا يوم يعظم الله فيه الكعبة، ويوم تكسى فيه الكعبة» قال: وأمر رسول الله صلى الله عليه وسلم أن تركز رايته بالحجون قال عروة، وأخبرني نافع بن جبير بن مطعم، قال: سمعت العباس، يقول للزبير بن العوام: يا أبا عبد الله ها هنا أمرك رسول الله صلى الله عليه وسلم أن تركز الراية، قال: \" وأمر رسول الله صلى الله عليه وسلم يومئذ خالد بن الوليد أن يدخل من أعلى مكة من كداء، ودخل النبي صلى الله عليه وسلم من كدا، فقتل من خيل خالد بن الوليد رضي الله عنه يومئذ رجلان: حبيش بن الأشعر، وكرز بن جابر الفهري", "4280"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا أبو الوليد، حدثنا شعبة، عن معاوية بن قرة، قال: سمعت عبد الله بن مغفل، يقول: «رأيت رسول الله صلى الله عليه وسلم يوم فتح مكة على ناقته، وهو يقرأ سورة الفتح يرجع». وقال: لولا أن يجتمع الناس حولي لرجعت كما رجع", "4281"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا سليمان بن عبد الرحمن، حدثنا سعدان بن يحيى، حدثنا محمد بن أبي حفصة، عن الزهري، عن علي بن حسين، عن عمرو بن عثمان، عن أسامة بن زيد، أنه قال زمن الفتح: يا رسول الله، أين تنزل غدا؟ قال النبي صلى الله عليه وسلم: «وهل ترك لنا عقيل من منزل»", "4282"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "ثم قال: «لا يرث المؤمن الكافر، ولا يرث الكافر المؤمن» قيل للزهري: ومن ورث أبا طالب؟ قال: «ورثه عقيل وطالب»، قال معمر عن الزهري: «أين تنزل غدا في حجته؟» ولم يقل يونس: «حجته ولا زمن الفتح»", "4283"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا أبو اليمان، حدثنا شعيب، حدثنا أبو الزناد، عن عبد الرحمن، عن أبي هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: «منزلنا - إن شاء الله، إذا فتح الله - الخيف حيث تقاسموا على الكفر»", "4284"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا موسى بن إسماعيل، حدثنا إبراهيم بن سعد، أخبرنا ابن شهاب، عن أبي سلمة، عن أبي هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم حين أراد حنينا: «منزلنا غدا إن شاء الله، بخيف بني كنانة، حيث تقاسموا على الكفر»", "4285"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا يحيى بن قزعة، حدثنا مالك، عن ابن شهاب، عن أنس بن مالك رضي الله عنه، أن النبي صلى الله عليه وسلم \" دخل مكة يوم الفتح وعلى رأسه المغفر، فلما نزعه جاء رجل فقال: ابن خطل متعلق بأستار الكعبة، فقال: «اقتله»، قال مالك: «ولم يكن النبي صلى الله عليه وسلم فيما نرى والله أعلم يومئذ محرما»", "4286"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا صدقة بن الفضل، أخبرنا ابن عيينة، عن ابن أبي نجيح، عن مجاهد، عن أبي معمر، عن عبد الله رضي الله عنه، قال: دخل النبي صلى الله عليه وسلم مكة يوم الفتح، وحول البيت ستون وثلاث مائة نصب فجعل يطعنها بعود في يده، ويقول: «جاء الحق وزهق الباطل، جاء الحق وما يبدئ الباطل وما يعيد»", "4287"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثني إسحاق، حدثنا عبد الصمد، قال: حدثني أبي، حدثنا أيوب، عن عكرمة، عن ابن عباس رضي الله عنهما: أن رسول الله صلى الله عليه وسلم لما قدم مكة، أبى أن يدخل البيت وفيه الآلهة، فأمر بها فأخرجت، فأخرج صورة إبراهيم وإسماعيل في أيديهما من الأزلام، فقال النبي صلى الله عليه وسلم: \" قاتلهم الله، لقد علموا: ما استقسما بها قط \"، ثم دخل البيت، فكبر في نواحي البيت، وخرج ولم يصل فيه تابعه معمر، عن أيوب، وقال: وهيب، حدثنا أيوب، عن عكرمة، عن النبي صلى الله عليه وسلم", "4288"], ["باب دخول النبي صلى الله عليه وسلم من أعلى مكة", "وقال الليث، حدثني يونس، قال: أخبرني نافع، عن عبد الله بن عمر رضي الله عنهما: «أن رسول الله صلى الله عليه وسلم أقبل يوم الفتح من أعلى مكة على راحلته، مردفا أسامة بن زيد، ومعه بلال، ومعه عثمان بن طلحة من الحجبة، حتى أناخ في المسجد، فأمره أن يأتي بمفتاح البيت، فدخل رسول الله صلى الله عليه وسلم ومعه أسامة بن زيد، وبلال، وعثمان بن طلحة، فمكث فيه نهارا طويلا، ثم خرج» فاستبق الناس، فكان عبد الله بن عمر أول من دخل، فوجد بلالا وراء الباب قائما، فسأله: أين صلى رسول الله صلى الله عليه وسلم؟ فأشار له إلى المكان الذي صلى فيه قال عبد الله: فنسيت أن أسأله كم صلى من سجدة", "4289"], ["باب دخول النبي صلى الله عليه وسلم من أعلى مكة", "حدثنا الهيثم بن خارجة، حدثنا حفص بن ميسرة، عن هشام بن عروة، عن أبيه، أن عائشة رضي الله عنها، أخبرته: «أن النبي صلى الله عليه وسلم دخل عام الفتح من كداء التي بأعلى مكة» تابعه أبو أسامة، ووهيب، في كداء", "4290"], ["باب دخول النبي صلى الله عليه وسلم من أعلى مكة", "حدثنا عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، «دخل النبي صلى الله عليه وسلم عام الفتح من أعلى مكة من كداء»", "4291"], ["باب منزل النبي صلى الله عليه وسلم يوم الفتح", "حدثنا أبو الوليد، حدثنا شعبة، عن عمرو، عن ابن أبي ليلى، ما أخبرنا أحد، أنه رأى النبي صلى الله عليه وسلم يصلي الضحى غير أم هانئ، فإنها ذكرت: «أنه يوم فتح مكة اغتسل في بيتها، ثم صلى ثماني ركعات»، قالت: «لم أره صلى صلاة أخف منها غير أنه يتم الركوع والسجود»", "4292"], ["باب", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن منصور، عن أبي الضحى، عن مسروق، عن عائشة رضي الله عنها، قالت: كان النبي صلى الله عليه وسلم يقول في ركوعه وسجوده: «سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي»", "4293"], ["باب", "حدثنا أبو النعمان، حدثنا أبو عوانة، عن أبي بشر، عن سعيد بن جبير، عن ابن عباس رضي الله عنهما، قال: كان عمر يدخلني مع أشياخ بدر، فقال بعضهم: لم تدخل هذا الفتى معنا ولنا أبناء مثله؟ فقال: «إنه ممن قد علمتم» قال: فدعاهم ذات يوم ودعاني معهم قال: وما رئيته دعاني يومئذ إلا ليريهم مني، فقال: ما تقولون في إذا جاء نصر الله والفتح، ورأيت الناس يدخلون في دين الله أفواجا حتى ختم السورة، فقال بعضهم: أمرنا أن نحمد الله ونستغفره إذا نصرنا وفتح علينا، وقال بعضهم: لا ندري، أو لم يقل بعضهم شيئا، فقال لي: يا ابن عباس، أكذاك تقول؟ قلت: لا، قال: فما تقول؟ قلت: هو أجل رسول الله صلى الله عليه وسلم أعلمه الله له: إذا جاء نصر الله والفتح فتح مكة، فذاك علامة أجلك: فسبح بحمد ربك واستغفره إنه كان توابا. قال عمر: «ما أعلم منها إلا ما تعلم»", "4294"], ["باب", "حدثنا سعيد بن شرحبيل، حدثنا الليث، عن المقبري، عن أبي شريح العدوي، أنه قال: لعمرو بن سعيد وهو يبعث البعوث إلى مكة ائذن لي أيها الأمير، أحدثك قولا قام به رسول الله صلى الله عليه وسلم الغد يوم الفتح، سمعته أذناي ووعاه قلبي، وأبصرته عيناي حين تكلم به، إنه حمد الله وأثنى عليه ثم قال: \" إن مكة حرمها الله، ولم يحرمها الناس، لا يحل لامرئ يؤمن بالله واليوم الآخر أن يسفك بها دما، ولا يعضد بها شجرا، فإن أحد ترخص لقتال رسول الله صلى الله عليه وسلم فيها، فقولوا له: إن الله أذن لرسوله، ولم يأذن لكم وإنما أذن لي فيها ساعة من نهار، وقد عادت حرمتها اليوم كحرمتها بالأمس، وليبلغ الشاهد الغائب \" فقيل لأبي شريح ماذا قال لك عمرو؟ قال: قال: أنا أعلم بذلك منك يا أبا شريح، إن الحرم لا يعيذ عاصيا، ولا فارا بدم، ولا فارا بخربة قال أبو عبد الله: الخربة: البلية", "4295"], ["باب", "حدثنا قتيبة، حدثنا الليث، عن يزيد بن أبي حبيب، عن عطاء بن أبي رباح، عن جابر بن عبد الله رضي الله عنهما، أنه سمع رسول الله صلى الله عليه وسلم يقول عام الفتح: وهو بمكة «إن الله ورسوله حرم بيع الخمر»", "4296"], ["باب مقام النبي صلى الله عليه وسلم بمكة زمن الفتح", "حدثنا أبو نعيم، حدثنا سفيان، ح حدثنا قبيصة، حدثنا سفيان، عن يحيى بن أبي إسحاق، عن أنس رضي الله عنه، قال: «أقمنا مع النبي صلى الله عليه وسلم عشرا نقصر الصلاة»", "4297"], ["باب مقام النبي صلى الله عليه وسلم بمكة زمن الفتح", "حدثنا عبدان، أخبرنا عبد الله، أخبرنا عاصم، عن عكرمة، عن ابن عباس رضي الله عنهما، قال: «أقام النبي صلى الله عليه وسلم بمكة تسعة عشر يوما يصلي ركعتين»", "4298"], ["باب مقام النبي صلى الله عليه وسلم بمكة زمن الفتح", "حدثنا أحمد بن يونس، حدثنا أبو شهاب، عن عاصم، عن عكرمة، عن ابن عباس، قال: «أقمنا مع النبي صلى الله عليه وسلم في سفر تسع عشرة نقصر الصلاة» وقال ابن عباس: «ونحن نقصر ما بيننا وبين تسع عشرة، فإذا زدنا أتممنا»", "4299"], ["باب:", "وقال الليث حدثني يونس، عن ابن شهاب، أخبرني عبد الله بن ثعلبة بن صعير، وكان النبي صلى الله عليه وسلم قد مسح وجهه عام الفتح", "4300"], ["باب:", "حدثني إبراهيم بن موسى، أخبرنا هشام، عن معمر، عن الزهري، عن سنين أبي جميلة، قال: أخبرنا ونحن مع ابن المسيب، قال: «وزعم أبو جميلة أنه أدرك النبي صلى الله عليه وسلم وخرج معه عام الفتح»", "4301"], ["باب:", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن أيوب، عن أبي قلابة، عن عمرو بن سلمة، قال: قال لي أبو قلابة: ألا تلقاه فتسأله؟ قال فلقيته فسألته فقال: كنا بماء ممر الناس، وكان يمر بنا الركبان فنسألهم: ما للناس، ما للناس؟ ما هذا الرجل؟ فيقولون: يزعم أن الله أرسله، أوحى إليه، أو: أوحى الله بكذا، فكنت أحفظ ذلك الكلام، وكأنما يقر في صدري، وكانت العرب تلوم بإسلامهم الفتح، فيقولون: اتركوه وقومه، فإنه إن ظهر عليهم فهو نبي صادق، فلما كانت وقعة أهل الفتح، بادر كل قوم بإسلامهم، وبدر أبي قومي بإسلامهم، فلما قدم قال: جئتكم والله من عند النبي صلى الله عليه وسلم حقا، فقال: «صلوا صلاة كذا في حين كذا، وصلوا صلاة كذا في حين كذا، فإذا حضرت الصلاة فليؤذن أحدكم، وليؤمكم أكثركم قرآنا». فنظروا فلم يكن أحد أكثر قرآنا مني، لما كنت أتلقى من الركبان، فقدموني بين أيديهم، وأنا ابن ست أو سبع سنين، وكانت علي بردة، كنت إذا سجدت تقلصت عني، فقالت امرأة من الحي: ألا تغطوا عنا است قارئكم؟ فاشتروا فقطعوا لي قميصا، فما فرحت بشيء فرحي بذلك القميص", "4302"], ["باب:", "حدثني عبد الله بن مسلمة، عن مالك، عن ابن شهاب، عن عروة بن الزبير، عن عائشة رضي الله عنها، عن النبي صلى الله عليه وسلم وقال الليث: حدثني يونس، عن ابن شهاب، أخبرني عروة بن الزبير، أن عائشة قالت: كان عتبة بن أبي وقاص عهد إلى أخيه سعد: أن يقبض ابن وليدة زمعة، وقال عتبة: إنه ابني، فلما قدم رسول الله صلى الله عليه وسلم مكة في الفتح، أخذ سعد بن أبي وقاص ابن وليدة زمعة، فأقبل به إلى رسول الله صلى الله عليه وسلم، وأقبل معه عبد بن زمعة، فقال سعد بن أبي وقاص: هذا ابن أخي عهد إلي أنه ابنه، قال عبد بن زمعة: يا رسول الله هذا أخي هذا ابن زمعة ولد على فراشه، فنظر رسول الله صلى الله عليه وسلم إلى ابن وليدة زمعة، فإذا أشبه الناس بعتبة بن أبي وقاص فقال رسول الله صلى الله عليه وسلم: «هو لك هو أخوك يا عبد بن زمعة» من أجل أنه ولد على فراشه، وقال رسول الله صلى الله عليه وسلم: «احتجبي منه يا سودة» لما رأى من شبه عتبة بن أبي وقاص قال ابن شهاب: قالت عائشة: قال رسول الله صلى الله عليه وسلم: «الولد للفراش وللعاهر الحجر» وقال ابن شهاب: وكان أبو هريرة يصيح بذلك", "4303"], ["باب:", "حدثنا محمد بن مقاتل، أخبرنا عبد الله، أخبرنا يونس، عن الزهري، قال: أخبرني عروة بن الزبير، أن امرأة سرقت في عهد رسول الله صلى الله عليه وسلم في غزوة الفتح، ففزع قومها إلى أسامة بن زيد يستشفعونه، قال عروة: فلما كلمه أسامة فيها، تلون وجه رسول الله صلى الله عليه وسلم، فقال: «أتكلمني في حد من حدود الله»، قال أسامة: استغفر لي يا رسول الله، فلما كان العشي قام رسول الله خطيبا، فأثنى على الله بما هو أهله، ثم قال: \" أما بعد، فإنما أهلك الناس قبلكم: أنهم كانوا إذا سرق فيهم الشريف تركوه، وإذا سرق فيهم الضعيف أقاموا عليه الحد، والذي نفس محمد بيده، لو أن فاطمة بنت محمد سرقت لقطعت يدها \" ثم أمر رسول الله صلى الله عليه وسلم بتلك المرأة فقطعت يدها، فحسنت توبتها بعد ذلك وتزوجت قالت عائشة: «فكانت تأتي بعد ذلك فأرفع حاجتها إلى رسول الله صلى الله عليه وسلم»", "4304"], ["باب:", "حدثنا عمرو بن خالد، حدثنا زهير، حدثنا عاصم، عن أبي عثمان، قال: حدثني مجاشع، قال: أتيت النبي صلى الله عليه وسلم بأخي بعد الفتح، قلت: يا رسول الله، جئتك بأخي لتبايعه على الهجرة. قال: «ذهب أهل الهجرة بما فيها». فقلت: \" على أي شيء تبايعه؟ قال: «أبايعه على الإسلام، والإيمان، والجهاد» فلقيت معبدا بعد، وكان أكبرهما، فسألته فقال: «صدق مجاشع»", "4305"], ["باب:", "حدثنا محمد بن أبي بكر، حدثنا الفضيل بن سليمان، حدثنا عاصم، عن أبي عثمان النهدي، عن مجاشع بن مسعود، انطلقت بأبي معبد إلى النبي صلى الله عليه وسلم ليبايعه على الهجرة قال: «مضت الهجرة لأهلها، أبايعه على الإسلام والجهاد» فلقيت أبا معبد فسألته فقال: «صدق مجاشع» وقال خالد، عن أبي عثمان، عن مجاشع، أنه جاء بأخيه مجالد", "4307"], ["باب:", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن أبي بشر، عن مجاهد، قلت لابن عمر رضي الله عنهما: إني أريد أن أهاجر إلى الشأم، قال: «لا هجرة، ولكن جهاد، فانطلق فاعرض نفسك، فإن وجدت شيئا وإلا رجعت»", "4309"], ["باب:", "وقال النضر: أخبرنا شعبة، أخبرنا أبو بشر، سمعت مجاهدا، قلت لابن عمر: فقال: «لا هجرة اليوم أو بعد رسول الله صلى الله عليه وسلم» مثله", "4310"], ["باب:", "حدثني إسحاق بن يزيد، حدثنا يحيى بن حمزة، قال: حدثني أبو عمرو الأوزاعي، عن عبدة بن أبي لبابة، عن مجاهد بن جبر المكي، أن عبد الله بن عمر رضي الله عنهما، كان يقول: «لا هجرة بعد الفتح»", "4311"], ["باب:", "حدثنا إسحاق بن يزيد، حدثنا يحيى بن حمزة، قال: حدثني الأوزاعي، عن عطاء بن أبي رباح، قال: زرت عائشة مع عبيد بن عمير، فسألها عن الهجرة، فقالت: «لا هجرة اليوم، كان المؤمن يفر أحدهم بدينه إلى الله وإلى رسوله صلى الله عليه وسلم، مخافة أن يفتن عليه، فأما اليوم فقد أظهر الله الإسلام، فالمؤمن يعبد ربه حيث شاء ولكن جهاد ونية»", "4312"], ["باب:", "حدثنا إسحاق، حدثنا أبو عاصم، عن ابن جريج، قال: أخبرني حسن بن مسلم، عن مجاهد، أن رسول الله صلى الله عليه وسلم قام يوم الفتح فقال: «إن الله حرم مكة يوم خلق السموات والأرض، فهي حرام بحرام الله إلى يوم القيامة، لم تحل لأحد قبلي ولا تحل لأحد بعدي، ولم تحلل لي قط إلا ساعة من الدهر، لا ينفر صيدها، ولا يعضد شوكها، ولا يختلى خلاها، ولا تحل لقطتها إلا لمنشد». فقال العباس بن عبد المطلب: إلا الإذخر يا رسول الله، فإنه لا بد منه للقين والبيوت، فسكت ثم قال: «إلا الإذخر فإنه حلال» وعن ابن جريج، أخبرني عبد الكريم، عن عكرمة، عن ابن عباس، بمثل هذا أو نحو هذا، رواه أبو هريرة عن النبي صلى الله عليه وسلم", "4313"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "حدثنا محمد بن عبد الله بن نمير، حدثنا يزيد بن هارون، أخبرنا إسماعيل، رأيت بيد ابن أبي أوفى ضربة قال: «ضربتها مع النبي صلى الله عليه وسلم يوم حنين» قلت: شهدت حنينا؟ قال: قبل ذلك", "4314"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "حدثنا محمد بن كثير، حدثنا سفيان، عن أبي إسحاق، قال: سمعت البراء رضي الله عنه، وجاءه رجل، فقال: يا أبا عمارة أتوليت يوم حنين؟ فقال: أما أنا فأشهد على النبي صلى الله عليه وسلم أنه لم يول، ولكن عجل سرعان القوم، فرشقتهم هوازن، وأبو سفيان بن الحارث آخذ برأس بغلته البيضاء، يقول: «أنا النبي لا كذب، أنا ابن عبد المطلب»", "4315"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "حدثنا أبو الوليد، حدثنا شعبة، عن أبي إسحاق، قيل للبراء: وأنا أسمع أوليتم مع النبي صلى الله عليه وسلم يوم حنين؟ فقال: أما النبي صلى الله عليه وسلم فلا كانوا رماة، فقال: «أنا النبي لا كذب، أنا ابن عبد المطلب»", "4316"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن أبي إسحاق، سمع البراء، وسأله رجل من قيس أفررتم عن رسول الله صلى الله عليه وسلم يوم حنين؟ فقال: لكن رسول الله صلى الله عليه وسلم لم يفر، كانت هوازن رماة، وإنا لما حملنا عليهم انكشفوا، فأكببنا على الغنائم، فاستقبلنا بالسهام، ولقد رأيت رسول الله صلى الله عليه وسلم على بغلته البيضاء، وإن أبا سفيان بن الحارث آخذ بزمامها، وهو يقول: «أنا النبي لا كذب» قال إسرائيل، وزهير: «نزل النبي صلى الله عليه وسلم عن بغلته»", "4317"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "حدثنا سعيد بن عفير، قال: حدثني الليث، حدثني عقيل، عن ابن شهاب، ح وحدثني إسحاق ، حدثنا يعقوب بن إبراهيم، حدثنا ابن أخي ابن شهاب، قال: محمد بن شهاب، وزعم عروة بن الزبير، أن مروان، والمسور بن مخرمة، أخبراه أن رسول الله صلى الله عليه وسلم قام حين جاءه وفد هوازن مسلمين، فسألوه أن يرد إليهم أموالهم وسبيهم، فقال لهم رسول الله صلى الله عليه وسلم: \" معي من ترون، وأحب الحديث إلي أصدقه، فاختاروا إحدى الطائفتين: إما السبي، وإما المال، وقد كنت استأنيت بكم \". وكان أنظرهم رسول الله صلى الله عليه وسلم بضع عشرة ليلة حين قفل من الطائف، فلما تبين لهم أن رسول الله صلى الله عليه وسلم غير راد إليهم إلا إحدى الطائفتين، قالوا: فإنا نختار سبينا، فقام رسول الله صلى الله عليه وسلم في المسلمين، فأثنى على الله بما هو أهله ثم قال: «أما بعد، فإن إخوانكم قد جاءونا تائبين، وإني قد رأيت أن أرد إليهم سبيهم، فمن أحب منكم أن يطيب ذلك فليفعل، ومن أحب منكم أن يكون على حظه حتى نعطيه إياه من أول ما يفيء الله علينا فليفعل» فقال الناس: قد طيبنا ذلك يا رسول الله، فقال رسول الله صلى الله عليه وسلم: «إنا لا ندري من أذن منكم في ذلك ممن لم يأذن، فارجعوا حتى يرفع إلينا عرفاؤكم أمركم» فرجع الناس، فكلمهم عرفاؤهم، ثم رجعوا إلى رسول الله صلى الله عليه وسلم فأخبروه أنهم قد طيبوا وأذنوا هذا الذي بلغني عن سبي هوازن", "4318"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "حدثنا أبو النعمان، حدثنا حماد بن زيد، عن أيوب، عن نافع، أن عمر، قال: يا رسول الله. ح حدثني محمد بن مقاتل، أخبرنا عبد الله، أخبرنا معمر، عن أيوب، عن نافع، عن ابن عمر رضي الله عنهما، قال: لما قفلنا من حنين، سأل عمر النبي صلى الله عليه وسلم عن نذر كان نذره في الجاهلية، اعتكاف: «فأمره النبي صلى الله عليه وسلم بوفائه» وقال: بعضهم، حماد، عن أيوب، عن نافع، عن ابن عمر، ورواه جرير بن حازم، وحماد بن سلمة، عن أيوب، عن نافع، عن ابن عمر، عن النبي صلى الله عليه وسلم", "4320"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "حدثنا عبد الله بن يوسف، أخبرنا مالك، عن يحيى بن سعيد، عن عمر بن كثير بن أفلح، عن أبي محمد، مولى أبي قتادة، عن أبي قتادة، قال: خرجنا مع النبي صلى الله عليه وسلم عام حنين، فلما التقينا كانت للمسلمين جولة، فرأيت رجلا من المشركين قد علا رجلا من المسلمين، فضربته من ورائه على حبل عاتقه بالسيف فقطعت الدرع، وأقبل علي فضمني ضمة وجدت منها ريح الموت، ثم أدركه الموت فأرسلني، فلحقت عمر بن الخطاب فقلت: ما بال الناس؟ قال: أمر الله عز وجل، ثم رجعوا، وجلس النبي صلى الله عليه وسلم ، فقال: «من قتل قتيلا له عليه بينة فله سلبه» فقلت: من يشهد لي، ثم جلست، قال: ثم قال النبي صلى الله عليه وسلم مثله، فقمت، فقلت: من يشهد لي، ثم جلست، قال: ثم قال النبي صلى الله عليه وسلم مثله، فقمت، فقال: «ما لك يا أبا قتادة؟». فأخبرته، فقال رجل: صدق، وسلبه عندي، فأرضه مني، فقال أبو بكر: لاها الله إذا، لا يعمد إلى أسد من أسد الله، يقاتل عن الله ورسوله صلى الله عليه وسلم فيعطيك سلبه، فقال النبي صلى الله عليه وسلم: «صدق، فأعطه». فأعطانيه، فابتعت به مخرفا في بني سلمة، فإنه لأول مال تأثلته في الإسلام،", "4321"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته} [التوبة: 26]- إلى قوله - {غفور رحيم} [البقرة: 173]", "وقال الليث: حدثني يحيى بن سعيد، عن عمر بن كثير بن أفلح، عن أبي محمد، مولى أبي قتادة، أن أبا قتادة، قال: لما كان يوم حنين نظرت إلى رجل من المسلمين يقاتل رجلا من المشركين، وآخر من المشركين يختله من ورائه ليقتله، فأسرعت إلى الذي يختله، فرفع يده ليضربني وأضرب يده فقطعتها، ثم أخذني فضمني ضما شديدا، حتى تخوفت، ثم ترك، فتحلل، ودفعته ثم قتلته، وانهزم المسلمون وانهزمت معهم، فإذا بعمر بن الخطاب في الناس، فقلت له: ما شأن الناس؟ قال: أمر الله، ثم تراجع الناس إلى رسول الله صلى الله عليه وسلم، فقال رسول الله صلى الله عليه وسلم: «من أقام بينة على قتيل قتله فله سلبه» فقمت لألتمس بينة على قتيلي، فلم أر أحدا يشهد لي فجلست، ثم بدا لي فذكرت أمره لرسول الله صلى الله عليه وسلم، فقال رجل من جلسائه: سلاح هذا القتيل الذي يذكر عندي، فأرضه منه، فقال أبو بكر: كلا لا يعطيه أصيبغ من قريش ويدع أسدا من أسد الله، يقاتل عن الله ورسوله صلى الله عليه وسلم، قال: فقام رسول الله صلى الله عليه وسلم فأداه إلي، فاشتريت منه خرافا، فكان أول مال تأثلته في الإسلام", "4322"], ["باب غزوة أوطاس", "حدثنا محمد بن العلاء، حدثنا أبو أسامة، عن بريد بن عبد الله، عن أبي بردة، عن أبي موسى رضي الله عنه، قال: لما فرغ النبي صلى الله عليه وسلم من حنين بعث أبا عامر على جيش إلى أوطاس، فلقي دريد بن الصمة، فقتل دريد وهزم الله أصحابه، قال أبو موسى: وبعثني مع أبي عامر، فرمي أبو عامر في ركبته، رماه جشمي بسهم فأثبته في ركبته، فانتهيت إليه فقلت: يا عم من رماك؟ فأشار إلى أبي موسى فقال: ذاك قاتلي الذي رماني، فقصدت له فلحقته، فلما رآني ولى، فاتبعته وجعلت أقول له : ألا تستحيي، ألا تثبت، فكف، فاختلفنا ضربتين بالسيف فقتلته، ثم قلت لأبي عامر: قتل الله صاحبك، قال: فانزع هذا السهم فنزعته فنزا منه الماء، قال: يا ابن أخي أقرئ النبي صلى الله عليه وسلم السلام، وقل له: استغفر لي. واستخلفني أبو عامر على الناس، فمكث يسيرا ثم مات، فرجعت فدخلت على النبي صلى الله عليه وسلم في بيته على سرير مرمل وعليه فراش، قد أثر رمال السرير بظهره وجنبيه، فأخبرته بخبرنا وخبر أبي عامر، وقال: قل له استغفر لي، فدعا بماء فتوضأ، ثم رفع يديه فقال: «اللهم اغفر لعبيد أبي عامر». ورأيت بياض إبطيه، ثم قال: «اللهم اجعله يوم القيامة فوق كثير من خلقك من الناس». فقلت: ولي فاستغفر، فقال: «اللهم اغفر لعبد الله بن قيس ذنبه، وأدخله يوم القيامة مدخلا كريما» قال أبو بردة: إحداهما لأبي عامر، والأخرى لأبي موسى", "4323"], ["باب غزوة الطائف", "حدثنا الحميدي، سمع سفيان، حدثنا هشام، عن أبيه، عن زينب بنت أبي سلمة، عن أمها أم سلمة رضي الله عنها، دخل علي النبي صلى الله عليه وسلم، وعندي مخنث، فسمعته يقول لعبد الله بن أبي أمية: يا عبد الله، أرأيت إن فتح الله عليكم الطائف غدا، فعليك بابنة غيلان، فإنها تقبل بأربع، وتدبر بثمان، وقال النبي صلى الله عليه وسلم: «لا يدخلن هؤلاء عليكن» قال ابن عيينة: وقال ابن جريج: المخنث: هيت، حدثنا محمود، حدثنا أبو أسامة، عن هشام: بهذا، وزاد وهو محاصر الطائف يومئذ", "4324"], ["باب غزوة الطائف", "حدثنا علي بن عبد الله، حدثنا سفيان، عن عمرو، عن أبي العباس الشاعر الأعمى، عن عبد الله بن عمر، قال: لما حاصر رسول الله صلى الله عليه وسلم الطائف، فلم ينل منهم شيئا، قال: «إنا قافلون إن شاء الله». فثقل عليهم، وقالوا: نذهب ولا نفتحه، وقال مرة: «نقفل». فقال: «اغدوا على القتال». فغدوا فأصابهم جراح، فقال: «إنا قافلون غدا إن شاء الله». فأعجبهم، فضحك النبي صلى الله عليه وسلم، وقال سفيان مرة، فتبسم، قال: قال الحميدي، حدثنا سفيان الخبر كله", "4325"], ["باب غزوة الطائف", "حدثنا محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن عاصم، قال: سمعت أبا عثمان، قال: سمعت سعدا، وهو أول من رمى بسهم في سبيل الله، وأبا بكرة، وكان تسور حصن الطائف في أناس فجاء إلى النبي صلى الله عليه وسلم، فقالا: سمعنا النبي صلى الله عليه وسلم يقول: «من ادعى إلى غير أبيه، وهو يعلم فالجنة عليه حرام» وقال هشام: وأخبرنا معمر، عن عاصم، عن أبي العالية، أو أبي عثمان النهدي، قال: سمعت سعدا وأبا بكرة عن النبي صلى الله عليه وسلم، قال: عاصم قلت: \" لقد شهد عندك رجلان حسبك بهما، قال: أجل، أما أحدهما فأول من رمى بسهم في سبيل الله، وأما الآخر فنزل إلى النبي صلى الله عليه وسلم ثالث ثلاثة وعشرين من الطائف \"", "4326"], ["باب غزوة الطائف", "حدثنا محمد بن العلاء، حدثنا أبو أسامة، عن بريد بن عبد الله، عن أبي بردة، عن أبي موسى رضي الله عنه، قال: كنت عند النبي صلى الله عليه وسلم وهو نازل بالجعرانة بين مكة والمدينة، ومعه بلال فأتى النبي صلى الله عليه وسلم أعرابي فقال: ألا تنجز لي ما وعدتني؟ فقال له: «أبشر» فقال: قد أكثرت علي من أبشر، فأقبل على أبي موسى وبلال كهيئة الغضبان، فقال: «رد البشرى، فاقبلا أنتما» قالا: قبلنا، ثم دعا بقدح فيه ماء، فغسل يديه ووجهه فيه ومج فيه، ثم قال: «اشربا منه، وأفرغا على وجوهكما ونحوركما وأبشرا». فأخذا القدح ففعلا، فنادت أم سلمة من وراء الستر: أن أفضلا لأمكما، فأفضلا لها منه طائفة", "4328"], ["باب غزوة الطائف", "حدثنا يعقوب بن إبراهيم، حدثنا إسماعيل، حدثنا ابن جريج، قال: أخبرني عطاء، أن صفوان بن يعلى بن أمية، أخبره: أن يعلى كان يقول: ليتني أرى رسول الله صلى الله عليه وسلم حين ينزل عليه، قال: فبينا النبي صلى الله عليه وسلم بالجعرانة وعليه ثوب قد أظل به، معه فيه ناس من أصحابه، إذ جاءه أعرابي عليه جبة متضمخ بطيب، فقال: يا رسول الله، كيف ترى في رجل أحرم بعمرة في جبة بعدما تضمخ بالطيب؟ فأشار عمر إلى يعلى بيده: أن تعال، فجاء يعلى فأدخل رأسه، فإذا النبي صلى الله عليه وسلم محمر الوجه، يغط كذلك ساعة، ثم سري عنه، فقال: «أين الذي يسألني عن العمرة آنفا» فالتمس الرجل فأتي به، فقال: «أما الطيب الذي بك فاغسله ثلاث مرات، وأما الجبة فانزعها، ثم اصنع في عمرتك كما تصنع في حجك»", "4329"], ["باب غزوة الطائف", "حدثنا موسى بن إسماعيل، حدثنا وهيب، حدثنا عمرو بن يحيى، عن عباد بن تميم، عن عبد الله بن زيد بن عاصم، قال: لما أفاء الله على رسوله صلى الله عليه وسلم يوم حنين، قسم في الناس في المؤلفة قلوبهم، ولم يعط الأنصار شيئا، فكأنهم وجدوا إذ لم يصبهم ما أصاب الناس، فخطبهم فقال: «يا معشر الأنصار، ألم أجدكم ضلالا فهداكم الله بي، وكنتم متفرقين فألفكم الله بي، وعالة فأغناكم الله بي» كلما قال شيئا قالوا: الله ورسوله أمن، قال: «ما يمنعكم أن تجيبوا رسول الله صلى الله عليه وسلم». قال: كلما قال شيئا، قالوا: الله ورسوله أمن، قال: \" لو شئتم قلتم: جئتنا كذا وكذا، أترضون أن يذهب الناس بالشاة والبعير، وتذهبون بالنبي صلى الله عليه وسلم إلى رحالكم، لولا الهجرة لكنت امرأ من الأنصار، ولو سلك الناس واديا وشعبا لسلكت وادي الأنصار وشعبها، الأنصار شعار والناس دثار، إنكم ستلقون بعدي أثرة، فاصبروا حتى تلقوني على الحوض \"", "4330"], ["باب غزوة الطائف", "حدثني عبد الله بن محمد، حدثنا هشام، أخبرنا معمر، عن الزهري، قال: أخبرني أنس بن مالك رضي الله عنه، قال: قال ناس من الأنصار، حين أفاء الله على رسوله صلى الله عليه وسلم ما أفاء من أموال هوازن، فطفق النبي صلى الله عليه وسلم يعطي رجالا المائة من الإبل، فقالوا: يغفر الله لرسول الله صلى الله عليه وسلم يعطي قريشا ويتركنا، وسيوفنا تقطر من دمائهم، قال أنس: فحدث رسول الله صلى الله عليه وسلم بمقالتهم، فأرسل إلى الأنصار فجمعهم في قبة من أدم، ولم يدع معهم غيرهم، فلما اجتمعوا قام النبي صلى الله عليه وسلم فقال: «ما حديث بلغني عنكم»، فقال فقهاء الأنصار: أما رؤساؤنا يا رسول الله فلم يقولوا شيئا، وأما ناس منا حديثة أسنانهم فقالوا: يغفر الله لرسول الله صلى الله عليه وسلم يعطي قريشا ويتركنا، وسيوفنا تقطر من دمائهم، فقال النبي صلى الله عليه وسلم: «فإني أعطي رجالا حديثي عهد بكفر أتألفهم، أما ترضون أن يذهب الناس بالأموال، وتذهبون بالنبي صلى الله عليه وسلم إلى رحالكم، فوالله لما تنقلبون به خير مما ينقلبون به» قالوا: يا رسول الله قد رضينا، فقال لهم النبي صلى الله عليه وسلم: «ستجدون أثرة شديدة، فاصبروا حتى تلقوا الله ورسوله صلى الله عليه وسلم فإني على الحوض» قال أنس: «فلم يصبروا»", "4331"], ["باب غزوة الطائف", "حدثنا سليمان بن حرب، حدثنا شعبة، عن أبي التياح، عن أنس، قال: لما كان يوم فتح مكة قسم رسول الله صلى الله عليه وسلم غنائم بين قريش، فغضبت الأنصار، قال النبي صلى الله عليه وسلم: «أما ترضون أن يذهب الناس بالدنيا، وتذهبون برسول الله - صلى الله عليه وسلم -» قالوا: بلى، قال: «لو سلك الناس واديا أو شعبا، لسلكت وادي الأنصار أو شعبهم»", "4332"], ["باب غزوة الطائف", "حدثنا علي بن عبد الله، حدثنا أزهر، عن ابن عون، أنبأنا هشام بن زيد بن أنس، عن أنس رضي الله عنه، قال: لما كان يوم حنين، التقى هوازن ومع النبي صلى الله عليه وسلم عشرة آلاف، والطلقاء، فأدبروا، قال: «يا معشر الأنصار». قالوا: لبيك يا رسول الله وسعديك لبيك نحن بين يديك، فنزل النبي صلى الله عليه وسلم فقال: «أنا عبد الله ورسوله». فانهزم المشركون، فأعطى الطلقاء والمهاجرين ولم يعط الأنصار شيئا، فقالوا، فدعاهم فأدخلهم في قبة، فقال: «أما ترضون أن يذهب الناس بالشاة والبعير، وتذهبون برسول الله صلى الله عليه وسلم» فقال النبي صلى الله عليه وسلم: «لو سلك الناس واديا، وسلكت الأنصار شعبا، لاخترت شعب الأنصار»", "4333"], ["باب غزوة الطائف", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، قال: سمعت قتادة، عن أنس بن مالك رضي الله عنه، قال: جمع النبي صلى الله عليه وسلم ناسا من الأنصار فقال: «إن قريشا حديث عهد بجاهلية ومصيبة، وإني أردت أن أجبرهم وأتألفهم، أما ترضون أن يرجع الناس بالدنيا، وترجعون برسول الله صلى الله عليه وسلم إلى بيوتكم» قالوا: بلى، قال: «لو سلك الناس واديا، وسلكت الأنصار شعبا، لسلكت وادي الأنصار، أو شعب الأنصار»", "4334"], ["باب غزوة الطائف", "حدثنا قبيصة، حدثنا سفيان، عن الأعمش، عن أبي وائل، عن عبد الله، قال: لما قسم النبي صلى الله عليه وسلم قسمة حنين، قال: رجل من الأنصار: ما أراد بها وجه الله، فأتيت النبي صلى الله عليه وسلم فأخبرته، فتغير وجهه ثم قال: «رحمة الله على موسى، لقد أوذي بأكثر من هذا فصبر»", "4335"], ["باب غزوة الطائف", "حدثنا قتيبة بن سعيد، حدثنا جرير، عن منصور، عن أبي وائل، عن عبد الله رضي الله عنه، قال: لما كان يوم حنين آثر النبي صلى الله عليه وسلم ناسا، أعطى الأقرع مائة من الإبل، وأعطى عيينة مثل ذلك، وأعطى ناسا، فقال رجل: ما أريد بهذه القسمة وجه الله، فقلت: لأخبرن النبي صلى الله عليه وسلم، قال: «رحم الله موسى، قد أوذي بأكثر من هذا فصبر»", "4336"], ["باب غزوة الطائف", "حدثنا محمد بن بشار، حدثنا معاذ بن معاذ، حدثنا ابن عون، عن هشام بن زيد بن أنس بن مالك، عن أنس بن مالك رضي الله عنه، قال: لما كان يوم حنين، أقبلت هوازن وغطفان وغيرهم بنعمهم وذراريهم، ومع النبي صلى الله عليه وسلم عشرة آلاف، ومن الطلقاء، فأدبروا عنه حتى بقي وحده، فنادى يومئذ نداءين لم يخلط بينهما، التفت عن يمينه فقال: «يا معشر الأنصار». قالوا: لبيك يا رسول الله أبشر نحن معك، ثم التفت عن يساره فقال: «يا معشر الأنصار» قالوا: لبيك يا رسول الله أبشر نحن معك، وهو على بغلة بيضاء فنزل فقال: «أنا عبد الله ورسوله». فانهزم المشركون، فأصاب يومئذ غنائم كثيرة، فقسم في المهاجرين والطلقاء ولم يعط الأنصار شيئا، فقالت الأنصار: إذا كانت شديدة فنحن ندعى، ويعطى الغنيمة غيرنا، فبلغه ذلك فجمعهم في قبة، فقال: «يا معشر الأنصار، ما حديث بلغني عنكم» فسكتوا، فقال: «يا معشر الأنصار، ألا ترضون أن يذهب الناس بالدنيا، وتذهبون برسول الله تحوزونه إلى بيوتكم» قالوا: بلى، فقال النبي صلى الله عليه وسلم: «لو سلك الناس واديا، وسلكت الأنصار شعبا، لأخذت شعب الأنصار» وقال هشام: قلت: يا أبا حمزة وأنت شاهد ذاك قال: «وأين أغيب عنه»", "4337"], ["باب السرية التي قبل نجد", "حدثنا أبو النعمان، حدثنا حماد، حدثنا أيوب، عن نافع، عن ابن عمر رضي الله عنهما، قال: «بعث النبي صلى الله عليه وسلم سرية قبل نجد فكنت فيها، فبلغت سهامنا اثني عشر بعيرا، ونفلنا بعيرا بعيرا، فرجعنا بثلاثة عشر بعيرا»", "4338"], ["باب بعث النبي صلى الله عليه وسلم خالد بن الوليد إلى بني جذيمة", "حدثني محمود، حدثنا عبد الرزاق، أخبرنا معمر، ح وحدثني نعيم، أخبرنا عبد الله، أخبرنا معمر، عن الزهري، عن سالم، عن أبيه، قال: بعث النبي صلى الله عليه وسلم خالد بن الوليد إلى بني جذيمة، فدعاهم إلى الإسلام، فلم يحسنوا أن يقولوا: أسلمنا، فجعلوا يقولون: صبأنا صبأنا، فجعل خالد يقتل منهم ويأسر، ودفع إلى كل رجل منا أسيره، حتى إذا كان يوم أمر خالد أن يقتل كل رجل منا أسيره ، فقلت: والله لا أقتل أسيري، ولا يقتل رجل من أصحابي أسيره، حتى قدمنا على النبي صلى الله عليه وسلم فذكرناه، فرفع النبي صلى الله عليه وسلم يده فقال: «اللهم إني أبرأ إليك مما صنع خالد مرتين»", "4339"], ["باب سرية عبد الله بن حذافة السهمي، وعلقمة بن مجزز المدلجي ويقال: إنها سرية الأنصار", "حدثنا مسدد، حدثنا عبد الواحد، حدثنا الأعمش، قال: حدثني سعد بن عبيدة، عن أبي عبد الرحمن، عن علي رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم سرية فاستعمل رجلا من الأنصار وأمرهم أن يطيعوه، فغضب، فقال: أليس أمركم النبي صلى الله عليه وسلم أن تطيعوني؟ قالوا: بلى، قال: فاجمعوا لي حطبا، فجمعوا، فقال: أوقدوا نارا، فأوقدوها، فقال: ادخلوها، فهموا وجعل بعضهم يمسك بعضا، ويقولون: فررنا إلى النبي صلى الله عليه وسلم من النار، فما زالوا حتى خمدت النار، فسكن غضبه، فبلغ النبي صلى الله عليه وسلم، فقال: «لو دخلوها ما خرجوا منها إلى يوم القيامة، الطاعة في المعروف»", "4340"], ["باب بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثنا موسى، حدثنا أبو عوانة، حدثنا عبد الملك، عن أبي بردة، قال: بعث رسول الله صلى الله عليه وسلم أبا موسى، ومعاذ بن جبل إلى اليمن، قال: وبعث كل واحد منهما على مخلاف، قال: واليمن مخلافان، ثم قال: «يسرا ولا تعسرا، وبشرا ولا تنفرا»، فانطلق كل واحد منهما إلى عمله، وكان كل واحد منهما إذا سار في أرضه كان قريبا من صاحبه أحدث به عهدا، فسلم عليه، فسار معاذ في أرضه قريبا من صاحبه أبي موسى، فجاء يسير على بغلته حتى انتهى إليه، وإذا هو جالس، وقد اجتمع إليه الناس وإذا رجل عنده قد جمعت يداه إلى عنقه، فقال له معاذ: يا عبد الله بن قيس أيم هذا؟ قال: هذا رجل كفر بعد إسلامه، قال: لا أنزل حتى يقتل، قال: إنما جيء به لذلك فانزل، قال: ما أنزل حتى يقتل، فأمر به فقتل، ثم نزل فقال: يا عبد الله، كيف تقرأ القرآن؟ قال: أتفوقه تفوقا، قال: فكيف تقرأ أنت يا معاذ؟ قال: أنام أول الليل، فأقوم وقد قضيت جزئي من النوم، فأقرأ ما كتب الله لي، فأحتسب نومتي كما أحتسب قومتي", "4341"], ["باب بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثني إسحاق، حدثنا خالد، عن الشيباني، عن سعيد بن أبي بردة، عن أبيه، عن أبي موسى الأشعري رضي الله عنه، أن النبي صلى الله عليه وسلم بعثه إلى اليمن، فسأله عن أشربة تصنع بها، فقال: «وما هي؟» قال: البتع والمزر، فقلت لأبي بردة: ما البتع؟ قال: نبيذ العسل، والمزر نبيذ الشعير، فقال: «كل مسكر حرام» رواه جرير، وعبد الواحد، عن الشيباني، عن أبي بردة", "4343"], ["باب بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثنا مسلم، حدثنا شعبة، حدثنا سعيد بن أبي بردة، عن أبيه، قال: بعث النبي صلى الله عليه وسلم جده أبا موسى ومعاذا إلى اليمن، فقال: «يسرا ولا تعسرا، وبشرا ولا تنفرا وتطاوعا»، فقال أبو موسى: يا نبي الله إن أرضنا بها شراب من الشعير المزر، وشراب من العسل البتع، فقال: «كل مسكر حرام». فانطلقا، فقال معاذ لأبي موسى: كيف تقرأ القرآن؟ قال: قائما وقاعدا وعلى راحلتي، وأتفوقه تفوقا، قال: أما أنا فأنام وأقوم، فأحتسب نومتي كما أحتسب قومتي، وضرب فسطاطا، فجعلا يتزاوران، فزار معاذ أبا موسى فإذا رجل موثق، فقال: ما هذا؟ فقال أبو موسى: يهودي أسلم ثم ارتد، فقال معاذ: لأضربن عنقه تابعه العقدي، ووهب، عن شعبة، وقال وكيع، والنضر، وأبو داود، عن شعبة، عن سعيد، عن أبيه، عن جده، عن النبي صلى الله عليه وسلم رواه جرير بن عبد الحميد، عن الشيباني، عن أبي بردة", "4344"], ["باب بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثني عباس بن الوليد هو النرسي حدثنا عبد الواحد، عن أيوب بن عائذ، حدثنا قيس بن مسلم، قال: سمعت طارق بن شهاب، يقول: حدثني أبو موسى الأشعري رضي الله عنه، قال: بعثني رسول الله صلى الله عليه وسلم إلى أرض قومي، فجئت ورسول الله صلى الله عليه وسلم منيخ بالأبطح، فقال: «أحججت يا عبد الله بن قيس» قلت: نعم يا رسول الله، قال: «كيف قلت؟» قال: قلت: لبيك إهلالا كإهلالك، قال: «فهل سقت معك هديا» قلت: لم أسق، قال: «فطف بالبيت، واسع بين الصفا والمروة، ثم حل». ففعلت حتى مشطت لي امرأة من نساء بني قيس، ومكثنا بذلك حتى استخلف عمر", "4346"], ["باب بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثني حبان، أخبرنا عبد الله، عن زكرياء بن إسحاق، عن يحيى بن عبد الله بن صيفي، عن أبي معبد، مولى ابن عباس، عن ابن عباس رضي الله عنهما، قال: قال رسول الله صلى الله عليه وسلم لمعاذ بن جبل حين بعثه إلى اليمن: «إنك ستأتي قوما من أهل الكتاب، فإذا جئتهم فادعهم إلى أن يشهدوا أن لا إله إلا الله، وأن محمدا رسول الله ، فإن هم طاعوا لك بذلك، فأخبرهم أن الله قد فرض عليهم خمس صلوات في كل يوم وليلة، فإن هم طاعوا لك بذلك فأخبرهم أن الله قد فرض عليهم صدقة، تؤخذ من أغنيائهم فترد على فقرائهم، فإن هم طاعوا لك بذلك فإياك وكرائم أموالهم، واتق دعوة المظلوم، فإنه ليس بينه وبين الله حجاب» قال أبو عبد الله: طوعت طاعت، وأطاعت لغة، طعت وطعت وأطعت", "4347"], ["باب بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثنا سليمان بن حرب، حدثنا شعبة، عن حبيب بن أبي ثابت، عن سعيد بن جبير، عن عمرو بن ميمون، أن معاذا رضي الله عنه، لما قدم اليمن، صلى بهم الصبح، فقرأ: \" {واتخذ الله إبراهيم خليلا} [النساء: 125] فقال رجل من القوم: لقد قرت عين أم إبراهيم \" زاد معاذ، عن شعبة، عن حبيب، عن سعيد، عن عمرو أن النبي صلى الله عليه وسلم بعث معاذا إلى اليمن، فقرأ معاذ في صلاة الصبح سورة النساء، فلما قال: {واتخذ الله إبراهيم خليلا} [النساء: 125] قال رجل خلفه: قرت عين أم إبراهيم", "4348"], ["باب بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثني أحمد بن عثمان، حدثنا شريح بن مسلمة، حدثنا إبراهيم بن يوسف بن إسحاق بن أبي إسحاق، حدثني أبي، عن أبي إسحاق، سمعت البراء رضي الله عنه، بعثنا رسول الله صلى الله عليه وسلم مع خالد بن الوليد إلى اليمن، قال: ثم بعث عليا بعد ذلك مكانه فقال: «مر أصحاب خالد، من شاء منهم أن يعقب معك فليعقب، ومن شاء فليقبل» فكنت فيمن عقب معه، قال: فغنمت أواق ذوات عدد", "4349"], ["باب بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثني محمد بن بشار، حدثنا روح بن عبادة، حدثنا علي بن سويد بن منجوف، عن عبد الله بن بريدة، عن أبيه رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم عليا إلى خالد ليقبض الخمس، وكنت أبغض عليا وقد اغتسل، فقلت لخالد: ألا ترى إلى هذا، فلما قدمنا على النبي صلى الله عليه وسلم ذكرت ذلك له، فقال: «يا بريدة أتبغض عليا؟» فقلت: نعم، قال: «لا تبغضه فإن له في الخمس أكثر من ذلك»", "4350"], ["باب بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثنا قتيبة، حدثنا عبد الواحد، عن عمارة بن القعقاع بن شبرمة، حدثنا عبد الرحمن بن أبي نعم، قال: سمعت أبا سعيد الخدري، يقول: بعث علي بن أبي طالب رضي الله عنه إلى رسول الله صلى الله عليه وسلم من اليمن بذهيبة في أديم مقروظ، لم تحصل من ترابها، قال: فقسمها بين أربعة نفر، بين عيينة بن بدر، وأقرع بن حابس، وزيد الخيل، والرابع: إما علقمة وإما عامر بن الطفيل، فقال رجل من أصحابه: كنا نحن أحق بهذا من هؤلاء، قال: فبلغ ذلك النبي صلى الله عليه وسلم فقال: «ألا تأمنوني وأنا أمين من في السماء، يأتيني خبر السماء صباحا ومساء»، قال: فقام رجل غائر العينين، مشرف الوجنتين، ناشز الجبهة، كث اللحية، محلوق الرأس، مشمر الإزار، فقال يا رسول الله اتق الله، قال: «ويلك، أولست أحق أهل الأرض أن يتقي الله» قال: ثم ولى الرجل، قال خالد بن الوليد: يا رسول الله، ألا أضرب عنقه؟ قال: «لا، لعله أن يكون يصلي» فقال خالد: وكم من مصل يقول بلسانه ما ليس في قلبه، قال رسول الله صلى الله عليه وسلم: «إني لم أومر أن أنقب عن قلوب الناس ولا أشق بطونهم» قال: ثم نظر إليه وهو مقف، فقال: «إنه يخرج من ضئضئ هذا قوم يتلون كتاب الله رطبا، لا يجاوز حناجرهم، يمرقون من الدين كما يمرق السهم من الرمية»، وأظنه قال: «لئن أدركتهم لأقتلنهم قتل ثمود»", "4351"], ["باب بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثنا المكي بن إبراهيم، عن ابن جريج، قال: عطاء، قال جابر: «أمر النبي صلى الله عليه وسلم عليا أن يقيم على إحرامه»، زاد محمد بن بكر، عن ابن جريج، قال: عطاء، قال: جابر، فقدم علي بن أبي طالب رضي الله عنه، بسعايته، قال له النبي صلى الله عليه وسلم: «بم أهللت يا علي؟» قال: بما أهل به النبي صلى الله عليه وسلم، قال: «فأهد، وامكث حراما كما أنت»، قال: وأهدى له علي هديا", "4352"], ["باب بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثنا مسدد، حدثنا بشر بن المفضل، عن حميد الطويل، حدثنا بكر، أنه ذكر لابن عمر، أن أنسا حدثهم أن النبي صلى الله عليه وسلم أهل بعمرة وحجة، فقال: أهل النبي صلى الله عليه وسلم بالحج وأهللنا به معه، فلما قدمنا مكة قال: «من لم يكن معه هدي فليجعلها عمرة»، وكان مع النبي صلى الله عليه وسلم هدي، فقدم علينا علي بن أبي طالب من اليمن حاجا، فقال النبي صلى الله عليه وسلم: «بم أهللت؟، فإن معنا أهلك» قال: أهللت بما أهل به النبي صلى الله عليه وسلم قال: «فأمسك فإن معنا هديا»", "4353"], ["باب غزوة ذي الخلصة", "حدثنا مسدد، حدثنا خالد، حدثنا بيان، عن قيس، عن جرير، قال: كان بيت في الجاهلية يقال له ذو الخلصة ، والكعبة اليمانية، والكعبة الشأمية، فقال لي النبي صلى الله عليه وسلم: «ألا تريحني من ذي الخلصة»، فنفرت في مائة وخمسين راكبا فكسرناه، وقتلنا من وجدنا عنده، فأتيت النبي صلى الله عليه وسلم فأخبرته فدعا لنا ولأحمس", "4355"], ["باب غزوة ذي الخلصة", "حدثنا محمد بن المثنى، حدثنا يحيى، حدثنا إسماعيل، حدثنا قيس، قال: قال لي جرير رضي الله عنه: قال لي النبي صلى الله عليه وسلم: «ألا تريحني من ذي الخلصة»، وكان بيتا في خثعم، يسمى الكعبة اليمانية، فانطلقت في خمسين ومائة فارس من أحمس، وكانوا أصحاب خيل، وكنت لا أثبت على الخيل، فضرب في صدري حتى رأيت أثر أصابعه في صدري، وقال: «اللهم ثبته، واجعله هاديا مهديا»، فانطلق إليها فكسرها وحرقها، ثم بعث إلى رسول الله صلى الله عليه وسلم، فقال رسول جرير: والذي بعثك بالحق، ما جئتك حتى تركتها كأنها جمل أجرب، قال: فبارك في خيل أحمس ورجالها خمس مرات", "4356"], ["باب غزوة ذي الخلصة", "حدثنا يوسف بن موسى، أخبرنا أبو أسامة، عن إسماعيل بن أبي خالد، عن قيس، عن جرير، قال: قال لي رسول الله صلى الله عليه وسلم: «ألا تريحني من ذي الخلصة» فقلت: بلى، فانطلقت في خمسين ومائة فارس من أحمس، وكانوا أصحاب خيل، وكنت لا أثبت على الخيل، فذكرت ذلك للنبي صلى الله عليه وسلم، فضرب يده على صدري حتى رأيت أثر يده في صدري، وقال: «اللهم ثبته، واجعله هاديا مهديا» قال: فما وقعت عن فرس بعد، قال: وكان ذو الخلصة بيتا باليمن لخثعم، وبجيلة، فيه نصب تعبد، يقال له الكعبة، قال: فأتاها فحرقها بالنار وكسرها، قال: ولما قدم جرير اليمن، كان بها رجل يستقسم بالأزلام، فقيل له: إن رسول رسول الله صلى الله عليه وسلم ها هنا، فإن قدر عليك ضرب عنقك، قال: فبينما هو يضرب بها إذ وقف عليه جرير، فقال: لتكسرنها ولتشهدن: أن لا إله إلا الله، أو لأضربن عنقك؟ قال: فكسرها وشهد، ثم بعث جرير رجلا من أحمس يكنى أبا أرطاة إلى النبي صلى الله عليه وسلم يبشره بذلك، فلما أتى النبي صلى الله عليه وسلم قال: يا رسول الله والذي بعثك بالحق، ما جئت حتى تركتها كأنها جمل أجرب، قال: فبرك النبي صلى الله عليه وسلم على خيل أحمس ورجالها خمس مرات", "4357"], ["باب غزوة ذات السلاسل", "حدثنا إسحاق، أخبرنا خالد بن عبد الله، عن خالد الحذاء، عن أبي عثمان، أن رسول الله صلى الله عليه وسلم بعث عمرو بن العاص على جيش ذات السلاسل، قال: فأتيته فقلت: أي الناس أحب إليك؟ قال: «عائشة» قلت: من الرجال؟ قال: «أبوها» قلت: ثم من؟ قال: «عمر» فعد رجالا، فسكت مخافة أن يجعلني في آخرهم", "4358"], ["باب ذهاب جرير إلى اليمن", "حدثني عبد الله بن أبي شيبة العبسي، حدثنا ابن إدريس، عن إسماعيل بن أبي خالد، عن قيس، عن جرير، قال: كنت باليمن، فلقيت رجلين من أهل اليمن، ذا كلاع، وذا عمرو، فجعلت أحدثهم عن رسول الله صلى الله عليه وسلم، فقال له: ذو عمرو: لئن كان الذي تذكر من أمر صاحبك، لقد مر على أجله منذ ثلاث، وأقبلا معي حتى إذا كنا في بعض الطريق، رفع لنا ركب من قبل المدينة فسألناهم، فقالوا: \" قبض رسول الله صلى الله عليه وسلم، واستخلف أبو بكر، والناس صالحون، فقالا: أخبر صاحبك أنا قد جئنا ولعلنا سنعود إن شاء الله، ورجعا إلى اليمن، فأخبرت أبا بكر بحديثهم، قال: أفلا جئت بهم، فلما كان بعد قال لي ذو عمرو: يا جرير إن بك علي كرامة، وإني مخبرك خبرا: إنكم معشر العرب، لن تزالوا بخير ما كنتم إذا هلك أمير تأمرتم في آخر، فإذا كانت بالسيف كانوا ملوكا، يغضبون غضب الملوك ويرضون رضا الملوك \"", "4359"], ["باب غزوة سيف البحر، وهم يتلقون عيرا لقريش، وأميرهم أبو عبيدة بن الجراح رضي الله عنه", "حدثنا إسماعيل، قال: حدثني مالك، عن وهب بن كيسان، عن جابر بن عبد الله رضي الله عنهما، أنه قال: «بعث رسول الله صلى الله عليه وسلم بعثا قبل الساحل، وأمر عليهم أبا عبيدة بن الجراح» وهم ثلاث مائة، فخرجنا وكنا ببعض الطريق فني الزاد، فأمر أبو عبيدة بأزواد الجيش، فجمع فكان مزودي تمر، فكان يقوتنا كل يوم قليل قليل حتى فني فلم يكن يصيبنا إلا تمرة تمرة، فقلت: ما تغني عنكم تمرة؟ فقال: لقد وجدنا فقدها حين فنيت، ثم انتهينا إلى البحر فإذا حوت مثل الظرب، فأكل منها القوم ثماني عشرة ليلة، ثم أمر أبو عبيدة بضلعين من أضلاعه فنصبا، ثم أمر براحلة فرحلت ثم مرت تحتهما فلم تصبهما", "4360"], ["باب غزوة سيف البحر، وهم يتلقون عيرا لقريش، وأميرهم أبو عبيدة بن الجراح رضي الله عنه", "حدثنا علي بن عبد الله، حدثنا سفيان، قال: الذي حفظناه من عمرو بن دينار، قال: سمعت جابر بن عبد الله يقول: «بعثنا رسول الله صلى الله عليه وسلم ثلاث مائة راكب أميرنا أبو عبيدة بن الجراح نرصد عير قريش»، فأقمنا بالساحل نصف شهر، فأصابنا جوع شديد حتى أكلنا الخبط، فسمي ذلك الجيش جيش الخبط، فألقى لنا البحر دابة يقال لها العنبر، فأكلنا منه نصف شهر، وادهنا من ودكه حتى ثابت إلينا أجسامنا، فأخذ أبو عبيدة ضلعا من أضلاعه، فنصبه فعمد إلى أطول رجل معه، قال سفيان: «مرة ضلعا من أضلاعه فنصبه وأخذ رجلا وبعيرا فمر تحته» قال جابر: وكان رجل من القوم نحر ثلاث جزائر، ثم نحر ثلاث جزائر ثم نحر ثلاث جزائر، ثم إن أبا عبيدة نهاه وكان عمرو يقول: أخبرنا أبو صالح، أن قيس بن سعد قال لأبيه: كنت في الجيش فجاعوا، قال انحر، قال: نحرت، قال: ثم جاعوا، قال: انحر، قال: نحرت، قال: ثم جاعوا، قال انحر قال: نحرت، ثم جاعوا، قال: انحر، قال: نهيت", "4361"], ["باب غزوة سيف البحر، وهم يتلقون عيرا لقريش، وأميرهم أبو عبيدة بن الجراح رضي الله عنه", "حدثنا مسدد، حدثنا يحيى، عن ابن جريج، قال: أخبرني عمرو، أنه سمع جابرا رضي الله عنه، يقول: غزونا جيش الخبط، وأمر أبو عبيدة فجعنا جوعا شديدا، فألقى البحر حوتا ميتا لم نر مثله، يقال له العنبر، فأكلنا منه نصف شهر، فأخذ أبو عبيدة عظما من عظامه، فمر الراكب تحته فأخبرني أبو الزبير، أنه سمع جابرا، يقول: قال أبو عبيدة: كلوا فلما قدمنا المدينة ذكرنا ذلك للنبي صلى الله عليه وسلم فقال: «كلوا، رزقا أخرجه الله، أطعمونا إن كان معكم» فأتاه بعضهم فأكله", "4362"], ["باب غزوة تبوك وهي غزوة العسرة", "حدثني محمد بن العلاء، حدثنا أبو أسامة، عن بريد بن عبد الله بن أبي بردة، عن أبي بردة، عن أبي موسى رضي الله عنه، قال: أرسلني أصحابي إلى رسول الله صلى الله عليه وسلم أسأله الحملان لهم، إذ هم معه في جيش العسرة، وهي غزوة تبوك فقلت يا نبي الله، إن أصحابي أرسلوني إليك لتحملهم، فقال «والله لا أحملكم على شيء ووافقته، وهو غضبان ولا أشعر» ورجعت حزينا من منع النبي صلى الله عليه وسلم، ومن مخافة أن يكون النبي صلى الله عليه وسلم وجد في نفسه علي، فرجعت إلى أصحابي فأخبرتهم الذي قال النبي صلى الله عليه وسلم، فلم ألبث إلا سويعة، إذ سمعت بلالا ينادي: أي عبد الله بن قيس، فأجبته، فقال: أجب رسول الله صلى الله عليه وسلم يدعوك، فلما أتيته قال: \" خذ هذين القرينين، وهذين القرينين - لستة أبعرة ابتاعهن حينئذ من سعد -، فانطلق بهن إلى أصحابك، فقل: إن الله، أو قال: إن رسول الله صلى الله عليه وسلم يحملكم على هؤلاء فاركبوهن \". فانطلقت إليهم بهن، فقلت: إن النبي صلى الله عليه وسلم يحملكم على هؤلاء، ولكني والله لا أدعكم حتى ينطلق معي بعضكم إلى من سمع مقالة رسول الله صلى الله عليه وسلم ، لا تظنوا أني حدثتكم شيئا لم يقله رسول الله صلى الله عليه وسلم، فقالوا لي: والله إنك عندنا لمصدق، ولنفعلن ما أحببت، فانطلق أبو موسى بنفر منهم، حتى أتوا الذين سمعوا قول رسول الله صلى الله عليه وسلم منعه إياهم، ثم إعطاءهم بعد فحدثوهم بمثل ما حدثهم به أبو موسى", "4415"], ["باب غزوة تبوك وهي غزوة العسرة", "حدثنا مسدد، حدثنا يحيى، عن شعبة، عن الحكم، عن مصعب بن سعد، عن أبيه، أن رسول الله صلى الله عليه وسلم خرج إلى تبوك، واستخلف عليا، فقال: أتخلفني في الصبيان والنساء؟ قال: «ألا ترضى أن تكون مني بمنزلة هارون، من موسى إلا أنه ليس نبي بعدي»، وقال أبو داود: حدثنا شعبة، عن الحكم، سمعت مصعبا", "4416"], ["باب غزوة تبوك وهي غزوة العسرة", "حدثنا عبيد الله بن سعيد، حدثنا محمد بن بكر، أخبرنا ابن جريج، قال: سمعت عطاء، يخبر قال: أخبرني صفوان بن يعلى بن أمية، عن أبيه، قال: غزوت مع النبي صلى الله عليه وسلم العسرة، قال: كان يعلى يقول: تلك الغزوة أوثق أعمالي عندي، قال عطاء: فقال صفوان: قال يعلى: فكان لي أجير، فقاتل إنسانا فعض أحدهما يد الآخر، قال عطاء: فلقد أخبرني صفوان: أيهما عض الآخر فنسيته، قال: فانتزع المعضوض يده من في العاض، فانتزع إحدى ثنيتيه، فأتيا النبي صلى الله عليه وسلم فأهدر ثنيته، قال عطاء: وحسبت أنه قال: قال النبي صلى الله عليه وسلم: «أفيدع يده في فيك تقضمها، كأنها في في فحل يقضمها»", "4417"], ["باب حديث كعب بن مالك، وقول الله عز وجل: {وعلى الثلاثة الذين خلفوا} [التوبة: 118]", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عبد الرحمن بن عبد الله بن كعب بن مالك، أن عبد الله بن كعب بن مالك، وكان، قائد كعب من بنيه، حين عمي، قال: سمعت كعب بن مالك، يحدث حين تخلف عن قصة، تبوك، قال كعب: لم أتخلف عن رسول الله صلى الله عليه وسلم في غزوة غزاها إلا في غزوة تبوك، غير أني كنت تخلفت في غزوة بدر، ولم يعاتب أحدا تخلف عنها، إنما خرج رسول الله صلى الله عليه وسلم يريد عير قريش، حتى جمع الله بينهم وبين عدوهم على غير ميعاد، ولقد شهدت مع رسول الله صلى الله عليه وسلم ليلة العقبة، حين تواثقنا على الإسلام، وما أحب أن لي بها مشهد بدر، وإن كانت بدر، أذكر في الناس منها، كان من خبري: أني لم أكن قط أقوى ولا أيسر حين تخلفت عنه، في تلك الغزاة، والله ما اجتمعت عندي قبله راحلتان قط، حتى جمعتهما في تلك الغزوة، ولم يكن رسول الله صلى الله عليه وسلم يريد غزوة إلا ورى بغيرها، حتى كانت تلك الغزوة، غزاها رسول الله صلى الله عليه وسلم في حر شديد، واستقبل سفرا بعيدا، ومفازا وعدوا كثيرا، فجلى للمسلمين أمرهم ليتأهبوا أهبة غزوهم، فأخبرهم بوجهه الذي يريد، والمسلمون مع رسول الله صلى الله عليه وسلم كثير، ولا يجمعهم كتاب حافظ، يريد الديوان، قال كعب: فما رجل يريد أن يتغيب إلا ظن أن سيخفى له، ما لم ينزل فيه وحي الله، وغزا رسول الله صلى الله عليه وسلم تلك الغزوة حين طابت الثمار والظلال، وتجهز رسول الله صلى الله عليه وسلم والمسلمون معه، فطفقت أغدو لكي أتجهز معهم، فأرجع ولم أقض شيئا، فأقول في نفسي: أنا قادر عليه، فلم يزل يتمادى بي حتى اشتد بالناس الجد، فأصبح رسول الله صلى الله عليه وسلم والمسلمون معه، ولم أقض من جهازي شيئا، فقلت أتجهز بعده بيوم أو يومين، ثم ألحقهم، فغدوت بعد أن فصلوا لأتجهز، فرجعت ولم أقض شيئا، ثم غدوت، ثم رجعت ولم أقض شيئا، فلم يزل بي حتى أسرعوا وتفارط الغزو، وهممت أن أرتحل فأدركهم، وليتني فعلت، فلم يقدر لي ذلك، فكنت إذا خرجت في الناس بعد خروج رسول الله صلى الله عليه وسلم فطفت فيهم، أحزنني أني لا أرى إلا رجلا مغموصا عليه النفاق، أو رجلا ممن عذر الله من الضعفاء، ولم يذكرني رسول الله صلى الله عليه وسلم حتى بلغ تبوك، فقال: وهو جالس في القوم بتبوك: «ما فعل كعب» فقال رجل من بني سلمة: يا رسول الله، حبسه برداه، ونظره في عطفه، فقال معاذ بن جبل: بئس ما قلت، والله يا رسول الله ما علمنا عليه إلا خيرا، فسكت رسول الله صلى الله عليه وسلم، قال كعب بن مالك: فلما بلغني أنه توجه قافلا حضرني همي، وطفقت أتذكر الكذب، وأقول: بماذا أخرج من سخطه غدا، واستعنت على ذلك بكل ذي رأي من أهلي، فلما قيل: إن رسول الله صلى الله عليه وسلم قد أظل قادما زاح عني الباطل، وعرفت أني لن أخرج منه أبدا بشيء فيه كذب، فأجمعت صدقه، وأصبح رسول الله صلى الله عليه وسلم قادما، وكان إذا قدم من سفر، بدأ بالمسجد، فيركع فيه ركعتين، ثم جلس للناس، فلما فعل ذلك جاءه المخلفون، فطفقوا يعتذرون إليه ويحلفون له، وكانوا بضعة وثمانين رجلا، فقبل منهم رسول الله صلى الله عليه وسلم علانيتهم، وبايعهم واستغفر لهم، ووكل سرائرهم إلى الله، فجئته فلما سلمت عليه تبسم تبسم المغضب، ثم قال: «تعال» فجئت أمشي حتى جلست بين يديه ، فقال لي: «ما خلفك، ألم تكن قد ابتعت ظهرك». فقلت: بلى، إني والله لو جلست عند غيرك من أهل الدنيا، لرأيت أن سأخرج من سخطه بعذر، ولقد أعطيت جدلا، ولكني والله، لقد علمت لئن حدثتك اليوم حديث كذب ترضى به عني، ليوشكن الله أن يسخطك علي، ولئن حدثتك حديث صدق، تجد علي فيه، إني لأرجو فيه عفو الله، لا والله، ما كان لي من عذر، والله ما كنت قط أقوى، ولا أيسر مني حين تخلفت عنك، فقال رسول الله صلى الله عليه وسلم: «أما هذا فقد صدق، فقم حتى يقضي الله فيك». فقمت، وثار رجال من بني سلمة فاتبعوني، فقالوا لي: والله ما علمناك كنت أذنبت ذنبا قبل هذا، ولقد عجزت أن لا تكون اعتذرت إلى رسول الله صلى الله عليه وسلم بما اعتذر إليه المتخلفون، قد كان كافيك ذنبك استغفار رسول الله صلى الله عليه وسلم لك، فوالله ما زالوا يؤنبوني حتى أردت أن أرجع فأكذب نفسي، ثم قلت لهم: هل لقي هذا معي أحد؟ قالوا: نعم، رجلان، قالا مثل ما قلت، فقيل لهما مثل ما قيل لك، فقلت: من هما؟ قالوا: مرارة بن الربيع العمري، وهلال بن أمية الواقفي، فذكروا لي رجلين صالحين، قد شهدا بدرا، فيهما أسوة، فمضيت حين ذكروهما لي، ونهى رسول الله صلى الله عليه وسلم المسلمين عن كلامنا أيها الثلاثة من بين من تخلف عنه، فاجتنبنا الناس، وتغيروا لنا حتى تنكرت في نفسي الأرض فما هي التي أعرف، فلبثنا على ذلك خمسين ليلة، فأما صاحباي فاستكانا وقعدا في بيوتهما يبكيان، وأما أنا، فكنت أشب القوم وأجلدهم فكنت أخرج فأشهد الصلاة مع المسلمين، وأطوف في الأسواق ولا يكلمني أحد، وآتي رسول الله صلى الله عليه وسلم فأسلم عليه وهو في مجلسه بعد الصلاة، فأقول في نفسي: هل حرك شفتيه برد السلام علي أم لا؟ ثم أصلي قريبا منه، فأسارقه النظر، فإذا أقبلت على صلاتي أقبل إلي، وإذا التفت نحوه أعرض عني، حتى إذا طال علي ذلك من جفوة الناس، مشيت حتى تسورت جدار حائط أبي قتادة، وهو ابن عمي وأحب الناس إلي، فسلمت عليه، فوالله ما رد علي السلام، فقلت: يا أبا قتادة، أنشدك بالله هل تعلمني أحب الله ورسوله؟ فسكت، فعدت له فنشدته فسكت، فعدت له فنشدته، فقال: الله ورسوله أعلم، ففاضت عيناي، وتوليت حتى تسورت الجدار، قال: فبينا أنا أمشي بسوق المدينة، إذا نبطي من أنباط أهل الشأم، ممن قدم بالطعام يبيعه بالمدينة، يقول: من يدل على كعب بن مالك، فطفق الناس يشيرون له، حتى إذا جاءني دفع إلي كتابا من ملك غسان، فإذا فيه: أما بعد، فإنه قد بلغني أن صاحبك قد جفاك ولم يجعلك الله بدار هوان، ولا مضيعة، فالحق بنا نواسك، فقلت لما قرأتها: وهذا أيضا من البلاء، فتيممت بها التنور فسجرته بها، حتى إذا مضت أربعون ليلة من الخمسين، إذا رسول رسول الله صلى الله عليه وسلم يأتيني، فقال: إن رسول الله صلى الله عليه وسلم يأمرك أن تعتزل امرأتك، فقلت: أطلقها؟ أم ماذا أفعل؟ قال: لا، بل اعتزلها ولا تقربها، وأرسل إلى صاحبي مثل ذلك، فقلت لامرأتي: الحقي بأهلك، فتكوني عندهم، حتى يقضي الله في هذا الأمر، قال كعب: فجاءت امرأة هلال بن أمية رسول الله صلى الله عليه وسلم، فقالت: يا رسول الله: إن هلال بن أمية شيخ ضائع، ليس له خادم، فهل تكره أن أخدمه؟ قال: «لا، ولكن لا يقربك». قالت: إنه والله ما به حركة إلى شيء، والله ما زال يبكي منذ كان من أمره، ما كان إلى يومه هذا، فقال لي بعض أهلي: لو استأذنت رسول الله صلى الله عليه وسلم في امرأتك كما أذن لامرأة هلال بن أمية أن تخدمه؟ فقلت: والله لا أستأذن فيها رسول الله صلى الله عليه وسلم، وما يدريني ما يقول رسول الله صلى الله عليه وسلم إذا استأذنته فيها، وأنا رجل شاب؟ فلبثت بعد ذلك عشر ليال، حتى كملت لنا خمسون ليلة من حين نهى رسول الله صلى الله عليه وسلم عن كلامنا، فلما صليت صلاة الفجر صبح خمسين ليلة، وأنا على ظهر بيت من بيوتنا، فبينا أنا جالس على الحال التي ذكر الله، قد ضاقت علي نفسي، وضاقت علي الأرض بما رحبت، سمعت صوت صارخ، أوفى على جبل سلع بأعلى صوته: يا كعب بن مالك أبشر، قال: فخررت ساجدا، وعرفت أن قد جاء فرج، وآذن رسول الله صلى الله عليه وسلم بتوبة الله علينا حين صلى صلاة الفجر، فذهب الناس يبشروننا، وذهب قبل صاحبي مبشرون، وركض إلي رجل فرسا، وسعى ساع من أسلم، فأوفى على الجبل، وكان الصوت أسرع من الفرس، فلما جاءني الذي سمعت صوته يبشرني، نزعت له ثوبي، فكسوته إياهما، ببشراه والله ما أملك غيرهما يومئذ، واستعرت ثوبين فلبستهما، وانطلقت إلى رسول الله صلى الله عليه وسلم، فيتلقاني الناس فوجا فوجا، يهنوني بالتوبة، يقولون: لتهنك توبة الله عليك، قال كعب: حتى دخلت المسجد، فإذا رسول الله صلى الله عليه وسلم جالس حوله الناس، فقام إلي طلحة بن عبيد الله يهرول حتى صافحني وهناني، والله ما قام إلي رجل من المهاجرين غيره، ولا أنساها لطلحة، قال كعب: فلما سلمت على رسول الله صلى الله عليه وسلم، قال: رسول الله صلى الله عليه وسلم، وهو يبرق وجهه من السرور: «أبشر بخير يوم مر عليك منذ ولدتك أمك»، قال: قلت: أمن عندك يا رسول الله، أم من عند الله؟ قال: «لا، بل من عند الله». وكان رسول الله صلى الله عليه وسلم إذا سر استنار وجهه، حتى كأنه قطعة قمر، وكنا نعرف ذلك منه، فلما جلست بين يديه قلت: يا رسول الله، إن من توبتي أن أنخلع من مالي صدقة إلى الله وإلى رسول الله، قال رسول الله صلى الله عليه وسلم: «أمسك عليك بعض مالك فهو خير لك». قلت: فإني أمسك سهمي الذي بخيبر، فقلت: يا رسول الله، إن الله إنما نجاني بالصدق، وإن من توبتي أن لا أحدث إلا صدقا، ما بقيت. فوالله ما أعلم أحدا من المسلمين أبلاه الله في صدق الحديث منذ ذكرت ذلك لرسول الله صلى الله عليه وسلم، أحسن مما أبلاني، ما تعمدت منذ ذكرت ذلك لرسول الله صلى الله عليه وسلم إلى يومي هذا كذبا، وإني لأرجو أن يحفظني الله فيما بقيت، وأنزل الله على رسوله صلى الله عليه وسلم: {لقد تاب الله على النبي والمهاجرين والأنصار} [التوبة: 117] إلى قوله {وكونوا مع الصادقين} [التوبة: 119] فوالله ما أنعم الله علي من نعمة قط بعد أن هداني للإسلام، أعظم في نفسي من صدقي لرسول الله صلى الله عليه وسلم، أن لا أكون كذبته، فأهلك كما هلك الذين كذبوا، فإن الله قال للذين كذبوا - حين أنزل الوحي - شر ما قال لأحد، فقال تبارك وتعالى: {سيحلفون بالله لكم إذا انقلبتم} [التوبة: 95] إلى قوله {فإن الله لا يرضى عن القوم الفاسقين} [التوبة: 96]، قال كعب: وكنا تخلفنا أيها الثلاثة عن أمر أولئك الذين قبل منهم رسول الله صلى الله عليه وسلم حين حلفوا له، فبايعهم واستغفر لهم، وأرجأ رسول الله صلى الله عليه وسلم أمرنا حتى قضى الله فيه، فبذلك قال الله: {وعلى الثلاثة الذين خلفوا} [التوبة: 118]. وليس الذي ذكر الله مما خلفنا عن الغزو، إنما هو تخليفه إيانا، وإرجاؤه أمرنا، عمن حلف له واعتذر إليه فقبل منه", "4418"], ["باب نزول النبي صلى الله عليه وسلم الحجر", "حدثنا عبد الله بن محمد الجعفي، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن سالم، عن ابن عمر رضي الله عنهما، قال: لما مر النبي صلى الله عليه وسلم بالحجر قال: «لا تدخلوا مساكن الذين ظلموا أنفسهم، أن يصيبكم ما أصابهم، إلا أن تكونوا باكين، ثم قنع رأسه وأسرع السير حتى أجاز الوادي»", "4419"], ["باب نزول النبي صلى الله عليه وسلم الحجر", "حدثنا يحيى بن بكير، حدثنا مالك، عن عبد الله بن دينار، عن ابن عمر رضي الله عنهما، قال: قال رسول الله صلى الله عليه وسلم لأصحاب الحجر: «لا تدخلوا على هؤلاء المعذبين إلا أن تكونوا باكين، أن يصيبكم مثل ما أصابهم»", "4420"], ["باب", "حدثنا يحيى بن بكير، عن الليث، عن عبد العزيز بن أبي سلمة، عن سعد بن إبراهيم، عن نافع بن جبير، عن عروة بن المغيرة، عن أبيه المغيرة بن شعبة، قال: «ذهب النبي صلى الله عليه وسلم لبعض حاجته، فقمت أسكب عليه الماء، - لا أعلمه إلا قال في غزوة تبوك - فغسل وجهه، وذهب يغسل ذراعيه، فضاق عليه كم الجبة، فأخرجهما من تحت جبته فغسلهما، ثم مسح على خفيه»", "4421"], ["باب", "حدثنا خالد بن مخلد، حدثنا سليمان، قال: حدثني عمرو بن يحيى، عن عباس بن سهل بن سعد، عن أبي حميد، قال: أقبلنا مع النبي صلى الله عليه وسلم من غزوة تبوك، حتى إذا أشرفنا على المدينة قال: هذه طابة، وهذا أحد، جبل يحبنا ونحبه \"", "4422"], ["باب", "حدثنا أحمد بن محمد، أخبرنا عبد الله، أخبرنا حميد الطويل، عن أنس بن مالك رضي الله عنه، أن رسول الله صلى الله عليه وسلم رجع من غزوة تبوك فدنا من المدينة، فقال: «إن بالمدينة أقواما، ما سرتم مسيرا، ولا قطعتم واديا إلا كانوا معكم»، قالوا: يا رسول الله، وهم بالمدينة؟ قال: «وهم بالمدينة، حبسهم العذر»", "4423"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا إسحاق، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن صالح، عن ابن شهاب، قال: أخبرني عبيد الله بن عبد الله، أن ابن عباس، أخبره \" أن رسول الله صلى الله عليه وسلم: بعث بكتابه إلى كسرى، مع عبد الله بن حذافة السهمي \" فأمره أن يدفعه إلى عظيم البحرين، فدفعه عظيم البحرين إلى كسرى، فلما قرأه مزقه، فحسبت أن ابن المسيب، قال: «فدعا عليهم رسول الله صلى الله عليه وسلم أن يمزقوا كل ممزق»", "4424"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا عثمان بن الهيثم، حدثنا عوف، عن الحسن، عن أبي بكرة، قال: لقد نفعني الله بكلمة سمعتها من رسول الله صلى الله عليه وسلم أيام الجمل، بعد ما كدت أن ألحق بأصحاب الجمل فأقاتل معهم، قال: لما بلغ رسول الله صلى الله عليه وسلم أن أهل فارس، قد ملكوا عليهم بنت كسرى، قال: «لن يفلح قوم ولوا أمرهم امرأة»", "4425"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا علي بن عبد الله، حدثنا سفيان، قال: سمعت الزهري، عن السائب بن يزيد، يقول: أذكر أني «خرجت مع الغلمان إلى ثنية الوداع، نتلقى رسول الله صلى الله عليه وسلم»، وقال سفيان مرة : «مع الصبيان»", "4426"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا عبد الله بن محمد، حدثنا سفيان، عن الزهري، عن السائب، أذكر أني «خرجت مع الصبيان نتلقى النبي صلى الله عليه وسلم، إلى ثنية الوداع مقدمه من غزوة تبوك»", "4427"], ["باب وفد بني تميم", "حدثنا أبو نعيم، حدثنا سفيان، عن أبي صخرة، عن صفوان بن محرز المازني، عن عمران بن حصين رضي الله عنهما، قال: أتى نفر من بني تميم النبي صلى الله عليه وسلم، فقال: «اقبلوا البشرى يا بني تميم». قالوا: يا رسول الله قد بشرتنا فأعطنا، فرئي ذلك في وجهه، فجاء نفر من اليمن، فقال: «اقبلوا البشرى إذ لم يقبلها بنو تميم» قالوا: قد قبلنا يا رسول الله", "4365"], ["باب : قال ابن إسحاق: غزوة عيينة بن حصن بن حذيفة بن بدر بني العنبر من بني تميم بعثه النبي صلى الله عليه وسلم إليهم فأغار وأصاب منهم ناسا، وسبى منهم نساء", "حدثني زهير بن حرب، حدثنا جرير، عن عمارة بن القعقاع، عن أبي زرعة، عن أبي هريرة رضي الله عنه، قال: لا أزال أحب بني تميم بعد ثلاث سمعته من رسول الله صلى الله عليه وسلم يقولها فيهم: «هم أشد أمتي على الدجال» وكانت فيهم سبية عند عائشة، فقال: «أعتقيها، فإنها من ولد إسماعيل»، وجاءت صدقاتهم، فقال: \" هذه صدقات قوم، أو: قومي \"", "4366"], ["باب : قال ابن إسحاق: غزوة عيينة بن حصن بن حذيفة بن بدر بني العنبر من بني تميم بعثه النبي صلى الله عليه وسلم إليهم فأغار وأصاب منهم ناسا، وسبى منهم نساء", "حدثني إبراهيم بن موسى، حدثنا هشام بن يوسف، أن ابن جريج، أخبرهم عن ابن أبي مليكة، أن عبد الله بن الزبير، أخبرهم: «أنه قدم ركب من بني تميم على النبي صلى الله عليه وسلم»، فقال أبو بكر: أمر القعقاع بن معبد بن زرارة، قال عمر: بل أمر الأقرع بن حابس، قال أبو بكر: ما أردت إلا خلافي، قال عمر: ما أردت خلافك، فتماريا حتى ارتفعت أصواتهما، فنزل في ذلك: {يا أيها الذين آمنوا لا تقدموا} [الحجرات: 1] حتى انقضت", "4367"], ["باب قصة وفد طيئ وحديث عدي بن حاتم", "حدثنا موسى بن إسماعيل، حدثنا أبو عوانة، حدثنا عبد الملك، عن عمرو بن حريث، عن عدي بن حاتم، قال: أتينا عمر في وفد، فجعل يدعو رجلا رجلا ويسميهم، فقلت: أما تعرفني يا أمير المؤمنين؟ قال: بلى «أسلمت إذ كفروا، وأقبلت إذ أدبروا، ووفيت إذ غدروا، وعرفت إذ أنكروا». فقال عدي: فلا أبالي إذا", "4394"], ["باب وفد عبد القيس", "حدثني إسحاق، أخبرنا أبو عامر العقدي، حدثنا قرة، عن أبي جمرة، قلت لابن عباس رضي الله عنهما: إن لي جرة ينتبذ لي نبيذ، فأشربه حلوا في جر، إن أكثرت منه، فجالست القوم فأطلت الجلوس، خشيت أن أفتضح، فقال: قدم وفد عبد القيس على رسول الله صلى الله عليه وسلم، فقال: «مرحبا بالقوم، غير خزايا ولا الندامى»، فقالوا: يا رسول الله إن بيننا وبينك المشركين من مضر، وإنا لا نصل إليك إلا في أشهر الحرم، حدثنا بجمل من الأمر: إن عملنا به دخلنا الجنة، وندعو به من وراءنا. قال: «آمركم بأربع ، وأنهاكم عن أربع الإيمان بالله، هل تدرون ما الإيمان بالله؟ شهادة أن لا إله إلا الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وأن تعطوا من المغانم الخمس، وأنهاكم عن أربع، ما انتبذ في الدباء، والنقير، والحنتم، والمزفت»", "4368"], ["باب وفد عبد القيس", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن أبي جمرة، قال: سمعت ابن عباس، يقول: قدم وفد عبد القيس على النبي صلى الله عليه وسلم، فقالوا: يا رسول الله، إنا هذا الحي من ربيعة، وقد حالت بيننا وبينك كفار مضر، فلسنا نخلص إليك إلا في شهر حرام، فمرنا بأشياء نأخذ بها، وندعو إليها من وراءنا، قال: «آمركم بأربع، وأنهاكم عن أربع، الإيمان بالله شهادة أن لا إله إلا الله، - وعقد واحدة - وإقام الصلاة، وإيتاء الزكاة، وأن تؤدوا لله خمس ما غنمتم، وأنهاكم عن الدباء، والنقير، والحنتم، والمزفت»", "4369"], ["باب وفد عبد القيس", "حدثنا يحيى بن سليمان، حدثني ابن وهب، أخبرني عمرو، وقال: بكر بن مضر، عن عمرو بن الحارث، عن بكير، أن كريبا، مولى ابن عباس، حدثه أن ابن عباس، وعبد الرحمن بن أزهر، والمسور بن مخرمة أرسلوا إلى عائشة رضي الله عنها، فقالوا: اقرأ عليها السلام منا جميعا، وسلها عن الركعتين بعد العصر، وإنا أخبرنا أنك تصليها، وقد بلغنا أن النبي صلى الله عليه وسلم نهى عنها، قال ابن عباس: «وكنت أضرب مع عمر الناس عنهما»، قال كريب: فدخلت عليها وبلغتها ما أرسلوني، فقالت: سل أم سلمة، فأخبرتهم فردوني إلى أم سلمة بمثل ما أرسلوني إلى عائشة، فقالت أم سلمة: \" سمعت النبي صلى الله عليه وسلم ينهى عنهما، وإنه صلى العصر، ثم دخل علي وعندي نسوة من بني حرام من الأنصار، فصلاهما، فأرسلت إليه الخادم، فقلت: قومي إلى جنبه، فقولي: تقول أم سلمة: يا رسول الله ألم أسمعك تنهى عن هاتين الركعتين؟ فأراك تصليهما، فإن أشار بيده فاستأخري، ففعلت الجارية، فأشار بيده فاستأخرت عنه، فلما انصرف قال: «يا بنت أبي أمية، سألت عن الركعتين بعد العصر، إنه أتاني أناس من عبد القيس بالإسلام من قومهم، فشغلوني عن الركعتين اللتين بعد الظهر، فهما هاتان»", "4370"], ["باب وفد عبد القيس", "حدثني عبد الله بن محمد الجعفي، حدثنا أبو عامر عبد الملك، حدثنا إبراهيم هو ابن طهمان، عن أبي جمرة، عن ابن عباس رضي الله عنهما، قال: \" أول جمعة جمعت، بعد جمعة جمعت في مسجد رسول الله صلى الله عليه وسلم، في مسجد عبد القيس بجواثى، يعني قرية من البحرين", "4371"], ["باب وفد بني حنيفة، وحديث ثمامة بن أثال", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني سعيد بن أبي سعيد، أنه سمع أبا هريرة رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم خيلا قبل نجد، فجاءت برجل من بني حنيفة يقال له ثمامة بن أثال، فربطوه بسارية من سواري المسجد، فخرج إليه النبي صلى الله عليه وسلم، فقال: «ما عندك يا ثمامة؟» فقال: عندي خير يا محمد، إن تقتلني تقتل ذا دم، وإن تنعم تنعم على شاكر، وإن كنت تريد المال فسل منه ما شئت، فترك حتى كان الغد، ثم قال له: «ما عندك يا ثمامة؟» قال: ما قلت لك: إن تنعم تنعم على شاكر، فتركه حتى كان بعد الغد، فقال: «ما عندك يا ثمامة؟» فقال: عندي ما قلت لك، فقال: «أطلقوا ثمامة» فانطلق إلى نجل قريب من المسجد، فاغتسل ثم دخل المسجد، فقال: أشهد أن لا إله إلا الله، وأشهد أن محمدا رسول الله، يا محمد، والله ما كان على الأرض وجه أبغض إلي من وجهك، فقد أصبح وجهك أحب الوجوه إلي، والله ما كان من دين أبغض إلي من دينك، فأصبح دينك أحب الدين إلي، والله ما كان من بلد أبغض إلي من بلدك، فأصبح بلدك أحب البلاد إلي، وإن خيلك أخذتني وأنا أريد العمرة، فماذا ترى؟ فبشره رسول الله صلى الله عليه وسلم وأمره أن يعتمر، فلما قدم مكة قال له قائل: صبوت، قال: لا، ولكن أسلمت مع محمد رسول الله صلى الله عليه وسلم، ولا والله، لا يأتيكم من اليمامة حبة حنطة، حتى يأذن فيها النبي صلى الله عليه وسلم", "4372"], ["باب وفد بني حنيفة، وحديث ثمامة بن أثال", "حدثنا أبو اليمان، أخبرنا شعيب، عن عبد الله بن أبي حسين، حدثنا نافع بن جبير، عن ابن عباس رضي الله عنهما، قال: قدم مسيلمة الكذاب على عهد رسول الله صلى الله عليه وسلم، فجعل يقول: إن جعل لي محمد الأمر من بعده تبعته، وقدمها في بشر كثير من قومه، فأقبل إليه رسول الله صلى الله عليه وسلم ومعه ثابت بن قيس بن شماس، وفي يد رسول الله صلى الله عليه وسلم قطعة جريد، حتى وقف على مسيلمة في أصحابه، فقال: «لو سألتني هذه القطعة ما أعطيتكها، ولن تعدو أمر الله فيك، ولئن أدبرت ليعقرنك الله، وإني لأراك الذي أريت فيه، ما رأيت، وهذا ثابت يجيبك عني» ثم انصرف عنه، قال ابن عباس: فسألت عن قول رسول الله صلى الله عليه وسلم: «إنك أرى الذي أريت فيه ما أريت»، فأخبرني أبو هريرة: أن رسول الله صلى الله عليه وسلم قال: \" بينا أنا نائم، رأيت في يدي سوارين من ذهب، فأهمني شأنهما، فأوحي إلي في المنام: أن انفخهما، فنفختهما فطارا، فأولتهما كذابين يخرجان بعدي \" أحدهما العنسي، والآخر مسيلمة", "4373"], ["باب وفد بني حنيفة، وحديث ثمامة بن أثال", "حدثنا إسحاق بن نصر، حدثنا عبد الرزاق، عن معمر، عن همام، أنه سمع أبا هريرة رضي الله عنه، يقول: قال رسول الله صلى الله عليه وسلم: «بينا أنا نائم أتيت بخزائن الأرض، فوضع في كفي سواران من ذهب، فكبرا علي، فأوحى الله إلي أن انفخهما، فنفختهما فذهبا، فأولتهما الكذابين اللذين أنا بينهما، صاحب صنعاء، وصاحب اليمامة»", "4374"], ["باب وفد بني حنيفة، وحديث ثمامة بن أثال", "حدثنا الصلت بن محمد، قال: سمعت مهدي بن ميمون، قال: سمعت أبا رجاء العطاردي، يقول: \" كنا نعبد الحجر، فإذا وجدنا حجرا هو أخير منه ألقيناه، وأخذنا الآخر، فإذا لم نجد حجرا جمعنا جثوة من تراب، ثم جئنا بالشاة فحلبناه عليه، ثم طفنا به، فإذا دخل شهر رجب قلنا: منصل الأسنة، فلا ندع رمحا فيه حديدة، ولا سهما فيه حديدة، إلا نزعناه وألقيناه شهر رجب \"،", "4376"], ["باب وفد بني حنيفة، وحديث ثمامة بن أثال", "وسمعت أبا رجاء يقول: «كنت يوم بعث النبي صلى الله عليه وسلم غلاما أرعى الإبل على أهلي، فلما سمعنا بخروجه فررنا إلى النار، إلى مسيلمة الكذاب»", "4377"], ["باب قصة الأسود العنسي", "حدثنا سعيد بن محمد الجرمي، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن صالح، عن ابن عبيدة بن نشيط، وكان في موضع آخر اسمه عبد الله، أن عبيد الله بن عبد الله بن عتبة، قال: بلغنا أن مسيلمة الكذاب قدم المدينة فنزل في دار بنت الحارث، وكان تحته بنت الحارث بن كريز، وهي أم عبد الله بن عامر، فأتاه رسول الله صلى الله عليه وسلم ومعه ثابت بن قيس بن شماس، وهو الذي يقال له: خطيب رسول الله صلى الله عليه وسلم، وفي يد رسول الله صلى الله عليه وسلم قضيب، فوقف عليه فكلمه، فقال له مسيلمة: إن شئت خليت بيننا وبين الأمر، ثم جعلته لنا بعدك، فقال النبي صلى الله عليه وسلم: «لو سألتني هذا القضيب ما أعطيتكه، وإني لأراك الذي أريت فيه ما أريت، وهذا ثابت بن قيس، وسيجيبك عني». فانصرف النبي صلى الله عليه وسلم،", "4378"], ["باب قصة الأسود العنسي", "قال: عبيد الله بن عبد الله: سألت عبد الله بن عباس عن رؤيا رسول الله صلى الله عليه وسلم التي ذكر، فقال ابن عباس: ذكر لي أن رسول الله صلى الله عليه وسلم، قال: «بينا أنا نائم أريت أنه وضع في يدي سواران من ذهب ففظعتهما وكرهتهما، فأذن لي فنفختهما فطارا، فأولتهما كذابين يخرجان» فقال عبيد الله: أحدهما العنسي، الذي قتله فيروز باليمن، والآخر مسيلمة الكذاب \"", "4379"], ["باب قصة أهل نجران", "حدثني عباس بن الحسين، حدثنا يحيى بن آدم، عن إسرائيل، عن أبي إسحاق، عن صلة بن زفر، عن حذيفة، قال: جاء العاقب والسيد، صاحبا نجران، إلى رسول الله صلى الله عليه وسلم يريدان أن يلاعناه، قال: فقال أحدهما لصاحبه: لا تفعل، فوالله لئن كان نبيا فلاعنا لا نفلح نحن، ولا عقبنا من بعدنا، قالا: إنا نعطيك ما سألتنا، وابعث معنا رجلا أمينا، ولا تبعث معنا إلا أمينا. فقال «لأبعثن معكم رجلا أمينا حق أمين»، فاستشرف له أصحاب رسول الله صلى الله عليه وسلم فقال: «قم يا أبا عبيدة بن الجراح» فلما قام، قال رسول الله صلى الله عليه وسلم: «هذا أمين هذه الأمة»", "4380"], ["باب قصة أهل نجران", "حدثنا محمد بن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، قال: سمعت أبا إسحاق، عن صلة بن زفر، عن حذيفة رضي الله عنه، قال: جاء أهل نجران إلى النبي صلى الله عليه وسلم فقالوا: ابعث لنا رجلا أمينا فقال: «لأبعثن إليكم رجلا أمينا حق أمين، فاستشرف له الناس فبعث أبا عبيدة بن الجراح»", "4381"], ["باب قصة أهل نجران", "حدثنا أبو الوليد، حدثنا شعبة، عن خالد، عن أبي قلابة، عن أنس، عن النبي صلى الله عليه وسلم، قال: «لكل أمة أمين، وأمين هذه الأمة أبو عبيدة بن الجراح»", "4382"], ["باب قصة عمان والبحرين", "حدثنا قتيبة بن سعيد، حدثنا سفيان، سمع ابن المنكدر، جابر بن عبد الله رضي الله عنهما، يقول: قال لي رسول الله صلى الله عليه وسلم: «لو قد جاء مال البحرين لقد أعطيتك هكذا، وهكذا». ثلاثا، فلم يقدم مال البحرين حتى قبض رسول الله صلى الله عليه وسلم، فلما قدم على أبي بكر أمر مناديا فنادى: من كان له عند النبي صلى الله عليه وسلم دين أو عدة فليأتني، قال: جابر: فجئت أبا بكر فأخبرته: أن النبي صلى الله عليه وسلم قال: «لو جاء مال البحرين أعطيتك هكذا وهكذا» ثلاثا، قال: فأعطاني، قال جابر: فلقيت أبا بكر بعد ذلك فسألته فلم يعطني، ثم أتيته، فلم يعطني، ثم أتيته الثالثة فلم يعطني، فقلت له: قد أتيتك فلم تعطني، ثم أتيتك فلم تعطني، ثم أتيتك فلم تعطني، فإما أن تعطيني وإما أن تبخل عني، فقال: أقلت تبخل عني؟ وأي داء أدوأ من البخل، قالها ثلاثا، ما منعتك من مرة إلا وأنا أريد أن أعطيك، وعن عمرو، عن محمد بن علي سمعت جابر بن عبد الله يقول: \" جئته، فقال لي أبو بكر: عدها، فعددتها، فوجدتها خمس مائة، فقال: خذ مثلها مرتين \"", "4383"], ["باب قدوم الأشعريين وأهل اليمن", "حدثني عبد الله بن محمد، وإسحاق بن نصر، قالا: حدثنا يحيى بن آدم، حدثنا ابن أبي زائدة، عن أبيه، عن أبي إسحاق، عن الأسود بن يزيد، عن أبي موسى رضي الله عنه، قال: «قدمت أنا وأخي من اليمن، فمكثنا حينا، ما نرى ابن مسعود وأمه، إلا من أهل البيت، من كثرة دخولهم ولزومهم له»", "4384"], ["باب قدوم الأشعريين وأهل اليمن", "حدثنا أبو نعيم، حدثنا عبد السلام، عن أيوب، عن أبي قلابة، عن زهدم، قال: لما قدم أبو موسى أكرم هذا الحي من جرم، وإنا لجلوس عنده، وهو يتغدى دجاجا، وفي القوم رجل جالس، فدعاه إلى الغداء، فقال: إني رأيته يأكل شيئا فقذرته، فقال: هلم، فإني رأيت النبي صلى الله عليه وسلم يأكله، فقال: إني حلفت لا آكله، فقال: هلم أخبرك عن يمينك، إنا أتينا النبي صلى الله عليه وسلم نفر من الأشعريين فاستحملناه، فأبى أن يحملنا، فاستحملناه فحلف أن لا يحملنا، ثم لم يلبث النبي صلى الله عليه وسلم أن أتي بنهب إبل، فأمر لنا بخمس ذود، فلما قبضناها قلنا: تغفلنا النبي صلى الله عليه وسلم يمينه، لا نفلح بعدها أبدا، فأتيته، فقلت: يا رسول الله، إنك حلفت أن لا تحملنا وقد حملتنا؟ قال: «أجل، ولكن لا أحلف على يمين، فأرى غيرها خيرا منها، إلا أتيت الذي هو خير منها»", "4385"], ["باب قدوم الأشعريين وأهل اليمن", "حدثني عمرو بن علي، حدثنا أبو عاصم، حدثنا سفيان، حدثنا أبو صخرة جامع بن شداد، حدثنا صفوان بن محرز المازني، حدثنا عمران بن حصين، قال: جاءت بنو تميم إلى رسول الله صلى الله عليه وسلم، فقال: «أبشروا يا بني تميم» قالوا: أما إذ بشرتنا فأعطنا، فتغير وجه رسول الله صلى الله عليه وسلم فجاء ناس من أهل اليمن فقال: النبي صلى الله عليه وسلم «اقبلوا البشرى إذ لم يقبلها بنو تميم» قالوا: قد قبلنا يا رسول الله", "4386"], ["باب قدوم الأشعريين وأهل اليمن", "حدثني عبد الله بن محمد الجعفي، حدثنا وهب بن جرير، حدثنا شعبة، عن إسماعيل بن أبي خالد، عن قيس بن أبي حازم، عن أبي مسعود، أن النبي صلى الله عليه وسلم، قال: «الإيمان ها هنا وأشار بيده إلى اليمن، والجفاء وغلظ القلوب في الفدادين عند أصول أذناب الإبل، من حيث يطلع قرنا الشيطان ربيعة، ومضر»", "4387"], ["باب قدوم الأشعريين وأهل اليمن", "حدثنا محمد بن بشار، حدثنا ابن أبي عدي، عن شعبة، عن سليمان، عن ذكوان، عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم: «أتاكم أهل اليمن، هم أرق أفئدة وألين قلوبا، الإيمان يمان والحكمة يمانية، والفخر والخيلاء في أصحاب الإبل، والسكينة والوقار في أهل الغنم»، وقال: غندر، عن شعبة، عن سليمان، سمعت ذكوان، عن أبي هريرة ، عن النبي صلى الله عليه وسلم", "4388"], ["باب قدوم الأشعريين وأهل اليمن", "حدثنا إسماعيل، قال: حدثني أخي، عن سليمان، عن ثور بن زيد، عن أبي الغيث، عن أبي هريرة، أن النبي صلى الله عليه وسلم، قال: «الإيمان يمان، والفتنة ها هنا، ها هنا يطلع قرن الشيطان»", "4389"], ["باب قدوم الأشعريين وأهل اليمن", "حدثنا أبو اليمان، أخبرنا شعيب، حدثنا أبو الزناد، عن الأعرج، عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم، قال: «أتاكم أهل اليمن، أضعف قلوبا، وأرق أفئدة، الفقه يمان والحكمة يمانية»", "4390"], ["باب قدوم الأشعريين وأهل اليمن", "حدثنا عبدان، عن أبي حمزة، عن الأعمش، عن إبراهيم، عن علقمة، قال: \" كنا جلوسا مع ابن مسعود، فجاء خباب، فقال: يا أبا عبد الرحمن، أيستطيع هؤلاء الشباب أن يقرءوا كما تقرأ؟ قال: أما إنك لو شئت أمرت بعضهم يقرأ عليك؟ قال: أجل، قال: اقرأ يا علقمة، فقال زيد بن حدير، أخو زياد بن حدير: أتأمر علقمة أن يقرأ وليس بأقرئنا؟ قال: أما إنك إن شئت أخبرتك بما قال النبي صلى الله عليه وسلم في قومك وقومه؟ فقرأت خمسين آية من سورة مريم، فقال عبد الله: كيف ترى؟ قال: قد أحسن، قال عبد الله: ما أقرأ شيئا إلا وهو يقرؤه، ثم التفت إلى خباب وعليه خاتم من ذهب، فقال: ألم يأن لهذا الخاتم أن يلقى، قال: أما إنك لن تراه علي بعد اليوم، فألقاه \" رواه غندر، عن شعبة", "4391"], ["باب قصة دوس، والطفيل بن عمرو الدوسي", "حدثنا أبو نعيم، حدثنا سفيان، عن ابن ذكوان، عن عبد الرحمن الأعرج، عن أبي هريرة رضي الله عنه، قال: جاء الطفيل بن عمرو إلى النبي صلى الله عليه وسلم فقال: إن دوسا قد هلكت عصت وأبت فادع الله عليهم، فقال: «اللهم اهد دوسا وأت بهم»", "4392"], ["باب قصة دوس، والطفيل بن عمرو الدوسي", "حدثني محمد بن العلاء، حدثنا أبو أسامة، حدثنا إسماعيل، عن قيس، عن أبي هريرة، قال: لما قدمت على النبي صلى الله عليه وسلم قلت في الطريق: [البحر الطويل] يا ليلة من طولها وعنائها ... على أنها من دارة الكفر نجت وأبق غلام لي في الطريق، فلما قدمت على النبي صلى الله عليه وسلم فبايعته، فبينا أنا عنده إذ طلع الغلام، فقال لي النبي صلى الله عليه وسلم: «يا أبا هريرة هذا غلامك» فقلت: هو لوجه الله، فأعتقته", "4393"], ["باب حج أبي بكر بالناس في سنة تسع", "حدثنا سليمان بن داود أبو الربيع، حدثنا فليح، عن الزهري، عن حميد بن عبد الرحمن، عن أبي هريرة، أن أبا بكر الصديق رضي الله عنه بعثه، في الحجة التي أمره النبي صلى الله عليه وسلم عليها قبل حجة الوداع، يوم النحر في رهط يؤذن في الناس «لا يحج بعد العام مشرك، ولا يطوف بالبيت عريان»", "4363"], ["باب حج أبي بكر بالناس في سنة تسع", "حدثني عبد الله بن رجاء ، حدثنا إسرائيل، عن أبي إسحاق، عن البراء رضي الله عنه، قال: \" آخر سورة نزلت كاملة براءة، وآخر سورة نزلت خاتمة سورة النساء {يستفتونك قل الله يفتيكم في الكلالة} [النساء: 176]", "4364"], ["باب حجة الوداع", "حدثنا إسماعيل بن عبد الله، حدثنا مالك، عن ابن شهاب، عن عروة بن الزبير، عن عائشة رضي الله عنها، قالت: خرجنا مع رسول الله صلى الله عليه وسلم في حجة الوداع، فأهللنا بعمرة، ثم قال رسول الله صلى الله عليه وسلم: «من كان معه هدي فليهلل بالحج مع العمرة، ثم لا يحل حتى يحل منهما جميعا»، فقدمت معه مكة وأنا حائض، ولم أطف بالبيت، ولا بين الصفا والمروة، فشكوت إلى رسول الله صلى الله عليه وسلم، فقال: «انقضي رأسك وامتشطي، وأهلي بالحج، ودعي العمرة» ففعلت، فلما قضينا الحج أرسلني رسول الله صلى الله عليه وسلم مع عبد الرحمن بن أبي بكر الصديق إلى التنعيم فاعتمرت، فقال: «هذه مكان عمرتك»، قالت: فطاف الذين أهلوا بالعمرة بالبيت وبين الصفا والمروة، ثم حلوا، ثم طافوا طوافا آخر، بعد أن رجعوا من منى، وأما الذين جمعوا الحج والعمرة فإنما طافوا طوافا واحدا", "4395"], ["باب حجة الوداع", "حدثني عمرو بن علي، حدثنا يحيى بن سعيد، حدثنا ابن جريج، قال: حدثني عطاء، عن ابن عباس: إذا طاف بالبيت فقد حل، فقلت: من أين؟ قال: هذا ابن عباس قال: من قول الله تعالى: {ثم محلها إلى البيت العتيق} [الحج: 33] ومن «أمر النبي صلى الله عليه وسلم أصحابه أن يحلوا في حجة الوداع»، قلت: إنما كان ذلك بعد المعرف قال: كان ابن عباس: «يراه قبل وبعد»", "4396"], ["باب حجة الوداع", "حدثني بيان، حدثنا النضر، أخبرنا شعبة، عن قيس، قال: سمعت طارقا، عن أبي موسى الأشعري رضي الله عنه، قال: قدمت على النبي صلى الله عليه وسلم بالبطحاء، فقال: «أحججت» قلت: نعم، قال: «كيف أهللت» قلت: لبيك بإهلال كإهلال رسول الله صلى الله عليه وسلم، قال: «طف بالبيت، وبالصفا، والمروة، ثم حل» فطفت بالبيت وبالصفا والمروة، وأتيت امرأة من قيس، ففلت رأسي", "4397"], ["باب حجة الوداع", "حدثني إبراهيم بن المنذر، أخبرنا أنس بن عياض، حدثنا موسى بن عقبة، عن نافع، أن ابن عمر، أخبره أن حفصة رضي الله عنها زوج النبي صلى الله عليه وسلم، أخبرته: أن النبي صلى الله عليه وسلم أمر أزواجه أن يحللن عام حجة الوداع، فقالت حفصة: فما يمنعك؟ فقال: «لبدت رأسي، وقلدت هديي، فلست أحل حتى أنحر هديي»", "4398"], ["باب حجة الوداع", "حدثنا أبو اليمان، قال: حدثني شعيب، عن الزهري، وقال محمد بن يوسف: حدثنا الأوزاعي، قال: أخبرني ابن شهاب، عن سليمان بن يسار، عن ابن عباس رضي الله عنهما، أن امرأة من خثعم استفتت رسول الله صلى الله عليه وسلم في حجة الوداع، والفضل بن عباس رديف رسول الله صلى الله عليه وسلم، فقالت: يا رسول الله، إن فريضة الله على عباده أدركت أبي شيخا كبيرا، لا يستطيع أن يستوي على الراحلة، فهل يقضي أن أحج عنه؟ قال: «نعم»", "4399"], ["باب حجة الوداع", "حدثني محمد، حدثنا سريج بن النعمان، حدثنا فليح، عن نافع، عن ابن عمر رضي الله عنهما، قال: أقبل النبي صلى الله عليه وسلم عام الفتح، وهو مردف أسامة على القصواء، ومعه بلال، وعثمان بن طلحة، حتى أناخ عند البيت، ثم قال لعثمان: «ائتنا بالمفتاح». فجاءه بالمفتاح ففتح له الباب، فدخل النبي صلى الله عليه وسلم وأسامة، وبلال، وعثمان، ثم أغلقوا عليهم الباب، فمكث نهارا طويلا، ثم خرج وابتدر الناس الدخول، فسبقتهم فوجدت بلالا قائما من وراء الباب، فقلت له: أين صلى رسول الله صلى الله عليه وسلم؟ فقال: صلى بين ذينك العمودين المقدمين، وكان البيت على ستة أعمدة سطرين، صلى بين العمودين من السطر المقدم، وجعل باب البيت خلف ظهره، واستقبل بوجهه الذي يستقبلك حين تلج البيت بينه وبين الجدار، قال: «ونسيت أن أسأله كم صلى وعند المكان الذي صلى فيه مرمرة حمراء»", "4400"], ["باب حجة الوداع", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، حدثني عروة بن الزبير، وأبو سلمة بن عبد الرحمن، أن عائشة زوج النبي صلى الله عليه وسلم، أخبرتهما أن صفية بنت حيي زوج النبي صلى الله عليه وسلم، حاضت في حجة الوداع، فقال النبي صلى الله عليه وسلم: «أحابستنا هي» فقلت: إنها قد أفاضت يا رسول الله وطافت بالبيت، فقال النبي صلى الله عليه وسلم: «فلتنفر»", "4401"], ["باب حجة الوداع", "حدثنا يحيى بن سليمان، قال: أخبرني ابن وهب، قال: حدثني عمر بن محمد، أن أباه، حدثه عن ابن عمر رضي الله عنهما، قال: كنا نتحدث بحجة الوداع، والنبي صلى الله عليه وسلم بين أظهرنا، ولا ندري ما حجة الوداع، فحمد الله وأثنى عليه، ثم ذكر المسيح الدجال فأطنب في ذكره، وقال: \" ما بعث الله من نبي إلا أنذر أمته، أنذره نوح والنبيون من بعده، وإنه يخرج فيكم، فما خفي عليكم من شأنه فليس يخفى عليكم: أن ربكم ليس على ما يخفى عليكم ثلاثا، إن ربكم ليس بأعور، وإنه أعور عين اليمنى، كأن عينه عنبة طافية،", "4402"], ["باب حجة الوداع", "ألا إن الله حرم عليكم دماءكم وأموالكم، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا، ألا هل بلغت \" قالوا: نعم، قال: «اللهم اشهد - ثلاثا - ويلكم، أو ويحكم، انظروا، لا ترجعوا بعدي كفارا، يضرب بعضكم رقاب بعض»", "4403"], ["باب حجة الوداع", "حدثنا عمرو بن خالد، حدثنا زهير، حدثنا أبو إسحاق، قال: حدثني زيد بن أرقم، أن النبي صلى الله عليه وسلم «غزا تسع عشرة غزوة، وأنه حج بعد ما هاجر حجة واحدة، لم يحج بعدها حجة الوداع»، قال أبو إسحاق: «وبمكة أخرى»", "4404"], ["باب حجة الوداع", "حدثنا حفص بن عمر، حدثنا شعبة، عن علي بن مدرك، عن أبي زرعة بن عمرو بن جرير، عن جرير، أن النبي صلى الله عليه وسلم، قال: في حجة الوداع لجرير: «استنصت الناس» فقال: «لا ترجعوا بعدي كفارا، يضرب بعضكم رقاب بعض»", "4405"], ["باب حجة الوداع", "حدثني محمد بن المثنى، حدثنا عبد الوهاب، حدثنا أيوب، عن محمد، عن ابن أبي بكرة، عن أبي بكرة، عن النبي صلى الله عليه وسلم، قال: \" الزمان قد استدار كهيئة يوم خلق السموات والأرض، السنة اثنا عشر شهرا منها أربعة حرم: ثلاثة متواليات: ذو القعدة، وذو الحجة، والمحرم، ورجب مضر، الذي بين جمادى وشعبان، أي شهر هذا \"، قلنا: الله ورسوله أعلم، فسكت حتى ظننا أنه سيسميه بغير اسمه، قال: «أليس ذو الحجة»، قلنا: بلى، قال: «فأي بلد هذا». قلنا: الله ورسوله أعلم، فسكت حتى ظننا أنه سيسميه بغير اسمه، قال: «أليس البلدة». قلنا: بلى، قال: «فأي يوم هذا». قلنا: الله ورسوله أعلم، فسكت حتى ظننا أنه سيسميه بغير اسمه، قال: «أليس يوم النحر». قلنا: بلى، قال: \" فإن دماءكم وأموالكم، - قال محمد: وأحسبه قال - وأعراضكم عليكم حرام، كحرمة يومكم هذا في بلدكم هذا، في شهركم هذا، وستلقون ربكم، فسيسألكم عن أعمالكم، ألا فلا ترجعوا بعدي ضلالا، يضرب بعضكم رقاب بعض، ألا ليبلغ الشاهد الغائب، فلعل بعض من يبلغه أن يكون أوعى له من بعض من سمعه \". فكان محمد إذا ذكره يقول: صدق محمد صلى الله عليه وسلم، ثم قال: «ألا هل بلغت» مرتين", "4406"], ["باب حجة الوداع", "حدثنا محمد بن يوسف، حدثنا سفيان الثوري، عن قيس بن مسلم، عن طارق بن شهاب، أن أناسا، من اليهود قالوا: لو نزلت هذه الآية فينا لاتخذنا ذلك اليوم عيدا، فقال عمر: أية آية؟ فقالوا: {اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينا} [المائدة: 3]. فقال عمر: «إني لأعلم أي مكان أنزلت أنزلت، ورسول الله صلى الله عليه وسلم واقف بعرفة»", "4407"], ["باب حجة الوداع", "حدثنا عبد الله بن مسلمة، عن مالك، عن أبي الأسود محمد بن عبد الرحمن بن نوفل، عن عروة، عن عائشة رضي الله عنها، قالت : خرجنا مع رسول الله صلى الله عليه وسلم، فمنا من أهل بعمرة، ومنا من أهل بحجة، ومنا من أهل بحج وعمرة، «وأهل رسول الله صلى الله عليه وسلم بالحج»، فأما من أهل بالحج أو جمع الحج والعمرة، فلم يحلوا حتى يوم النحر حدثنا عبد الله بن يوسف، أخبرنا مالك، وقال: مع رسول الله صلى الله عليه وسلم في حجة الوداع، حدثنا إسماعيل، حدثنا مالك مثله", "4408"], ["باب حجة الوداع", "حدثنا أحمد بن يونس، حدثنا إبراهيم هو ابن سعد، حدثنا ابن شهاب، عن عامر بن سعد، عن أبيه، قال: عادني النبي صلى الله عليه وسلم في حجة الوداع، من وجع أشفيت منه على الموت، فقلت: يا رسول الله، بلغ بي من الوجع ما ترى، وأنا ذو مال، ولا يرثني إلا ابنة لي واحدة، أفأتصدق بثلثي مالي؟ قال: «لا» قلت: أفأتصدق بشطره؟ قال: «لا». قلت: فالثلث؟، قال: «والثلث كثير، إنك أن تذر ورثتك أغنياء، خير من أن تذرهم عالة يتكففون الناس، ولست تنفق نفقة تبتغي بها وجه الله إلا أجرت بها، حتى اللقمة تجعلها في في امرأتك» قلت: يا رسول الله أأخلف بعد أصحابي؟ قال: «إنك لن تخلف، فتعمل عملا تبتغي به وجه الله، إلا ازددت به درجة ورفعة، ولعلك تخلف حتى ينتفع بك أقوام ويضر بك آخرون، اللهم أمض لأصحابي هجرتهم، ولا تردهم على أعقابهم، لكن البائس سعد ابن خولة» رثى له رسول الله صلى الله عليه وسلم أن توفي بمكة", "4409"], ["باب حجة الوداع", "حدثني إبراهيم بن المنذر، حدثنا أبو ضمرة، حدثنا موسى بن عقبة، عن نافع، أن ابن عمر رضي الله عنهما، أخبرهم: «أن رسول الله صلى الله عليه وسلم حلق رأسه في حجة الوداع»", "4410"], ["باب حجة الوداع", "حدثنا عبيد الله بن سعيد، حدثنا محمد بن بكر، حدثنا ابن جريج، أخبرني موسى بن عقبة، عن نافع، أخبره ابن عمر، «أن النبي صلى الله عليه وسلم حلق في حجة الوداع، وأناس من أصحابه وقصر بعضهم»", "4411"], ["باب حجة الوداع", "حدثنا يحيى بن قزعة، حدثنا مالك، عن ابن شهاب، وقال الليث: حدثني يونس، عن ابن شهاب، حدثني عبيد الله بن عبد الله، أن عبد الله بن عباس رضي الله عنهما، أخبره «أنه أقبل يسير على حمار، ورسول الله صلى الله عليه وسلم قائم بمنى في حجة الوداع يصلي بالناس، فسار الحمار بين يدي بعض الصف، ثم نزل عنه فصف مع الناس»", "4412"], ["باب حجة الوداع", "حدثنا مسدد، حدثنا يحيى، عن هشام، قال: حدثني أبي قال: سئل أسامة وأنا شاهد عن سير النبي صلى الله عليه وسلم في حجته؟ فقال: «العنق فإذا وجد فجوة نص»", "4413"], ["باب حجة الوداع", "حدثنا عبد الله بن مسلمة، عن مالك، عن يحيى بن سعيد، عن عدي بن ثابت، عن عبد الله بن يزيد الخطمي، أن أبا أيوب، أخبره: أنه «صلى مع رسول الله صلى الله عليه وسلم في حجة الوداع المغرب والعشاء جميعا»", "4414"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد رضي الله عنهما، في مرضه الذي توفي فيه", "حدثنا أبو عاصم الضحاك بن مخلد، عن الفضيل بن سليمان، حدثنا موسى بن عقبة، عن سالم، عن أبيه، استعمل النبي صلى الله عليه وسلم أسامة، فقالوا فيه: فقال النبي صلى الله عليه وسلم: «قد بلغني أنكم قلتم في أسامة وإنه أحب الناس إلي»", "4468"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد رضي الله عنهما، في مرضه الذي توفي فيه", "حدثنا إسماعيل، حدثنا مالك، عن عبد الله بن دينار، عن عبد الله بن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم بعث بعثا، وأمر عليهم أسامة بن زيد، فطعن الناس في إمارته، فقام رسول الله صلى الله عليه وسلم فقال: «إن تطعنوا في إمارته فقد كنتم تطعنون في إمارة أبيه من قبل، وايم الله إن كان لخليقا للإمارة، وإن كان لمن أحب الناس إلي، وإن هذا لمن أحب الناس إلي بعده»", "4469"], ["باب", "حدثنا أصبغ، قال: أخبرني ابن وهب، قال: أخبرني عمرو بن الحارث، عن ابن أبي حبيب، عن أبي الخير، عن الصنابحي، أنه قال له: متى هاجرت؟ قال: خرجنا من اليمن مهاجرين، فقدمنا الجحفة، فأقبل راكب، فقلت له: الخبر؟ فقال: «دفنا النبي صلى الله عليه وسلم منذ خمس»، قلت: هل سمعت في ليلة القدر شيئا؟ قال: نعم، أخبرني بلال مؤذن النبي صلى الله عليه وسلم: «أنه في السبع في العشر الأواخر»", "4470"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "وقال يونس عن الزهري، قال عروة: قالت عائشة رضي الله عنها: كان النبي صلى الله عليه وسلم يقول في مرضه الذي مات فيه: «يا عائشة ما أزال أجد ألم الطعام الذي أكلت بخيبر، فهذا أوان وجدت انقطاع أبهري من ذلك السم»", "4428"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عبيد الله بن عبد الله، عن عبد الله بن عباس رضي الله عنهما، عن أم الفضل بنت الحارث، قالت: سمعت النبي صلى الله عليه وسلم: «يقرأ في المغرب بالمرسلات عرفا، ثم ما صلى لنا بعدها حتى قبضه الله»", "4429"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا محمد بن عرعرة، حدثنا شعبة، عن أبي بشر، عن سعيد بن جبير، عن ابن عباس، قال: كان عمر بن الخطاب رضي الله عنه، يدني ابن عباس، فقال له عبد الرحمن بن عوف: إن لنا أبناء مثله، فقال: إنه من حيث تعلم، فسأل عمر، ابن عباس عن هذه الآية: {إذا جاء نصر الله والفتح} [النصر: 1]. فقال: «أجل رسول الله صلى الله عليه وسلم أعلمه إياه» فقال: ما أعلم منها إلا ما تعلم", "4430"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا قتيبة، حدثنا سفيان، عن سليمان الأحول، عن سعيد بن جبير، قال: قال ابن عباس: يوم الخميس، وما يوم الخميس؟ اشتد برسول الله صلى الله عليه وسلم وجعه، فقال: «ائتوني أكتب لكم كتابا لن تضلوا بعده أبدا»، فتنازعوا ولا ينبغي عند نبي تنازع، فقالوا: ما شأنه، أهجر استفهموه؟ فذهبوا يردون عليه، فقال: «دعوني، فالذي أنا فيه خير مما تدعوني إليه» وأوصاهم بثلاث، قال: «أخرجوا المشركين من جزيرة العرب، وأجيزوا الوفد بنحو ما كنت أجيزهم» وسكت عن الثالثة أو قال فنسيتها \"", "4431"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا علي بن عبد الله، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن عبيد الله بن عبد الله بن عتبة، عن ابن عباس رضي الله عنهما، قال: لما حضر رسول الله صلى الله عليه وسلم وفي البيت رجال، فقال النبي صلى الله عليه وسلم: «هلموا أكتب لكم كتابا لا تضلوا بعده»، فقال بعضهم: إن رسول الله صلى الله عليه وسلم قد غلبه الوجع، وعندكم القرآن حسبنا، كتاب الله فاختلف أهل البيت واختصموا، فمنهم من يقول قربوا يكتب لكم كتابا لا تضلوا بعده، ومنهم من يقول غير ذلك، فلما أكثروا اللغو والاختلاف، قال رسول الله صلى الله عليه وسلم: «قوموا» قال عبيد الله، فكان يقول ابن عباس: «إن الرزية كل الرزية، ما حال بين رسول الله صلى الله عليه وسلم وبين أن يكتب لهم ذلك الكتاب، لاختلافهم ولغطهم»", "4432"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا يسرة بن صفوان بن جميل اللخمي، حدثنا إبراهيم بن سعد، عن أبيه، عن عروة، عن عائشة رضي الله عنها، قالت: دعا النبي صلى الله عليه وسلم فاطمة عليها السلام في شكواه الذي قبض فيه، فسارها بشيء فبكت، ثم دعاها فسارها بشيء فضحكت، فسألنا عن ذلك فقالت: «سارني النبي صلى الله عليه وسلم أنه يقبض في وجعه الذي توفي فيه فبكيت، ثم سارني فأخبرني أني أول أهله يتبعه فضحكت»", "4433"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن سعد، عن عروة، عن عائشة، قالت: كنت أسمع: \" أنه لا يموت نبي حتى يخير بين الدنيا والآخرة، فسمعت النبي صلى الله عليه وسلم يقول في مرضه الذي مات فيه، وأخذته بحة، يقول: {مع الذين أنعم الله عليهم} [النساء: 69] الآية فظننت أنه خير \"", "4435"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا مسلم، حدثنا شعبة، عن سعد، عن عروة، عن عائشة، قالت: لما مرض النبي صلى الله عليه وسلم المرض الذي مات فيه جعل يقول: «في الرفيق الأعلى»", "4436"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني عروة بن الزبير، إن عائشة، قالت: كان رسول الله صلى الله عليه وسلم، وهو صحيح يقول: \" إنه لم يقبض نبي قط حتى يرى مقعده من الجنة، ثم يحيا أو يخير، فلما اشتكى وحضره القبض ورأسه على فخذ عائشة غشي عليه، فلما أفاق شخص بصره نحو سقف البيت، ثم قال: «اللهم في الرفيق الأعلى» فقلت: إذا لا يجاورنا، فعرفت أنه حديثه الذي كان يحدثنا وهو صحيح", "4437"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا محمد، حدثنا عفان، عن صخر بن جويرية، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة، دخل عبد الرحمن بن أبي بكر على النبي صلى الله عليه وسلم وأنا مسندته إلى صدري، ومع عبد الرحمن سواك رطب يستن به، فأبده رسول الله صلى الله عليه وسلم بصره، فأخذت السواك فقصمته، ونفضته وطيبته، ثم دفعته إلى النبي صلى الله عليه وسلم فاستن به، فما رأيت رسول الله صلى الله عليه وسلم استن استنانا قط أحسن منه، فما عدا أن فرغ رسول الله صلى الله عليه وسلم رفع يده أو إصبعه ثم قال «في الرفيق الأعلى». ثلاثا، ثم قضى، وكانت تقول: مات بين حاقنتي وذاقنتي", "4438"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني حبان، أخبرنا عبد الله، أخبرنا يونس، عن ابن شهاب، قال: أخبرني عروة، أن عائشة، رضي الله عنها، أخبرته: «أن رسول الله صلى الله عليه وسلم كان إذا اشتكى نفث على نفسه بالمعوذات، ومسح عنه بيده، فلما اشتكى وجعه الذي توفي فيه، طفقت أنفث على نفسه بالمعوذات التي كان ينفث، وأمسح بيد النبي صلى الله عليه وسلم عنه»", "4439"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا معلى بن أسد، حدثنا عبد العزيز بن مختار، حدثنا هشام بن عروة، عن عباد بن عبد الله بن الزبير، أن عائشة، أخبرته أنها سمعت النبي صلى الله عليه وسلم وأصغت إليه قبل أن يموت، وهو مسند إلي ظهره يقول: «اللهم اغفر لي وارحمني، وألحقني بالرفيق»", "4440"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا الصلت بن محمد، حدثنا أبو عوانة، عن هلال الوزان، عن عروة بن الزبير، عن عائشة رضي الله عنها، قالت: قال النبي صلى الله عليه وسلم في مرضه الذي لم يقم منه: «لعن الله اليهود اتخذوا قبور أنبيائهم مساجد»، قالت عائشة: «لولا ذلك لأبرز قبره خشي أن يتخذ مسجدا»", "4441"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا سعيد بن عفير، قال: حدثني الليث، قال: حدثني عقيل، عن ابن شهاب، قال: أخبرني عبيد الله بن عبد الله بن عتبة بن مسعود، أن عائشة زوج النبي صلى الله عليه وسلم، قالت: لما ثقل رسول الله صلى الله عليه وسلم واشتد به وجعه، استأذن أزواجه أن يمرض في بيتي، فأذن له، فخرج وهو بين الرجلين تخط رجلاه في الأرض، بين عباس بن عبد المطلب وبين رجل آخر، قال عبيد الله فأخبرت عبد الله بالذي قالت عائشة: فقال لي عبد الله بن عباس: «هل تدري من الرجل الآخر الذي لم تسم عائشة؟» قال: قلت: لا، قال ابن عباس: «هو علي بن أبي طالب» وكانت عائشة زوج النبي صلى الله عليه وسلم تحدث أن رسول الله صلى الله عليه وسلم لما دخل بيتي واشتد به وجعه قال: «هريقوا علي من سبع قرب، لم تحلل، أوكيتهن لعلي أعهد إلى الناس» فأجلسناه في مخضب لحفصة زوج النبي صلى الله عليه وسلم، ثم طفقنا نصب عليه من تلك القرب، حتى طفق يشير إلينا بيده، «أن قد فعلتن» قالت: ثم خرج إلى الناس فصلى بهم وخطبهم", "4442"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "وأخبرني عبيد الله بن عبد الله بن عتبة، أن عائشة، وعبد الله بن عباس رضي الله عنهم، قالا: لما نزل برسول الله صلى الله عليه وسلم ، طفق يطرح خميصة له على وجهه، فإذا اغتم كشفها عن وجهه، وهو كذلك يقول: «لعنة الله على اليهود، والنصارى اتخذوا قبور أنبيائهم مساجد» يحذر ما صنعوا \"", "4443"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "أخبرني عبيد الله، أن عائشة، قالت: \" لقد راجعت رسول الله صلى الله عليه وسلم في ذلك، وما حملني على كثرة مراجعته إلا أنه لم يقع في قلبي: أن يحب الناس بعده رجلا، قام مقامه أبدا، ولا كنت أرى أنه لن يقوم أحد مقامه إلا تشاءم الناس به، فأردت أن يعدل ذلك رسول الله صلى الله عليه وسلم عن أبي بكر \" رواه ابن عمر، وأبو موسى، وابن عباس رضي الله عنهم، عن النبي صلى الله عليه وسلم", "4445"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني ابن الهاد، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة، قالت: «مات النبي صلى الله عليه وسلم وإنه لبين حاقنتي وذاقنتي، فلا أكره شدة الموت لأحد أبدا، بعد النبي صلى الله عليه وسلم»", "4446"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني إسحاق، أخبرنا بشر بن شعيب بن أبي حمزة، قال: حدثني أبي، عن الزهري، قال: أخبرني عبد الله بن كعب بن مالك الأنصاري، وكان كعب بن مالك أحد الثلاثة الذين تيب عليهم أن عبد الله بن عباس، أخبره أن علي بن أبي طالب رضي الله عنه، خرج من عند رسول الله صلى الله عليه وسلم في وجعه الذي توفي فيه، فقال الناس: يا أبا حسن، \" كيف أصبح رسول الله صلى الله عليه وسلم؟، فقال: أصبح بحمد الله بارئا \"، فأخذ بيده عباس بن عبد المطلب فقال له: أنت والله بعد ثلاث عبد العصا، وإني والله لأرى رسول الله صلى الله عليه وسلم سوف يتوفى من وجعه هذا، إني لأعرف وجوه بني عبد المطلب عند الموت، اذهب بنا إلى رسول الله صلى الله عليه وسلم فلنسأله فيمن هذا الأمر، إن كان فينا علمنا ذلك، وإن كان في غيرنا علمناه، فأوصى بنا، فقال علي: إنا والله لئن سألناها رسول الله صلى الله عليه وسلم فمنعناها لا يعطيناها الناس بعده، وإني والله لا أسألها رسول الله صلى الله عليه وسلم", "4447"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا سعيد بن عفير، قال: حدثني الليث، قال: حدثني عقيل، عن ابن شهاب، قال: حدثني أنس بن مالك رضي الله عنه، أن المسلمين بينا هم في صلاة الفجر من يوم الاثنين، وأبو بكر يصلي لهم، لم يفجأهم إلا رسول الله صلى الله عليه وسلم قد «كشف ستر حجرة عائشة، فنظر إليهم وهم في صفوف الصلاة، ثم تبسم يضحك»، فنكص أبو بكر على عقبيه ليصل الصف، وظن أن رسول الله صلى الله عليه وسلم يريد أن يخرج إلى الصلاة، فقال أنس : وهم المسلمون أن يفتتنوا في صلاتهم، فرحا برسول الله صلى الله عليه وسلم، فأشار إليهم بيده رسول الله صلى الله عليه وسلم: «أن أتموا صلاتكم ثم دخل الحجرة وأرخى الستر»", "4448"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني محمد بن عبيد، حدثنا عيسى بن يونس، عن عمر بن سعيد، قال: أخبرني ابن أبي مليكة، أن أبا عمرو ذكوان، مولى عائشة، أخبره أن عائشة كانت تقول: إن من نعم الله علي: أن رسول الله صلى الله عليه وسلم توفي في بيتي، وفي يومي، وبين سحري ونحري، وأن الله جمع بين ريقي وريقه عند موته: دخل علي عبد الرحمن، وبيده السواك، وأنا مسندة رسول الله صلى الله عليه وسلم، فرأيته ينظر إليه، وعرفت أنه يحب السواك، فقلت: آخذه لك؟ فأشار برأسه: «أن نعم» فتناولته، فاشتد عليه، وقلت: ألينه لك؟ فأشار برأسه: «أن نعم» فلينته، فأمره، وبين يديه ركوة أو علبة - يشك عمر - فيها ماء، فجعل يدخل يديه في الماء فيمسح بهما وجهه، يقول: «لا إله إلا الله، إن للموت سكرات» ثم نصب يده، فجعل يقول: «في الرفيق الأعلى» حتى قبض ومالت يده", "4449"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا إسماعيل، قال: حدثني سليمان بن بلال، حدثنا هشام بن عروة، أخبرني أبي، عن عائشة رضي الله عنها، أن رسول الله صلى الله عليه وسلم كان يسأل في مرضه الذي مات فيه، يقول: «أين أنا غدا، أين أنا غدا» يريد يوم عائشة، فأذن له أزواجه يكون حيث شاء، فكان في بيت عائشة حتى مات عندها، قالت عائشة: فمات في اليوم الذي كان يدور علي فيه، في بيتي، فقبضه الله وإن رأسه لبين نحري وسحري، وخالط ريقه ريقي، ثم قالت: دخل عبد الرحمن بن أبي بكر ومعه سواك يستن به، فنظر إليه رسول الله صلى الله عليه وسلم، فقلت له: أعطني هذا السواك يا عبد الرحمن، فأعطانيه، فقضمته، ثم مضغته، فأعطيته رسول الله صلى الله عليه وسلم فاستن به، وهو مستند إلى صدري", "4450"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن أيوب، عن ابن أبي مليكة، عن عائشة رضي الله عنها، قالت: توفي النبي صلى الله عليه وسلم في بيتي، وفي يومي، وبين سحري ونحري، وكانت إحدانا تعوذه بدعاء إذا مرض، فذهبت أعوذه، فرفع رأسه إلى السماء، وقال: «في الرفيق الأعلى، في الرفيق الأعلى»، ومر عبد الرحمن بن أبي بكر وفي يده جريدة رطبة، فنظر إليه النبي صلى الله عليه وسلم، فظننت أن له بها حاجة، فأخذتها، فمضغت رأسها، ونفضتها، فدفعتها إليه، فاستن بها كأحسن ما كان مستنا، ثم ناولنيها، فسقطت يده، أو: سقطت من يده، فجمع الله بين ريقي وريقه في آخر يوم من الدنيا، وأول يوم من الآخرة", "4451"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، قال: أخبرني أبو سلمة، أن عائشة ، أخبرته: أن أبا بكر رضي الله عنه أقبل على فرس من مسكنه بالسنح، حتى نزل فدخل المسجد، فلم يكلم الناس حتى دخل على عائشة، فتيمم رسول الله صلى الله عليه وسلم وهو مغشى بثوب حبرة، فكشف عن وجهه ثم أكب عليه فقبله وبكى، ثم قال: «بأبي أنت وأمي، والله لا يجمع الله عليك موتتين أما الموتة التي كتبت عليك، فقد متها»", "4452"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "قال الزهري: وحدثني أبو سلمة، عن عبد الله بن عباس، أن أبا بكر خرج وعمر بن الخطاب يكلم الناس فقال: اجلس يا عمر، فأبى عمر أن يجلس، فأقبل الناس إليه، وتركوا عمر، فقال أبو بكر: \" أما بعد فمن كان منكم يعبد محمدا صلى الله عليه وسلم، فإن محمدا قد مات، ومن كان منكم يعبد الله فإن الله حي لا يموت، قال الله: {وما محمد إلا رسول قد خلت من قبله الرسل} [آل عمران: 144] إلى قوله {الشاكرين} [آل عمران: 144]، وقال: والله لكأن الناس لم يعلموا أن الله أنزل هذه الآية حتى تلاها أبو بكر، فتلقاها منه الناس كلهم، فما أسمع بشرا من الناس إلا يتلوها \" فأخبرني سعيد بن المسيب، أن عمر قال: «والله ما هو إلا أن سمعت أبا بكر تلاها فعقرت، حتى ما تقلني رجلاي، وحتى أهويت إلى الأرض حين سمعته تلاها، علمت أن النبي صلى الله عليه وسلم قد مات»", "4454"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني عبد الله بن أبي شيبة، حدثنا يحيى بن سعيد، عن سفيان، عن موسى بن أبي عائشة، عن عبيد الله بن عبد الله بن عتبة، عن عائشة، وابن عباس أن أبا بكر رضي الله عنه «قبل النبي صلى الله عليه وسلم بعد موته»", "4455"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا علي، حدثنا يحيى، وزاد قالت عائشة: لددناه في مرضه فجعل يشير إلينا: «أن لا تلدوني» فقلنا كراهية المريض للدواء، فلما أفاق قال: «ألم أنهكم أن تلدوني»، قلنا كراهية المريض للدواء، فقال: «لا يبقى أحد في البيت إلا لد وأنا أنظر إلا العباس فإنه لم يشهدكم» رواه ابن أبي الزناد، عن هشام، عن أبيه، عن عائشة، عن النبي صلى الله عليه وسلم", "4458"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا عبد الله بن محمد، أخبرنا أزهر، أخبرنا ابن عون، عن إبراهيم، عن الأسود، قال: ذكر عند عائشة أن النبي صلى الله عليه وسلم أوصى إلى علي، فقالت: من قاله؟ «لقد رأيت النبي صلى الله عليه وسلم وإني لمسندته إلى صدري فدعا بالطست، فانخنث فمات فما شعرت فكيف أوصى إلى علي؟»", "4459"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا أبو نعيم، حدثنا مالك بن مغول، عن طلحة، قال: سألت عبد الله بن أبي أوفى رضي الله عنهما أوصى النبي صلى الله عليه وسلم؟ فقال: لا، فقلت: كيف كتب على الناس الوصية، أو أمروا بها؟ قال: «أوصى بكتاب الله»", "4460"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا قتيبة، حدثنا أبو الأحوص، عن أبي إسحاق، عن عمرو بن الحارث، قال: «ما ترك رسول الله صلى الله عليه وسلم دينارا، ولا درهما، ولا عبدا، ولا أمة، إلا بغلته البيضاء التي كان يركبها، وسلاحه، وأرضا جعلها لابن السبيل صدقة»", "4461"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا سليمان بن حرب، حدثنا حماد، عن ثابت، عن أنس، قال: لما ثقل النبي صلى الله عليه وسلم جعل يتغشاه، فقالت فاطمة عليها السلام: وا كرب أباه، فقال لها: «ليس على أبيك كرب بعد اليوم»، فلما مات قالت: يا أبتاه، أجاب ربا دعاه، يا أبتاه، من جنة الفردوس، مأواه يا أبتاه إلى جبريل ننعاه، فلما دفن، قالت فاطمة عليها السلام: يا أنس أطابت أنفسكم أن تحثوا على رسول الله صلى الله عليه وسلم التراب", "4462"], ["باب آخر ما تكلم به النبي صلى الله عليه وسلم", "حدثنا بشر بن محمد، حدثنا عبد الله، قال يونس: قال الزهري: أخبرني سعيد بن المسيب، في رجال من أهل العلم: أن عائشة قالت: كان النبي صلى الله عليه وسلم يقول وهو صحيح: «إنه لم يقبض نبي حتى يرى مقعده من الجنة، ثم يخير» فلما نزل به، ورأسه على فخذي غشي عليه، ثم أفاق فأشخص بصره إلى سقف البيت، ثم قال: «اللهم الرفيق الأعلى». فقلت: إذا لا يختارنا، وعرفت أنه الحديث الذي كان يحدثنا وهو صحيح، قالت: فكانت آخر كلمة تكلم بها: «اللهم الرفيق الأعلى»", "4463"], ["باب وفاة النبي صلى الله عليه وسلم", "حدثنا أبو نعيم، حدثنا شيبان، عن يحيى، عن أبي سلمة، عن عائشة، وابن عباس رضي الله عنهم: «أن النبي صلى الله عليه وسلم لبث بمكة عشر سنين، ينزل عليه القرآن وبالمدينة عشرا»", "4464"], ["باب وفاة النبي صلى الله عليه وسلم", "حدثنا عبد الله بن يوسف، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عروة بن الزبير، عن عائشة رضي الله عنها: «أن رسول الله صلى الله عليه وسلم توفي وهو ابن ثلاث وستين» قال ابن شهاب: وأخبرني سعيد بن المسيب مثله", "4466"], ["باب", "حدثنا قبيصة، حدثنا سفيان، عن الأعمش، عن إبراهيم، عن الأسود، عن عائشة رضي الله عنها، قالت: «توفي النبي صلى الله عليه وسلم ودرعه مرهونة عند يهودي بثلاثين»", "4467"], ["باب: كم غزا النبي صلى الله عليه وسلم؟", "حدثنا عبد الله بن رجاء، حدثنا إسرائيل، عن أبي إسحاق، قال: سألت زيد بن أرقم رضي الله عنه: كم غزوت مع رسول الله صلى الله عليه وسلم؟ قال: سبع عشرة، قلت: \" كم غزا النبي صلى الله عليه وسلم؟ قال: تسع عشرة \"", "4471"], ["باب: كم غزا النبي صلى الله عليه وسلم؟", "حدثنا عبد الله بن رجاء، حدثنا إسرائيل، عن أبي إسحاق، حدثنا البراء رضي الله عنه قال: «غزوت مع النبي صلى الله عليه وسلم خمس عشرة»", "4472"], ["باب: كم غزا النبي صلى الله عليه وسلم؟", "حدثني أحمد بن الحسن، حدثنا أحمد بن محمد بن حنبل بن هلال، حدثنا معتمر بن سليمان، عن كهمس، عن ابن بريدة، عن أبيه، قال: «غزا مع رسول الله صلى الله عليه وسلم ست عشرة غزوة»", "4473"]];
